function accounts(){return store.get('accounts')||{};}
/* ===== 클라우드(Cloudflare KV) 동기화 — 실패 시 로컬로 폴백 ===== */
let CLOUD=true,syncT=null;
async function cloudCall(body){
  if(!CLOUD&&body.action!=='login'&&body.action!=='signup'&&body.action!=='ensure')return null;  // [v4.18] 가입·복구도 항상 시도
  const ctrl=new AbortController(); const to=setTimeout(()=>ctrl.abort(),8000);   // 8초 넘으면 포기(무한 '확인 중' 방지)
  try{const r=await fetch('/api/accounts',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body),signal:ctrl.signal});
    if(!r.ok)return null;const j=await r.json();if(j&&j.err==='nostore'){CLOUD=false;return null;}
    /* [v11.0] 로그인·동기화 응답에 담긴 등급을 여기 한 곳에서 받는다.
       호출부마다 챙기면 한 곳만 빠져도 등급이 안 바뀌므로 입구를 하나로 둔다. */
    try{ if(j&&j.ok&&(j.tier!=null||j.lv!=null))tierSet(j); }catch(e){}
    return j;}
  catch{return null;}
  finally{clearTimeout(to);}
}
function cloudSync(){
  if(!currentUser)return;const acc=accounts()[currentUser];if(!acc)return;
  /* ══ [v13.2] 빈 상태는 아예 올리지 않는다 ═══════════════════════════════════
     서버에도 방어를 뒀지만, 애초에 보내지 않는 것이 낫다. 화면이 어떤 이유로든
     비어 있는 순간에 동기화가 돌면 멀쩡한 서버 사본이 위험해진다.
     로컬에 내용이 있는데 지금 화면이 비었다면 그건 '아직 안 불러온 상태'다. */
  try{
    const _live={holdings,cash,usdCash,acctList,acctBooks,tradeLog,watchFolders};
    if(!hasRealData(_live)){
      const _saved=store.get('user:'+currentUser);
      if(hasRealData(_saved)){
        try{ console.warn('[LIVE] 화면이 비어 있어 동기화를 건너뜁니다'); }catch(e){}
        return;
      }
    }
  }catch(e){}
  clearTimeout(syncT);
  syncT=setTimeout(()=>syncOnce(acc),_syncDelay());
}
/* ══ [v13.6] 서버 저장 실패를 알아챈다 ═══════════════════════════════════════
   예전에는 sync 응답을 버렸다. 서버가 stored:"fail" 을 돌려줘도 화면은 아무 일
   없다는 듯 넘어갔고, 사용자는 저장된 줄 알았다. 이 기기에는 남아 있으니 당장은
   괜찮지만, 기기를 바꾸면 그 사이 거래가 통째로 없다.
   실패하면 몇 초 뒤 다시 시도하고, 계속 실패하면 분명히 알린다. */
var _syncFail=0, _syncWarnAt=0;
function syncOnce(acc){
  const _cur=currentUser;
  cloudCall({action:'sync',id:_cur,pass:acc.pass,
    /* 폴더·종목메모·개인설정까지 자동 저장 — 기기를 바꿔 로그인해도 그대로 복원된다(수동 내보내기 불필요) */
    user:{watchlist,holdings,cash,usdCash,usdSettling,acctType,acctList,acctBooks,acctActive,sendLog,ipoPlans,tradeLog,tradeArchive,watchFolders,stockMemos,prefs:userPrefs,acctPass:acctPassHash,savedAt:Date.now()}})
  .then(j=>{
    if(j&&j.ok&&(j.stored==='usr'||j.stored==='kept')){ _syncFail=0; return; }
    if(j&&j.ok&&j.guarded){ _syncFail=0; return; }      // 서버가 지켜 준 경우 — 정상
    syncRetry(acc,_cur);
  })
  .catch(()=>{ syncRetry(acc,_cur); });
}
/* 실패했을 때 — 짧게 세 번 다시 시도하고, 그 뒤에는 알린 다음 천천히 계속 시도한다.
   포기하지 않는 것이 중요하다. 연결이 돌아오면 저절로 올라간다. */
function syncRetry(acc,uid){
  _syncFail++;
  const wait = _syncFail<=3 ? 1500*_syncFail : 60000;   // 1.5초·3초·4.5초 → 이후 1분마다
  if(_syncFail===4){
    const now=Date.now();
    if(now-_syncWarnAt>60000){
      _syncWarnAt=now;
      try{ toast('warn','서버에 저장하지 못했어요',
        '이 기기에는 남아 있습니다. 연결이 돌아오면 자동으로 다시 저장돼요'); }catch(e){}
    }
  }
  if(_syncFail>200)return;                              // 무한히 붙들지는 않는다
  clearTimeout(syncT);
  syncT=setTimeout(()=>{ try{ if(currentUser===uid)syncOnce(acc); }catch(e){} }, wait);
}
/* ══ [v9.73] 서버 저장 간격을 상황에 맞게 ══════════════════════════════════
   800ms 고정이라, 주문 화면에서 값을 조금씩 만지는 동안에도 계속 저장 요청이
   나갔다. KV 는 하루 쓰기 한도가 있으므로 조용할 때는 넉넉히 묶는다.
   화면을 닫거나 탭을 벗어날 때는 아래에서 즉시 한 번 밀어 넣으므로 유실은 없다. */
function _syncDelay(){
  /* ══ [v9.97] KV 쓰기가 첫 병목이다 ═══════════════════════════════════════
     Cloudflare 무료 KV 는 하루 쓰기 1,000회다. 사용자 한 명이 하루 20~60회를
     쓰므로 25명쯤에서 요청 한도(10만)보다 먼저 막힌다. 막히면 저장이 조용히
     실패해 '분명 샀는데 새로고침하면 없는' 증상이 된다 — 가장 나쁜 고장이다.
     서버가 알려 준 전체 사용률이 높으면 저장 간격을 늘려 쓰기를 아낀다.
     화면을 닫을 때는 즉시 밀어 넣으므로 데이터가 사라지지는 않는다. */
  try{
    if(document.hidden)return 300;              // 곧 사라질 수 있으니 빨리 보낸다
    const t=(typeof srvBudgetTier==='function')?srvBudgetTier():-1;
    if(t>=3)return 30000;                       // 한도 임박 — 30초에 한 번
    if(t>=2)return 15000;
    if(t>=1)return 8000;
    return 4000;
  }catch(e){ return 4000; }
}
/* 탭을 벗어나거나 앱을 닫을 때 밀린 저장을 즉시 보낸다 */
try{
  const flush=()=>{ try{ if(syncT){ clearTimeout(syncT); syncT=null; cloudSyncNow(); } }catch(e){} };
  document.addEventListener('visibilitychange',()=>{ if(document.hidden)flush(); });
  window.addEventListener('pagehide',flush);
}catch(e){}
function cloudSyncNow(){
  if(!currentUser)return; const acc=accounts()[currentUser]; if(!acc)return;
  try{ cloudCall({action:'sync',id:currentUser,pass:acc.pass,
    user:{watchlist,holdings,cash,usdCash,usdSettling,acctType,acctList,acctBooks,acctActive,sendLog,ipoPlans,tradeLog,tradeArchive,watchFolders,stockMemos,prefs:userPrefs,acctPass:acctPassHash,savedAt:Date.now()}}); }catch(e){}
}
function saveState(){ if(!currentUser)return; try{acctSnap();}catch(e){}   // [v4.40] 활성 계좌 장부 반영
  /* [v13.9] 저장 시각을 함께 남긴다 — 로컬과 서버 중 어느 쪽이 새것인지 가리는 근거 */
  const _next={watchlist,holdings,cash,usdCash,usdSettling,acctType,acctList,acctBooks,acctActive,sendLog,ipoPlans,tradeLog,tradeArchive,watchFolders,stockMemos,bookOrders,priceAlerts,prefs:userPrefs,acctPass:acctPassHash,savedAt:Date.now()};
  /* ══ [v13.1] 3겹 — 갑자기 텅 비는 저장을 감지한다 ═══════════════════════════
     계좌를 전부 해지하는 것처럼 정말 비우는 경우도 있으므로 막지는 않는다.
     다만 '있던 것이 사라지는' 저장이라면 직전 상태를 스냅샷으로 반드시 남긴다.
     그래야 무슨 일이 있어도 한 걸음 뒤로는 돌아갈 수 있다. */
  /* ══ [v13.4] 있던 것이 사라지는 저장은 서버 사본으로 되살릴 수 있게 알린다 ══
     로컬 스냅샷은 저장 공간을 잡아먹어 없앴다. 대신 서버(usr:<id>)가 백업이다.
     서버는 빈 것으로 덮이지 않으므로, 로컬이 비어도 서버 사본은 남아 있다. */
  try{
    const _prev=store.get('user:'+currentUser)||null;
    if(hasRealData(_prev)&&!hasRealData(_next)){
      console.warn('[LIVE] 데이터가 비워지는 저장 — 서버 사본은 그대로 유지됩니다');
    }
  }catch(e){}
  /* ══ [v13.3] 저장이 실패하면 반드시 알린다 ═══════════════════════════════════
     store.set 은 예외를 try/catch 로 삼킨다. 저장 공간이 차면 저장이 안 되는데도
     화면은 아무 일 없다는 듯 돌아가고, 새로고침하면 거래가 통째로 사라진다.
     조용한 실패가 가장 위험하다 — 실패하면 공간을 만들어 다시 시도하고,
     그래도 안 되면 사용자에게 분명히 알린다. */
  if(!saveUserSafe(currentUser,_next))return;
  cloudSync(); }
/* 저장을 확실히 한다. 실패하면 스냅샷을 비워 공간을 만들고 다시 시도한다. */
var _saveWarnAt=0;
function saveUserSafe(u,d){
  const key='user:'+u;
  /* ══ [v13.5] 다른 탭이 더 새 판을 썼으면 덮지 않는다 ═══════════════════════ */
  try{
    const cur=revGet(u);
    if(cur>_myRev){
      _myRev=cur;
      applyUser(u);                      // 저장소의 최신 내용으로 이 탭을 맞춘다
      try{ renderAll&&renderAll(); }catch(e){}
      const now=Date.now();
      if(now-_staleWarnAt>15000){
        _staleWarnAt=now;
        try{ toast('warn','다른 탭에서 먼저 저장했어요','최신 내용으로 화면을 맞췄습니다'); }catch(e){}
      }
      return false;                      // 이번 저장은 건너뛴다 — 남의 거래를 지우지 않는다
    }
  }catch(e){}
  let body;
  /* ══ [v13.4] ① 만들 수 없는 데이터는 저장하지 않는다 ═══════════════════════
     순환 참조나 이상한 값이 섞이면 JSON.stringify 가 예외를 던진다. 그대로
     두면 저장이 안 되는데 아무도 모른다. 여기서 잡아 알린다. */
  try{ body=JSON.stringify(d); }
  catch(e){
    try{ console.error('[LIVE] 저장할 데이터를 만들지 못했습니다:',e); }catch(e2){}
    try{ toast('warn','저장하지 못했어요','새로고침 후 다시 시도해 주세요'); }catch(e2){}
    return false;
  }
  if(!body||body.length<3){
    try{ console.error('[LIVE] 저장할 내용이 비어 있어 건너뜁니다'); }catch(e){}
    return false;
  }
  for(let tries=0;tries<6;tries++){
    try{
      localStorage.setItem(key,body);
      /* ② 쓴 뒤 다시 읽어 확인한다 — 브라우저가 조용히 잘라 넣는 경우가 있다 */
      const back=localStorage.getItem(key);
      if(back===body){ _myRev=revGet(u)+1; revSet(u,_myRev); return true; }
      try{ console.warn('[LIVE] 저장 결과가 다릅니다 — 다시 시도합니다'); }catch(e){}
      throw new Error('verify-failed');
    }
    catch(e){
      /* 공간 부족 — 다시 만들 수 있는 캐시부터 비운다 */
      let freed=false;
      ['stockAll','usPopCache','verLast','updSkip','usDyn1','tierCache'].forEach(k=>{
        try{ if(localStorage.getItem(k)!=null){ localStorage.removeItem(k); freed=true; } }catch(e2){}
      });
      /* 깨진 데이터 보관본도 마지막에는 비운다 */
      if(!freed){
        try{ Object.keys(localStorage).filter(k=>k.startsWith('broken:')).forEach(k=>{ localStorage.removeItem(k); freed=true; }); }catch(e2){}
      }
      if(!freed)break;
    }
  }
  /* 끝내 실패 — 조용히 넘어가지 않는다 */
  try{
    const now=Date.now();
    if(now-_saveWarnAt>20000){
      _saveWarnAt=now;
      toast('warn','저장 공간이 부족해 저장하지 못했어요',
        '브라우저 설정에서 이 사이트의 저장 공간을 확보하거나, 사용하지 않는 탭을 닫아 주세요');
    }
    console.error('[LIVE] 저장 실패 — 공간 부족');
  }catch(e){}
  return false;
}
/* [폴더] 관심종목 폴더 상태 */
let watchFolders=[]; let watchTab='all';
/* [v1.99] 관심종목 = 폴더 소속 종목. '전체' 가상 폴더 폐지.
   watchlist는 모든 폴더의 합집합으로 자동 동기화된다(순서는 기존 순서 유지 + 신규 뒤). */
function syncWatchUnion(){
  const set=new Set();watchFolders.forEach(f=>(f.codes||[]).forEach(c=>set.add(c)));
  const kept=watchlist.filter(c=>set.has(c));
  set.forEach(c=>{if(!kept.includes(c))kept.push(c);});
  watchlist=kept;
}
/* 기존 사용자 데이터 이전 — 폴더 밖 종목(옛 '전체' 전용)을 폴더로 승격 */
function migrateWatchModel(){
  let changed=false;
  const inF=new Set();watchFolders.forEach(f=>(f.codes||[]).forEach(c=>inF.add(c)));
  const orphans=watchlist.filter(c=>!inF.has(c));
  if(orphans.length){
    if(!watchFolders.length){
      watchFolders.push({id:'f'+Date.now().toString(36),name:'내 관심',icon:'⭐',codes:orphans.slice(),color:''});
    }else{
      let mf=watchFolders.find(f=>f.name==='미분류');
      if(!mf){mf={id:'f'+(Date.now()+1).toString(36),name:'미분류',icon:'📌',codes:[],color:''};watchFolders.push(mf);}
      orphans.forEach(c=>{if(!mf.codes.includes(c))mf.codes.push(c);});
    }
    changed=true;
  }
  syncWatchUnion();
  if(watchTab==='all'||!watchFolders.some(f=>f.id===watchTab))watchTab=watchFolders.length?watchFolders[0].id:'all';
  if(changed)saveState();
}
let watchSortMode='chg';   // 계정별 값은 reloadPerUser()에서 로드
let stockMemos={};          // [H2] 종목별 메모 — 계정 데이터로 클라우드 동기화
function applyUser(u){
  /* [v13.0] 로그인 직후에도 이용권 안내를 확인한다 — 세션 복원 경로와 별개다 */
  try{ setTimeout(()=>{ try{ checkTierInbox(); }catch(e){} }, 3000); }catch(e){}
  /* ══ [v13.3] 저장된 데이터가 깨졌을 때 ═══════════════════════════════════════
     store.get 은 JSON 해석에 실패하면 조용히 null 을 준다. 그러면 아래에서
     전부 기본값이 되고, 곧이어 saveState 가 그 빈 상태로 덮어써 깨진 원본마저
     사라진다. 깨졌다는 사실 자체를 알아채지 못하는 것이 문제다.
     [고침] 글자는 있는데 해석이 안 되면 '깨졌다'고 판단해, 원본을 따로 보관하고
     스냅샷에서 되살릴 것을 권한다. 원본을 지우지 않으므로 나중에 손으로도 살릴 수 있다. */
  try{
    const _raw=localStorage.getItem('user:'+u);
    if(_raw&&_raw.length>2){
      let _ok=true; try{ JSON.parse(_raw); }catch(e){ _ok=false; }
      if(!_ok){
        /* [v13.4] 시각을 붙이면 깨질 때마다 쌓여 공간을 먹는다 — 한 개만 둔다 */
        try{ localStorage.setItem('broken:'+u, _raw); }catch(e){}
        console.error('[LIVE] 저장된 데이터가 깨져 있습니다 — 원본을 broken: 키로 보관했습니다');
        /* ══ [v13.4] 깨진 뒤에는 '비었다'고 표시해 둔다 ═══════════════════════════
           깨진 직후 앱은 기본 계좌를 하나 만들어 저장한다. 그러면 잠시 뒤 서버에서
           되찾으려 할 때 '로컬에도 데이터가 있다'고 판단해 되찾기를 건너뛴다.
           실제로 그렇게 복구가 막혔다. 깨졌다는 사실을 따로 남겨, 되찾기가
           로컬을 무시하고 서버 것을 가져오게 한다. */
        _localBroken=true;
        setTimeout(()=>{
          try{
            toast('warn','저장된 데이터를 읽지 못했어요','서버에 저장된 기록에서 되살립니다');
            try{ pullFromServer(true); }catch(e){}
          }catch(e){}
        }, 2200);
      }
    }
  }catch(e){}
  try{ _myRev=revGet(u); }catch(e){}    /* [v13.5] 이 탭이 읽은 판번호 */
  const d=store.get('user:'+u)||{};
  bookOrders=Array.isArray(d.bookOrders)?d.bookOrders:[];
  priceAlerts=(d.priceAlerts&&typeof d.priceAlerts==='object')?d.priceAlerts:{};
  currentUser=u;
  watchlist=d.watchlist||['005930','000660','035420'];
  holdings=d.holdings||[];
  /* [v4.99] 저장된 값이 없으면 0원 — 임의로 1,000만원을 넣지 않는다 */
  cash=(d.cash!=null)?d.cash:0;
  usdCash=(d.usdCash!=null)?+d.usdCash:0;                       // [v4.29]
  acctType=(d.acctType&&ACCT_TYPES[d.acctType])?d.acctType:'general';   // [v4.32]
  /* [v4.40] 계좌 목록 복원. acctList 키 자체가 없는 예전 사용자만 자동 이전하고,
     키가 있는데 비어 있으면 '아직 개설하지 않은 상태'로 그대로 둔다(그래야 안내가 뜬다). */
  const hasNewFmt=Object.prototype.hasOwnProperty.call(d,'acctList');
  acctList=Array.isArray(d.acctList)?d.acctList.filter(a=>a&&a.id&&ACCT_TYPES[a.type]):[];
  acctBooks=(d.acctBooks&&typeof d.acctBooks==='object')?d.acctBooks:{};
  sendLog=Array.isArray(d.sendLog)?d.sendLog:[];                      // [v4.51] 이체 내역
  /* 예전에 개설된 계좌에는 번호가 없다 — 불러올 때 한 번 발급해 준다 */
  {let need=false; acctList.forEach(a=>{ if(!a.no){ a.no=acctNewNo(a.type); need=true; } });
   if(need)setTimeout(()=>{try{saveState();}catch(e2){}},400);}
  acctActive=(d.acctActive&&acctList.some(a=>a.id===d.acctActive))?d.acctActive:(acctList[0]?acctList[0].id:'');
  if(acctOpened()&&acctActive)acctLoad(acctActive);
  else if(!hasNewFmt)acctMigrate();                      // 예전 사용자 → 계좌 하나로 이전
  else { cash=0; usdCash=0; usdSettling=[]; holdings=[]; }   // 미개설 → 빈 상태
  /* ══ [v13.8] 화면 값과 활성 계좌가 짝이 맞음을 표시한다 ═══════════════════════
     [무엇이 잘못됐나] acctSnap 은 '펼친 계좌만 기록한다'는 안전장치를 두었는데
     (v13.2), 그 표시를 acctLoad 에서만 세웠다. 그런데 위 갈래에서 acctLoad 를
     타지 않는 경우(계좌 이전·미개설 뒤 개설 등)에는 표시가 비어 있어,
     그 뒤의 모든 저장이 장부를 건너뛰었다. 매수해도 장부에 남지 않는다.
     실제로 계좌 A 에서 매수한 뒤 B 로 갔다 오면 A 의 거래가 전부 사라졌다.
     [고침] applyUser 를 마친 시점의 화면 값은 정의상 활성 계좌의 값이다
     (saveState 가 둘을 함께 저장하므로). 여기서 짝을 확정한다. */
  try{ if(acctActive)_acctLoadedId=acctActive; }catch(e){}
  usdSettling=Array.isArray(d.usdSettling)?d.usdSettling:[];
  ipoPlans=d.ipoPlans||[];
  tradeLog=d.tradeLog||[]; tradeArchive=d.tradeArchive||{};
  /* [v4.5] 저장소·클라우드에서 온 계좌를 그대로 믿지 않는다.
     문자열·소수·NaN·음수 예수금, 수량 0 이하 보유, 중복된 종목 줄을 여기서 바로잡는다.
     (로그인 직후 조용히 수행 — 이후 총자산이 NaN·음수로 표시될 통로를 막는다) */
  try{sanitizeAccount(true);}catch(e){}
  watchFolders=Array.isArray(d.watchFolders)?d.watchFolders
    .filter(f=>f&&f.id&&f.name)
    .map(f=>({id:String(f.id),name:String(f.name).slice(0,12),codes:(f.codes||[]).filter(c=>watchlist.includes(c)),color:f.color||'',icon:f.icon||''})):[];
  migrateWatchModel();   // [v1.99] '전체' 폐지 — 폴더 밖 종목을 폴더로 승격
  watchTab='all';
  stockMemos=(d.stockMemos&&typeof d.stockMemos==='object')?d.stockMemos:{};
  loadPrefs(d.prefs||null);                    // 클라우드에 설정이 있으면 그걸 우선
  reloadPerUser();                             // 검색기록·최근본·정렬을 이 계정 것으로
  acctPassHash=d.acctPass||hash('0000');
  store.set('session',u);
}
/* [v4.1] 게스트 모드 폐지 — 회원가입·로그인해야 이용할 수 있다.
   예전 게스트 모드는 계정 없이 임시 데이터로 앱을 쓰게 했는데, 그 상태에서 쌓은
   투자내역·관심종목이 브라우저 저장소를 지우면 사라지고 기기를 옮기면 이어지지 않았다.
   로그인 화면을 닫을 수 없게 하고, 앱 초기화는 계정이 확정된 뒤에만 실행한다. */
function requireAuth(){
  currentUser=null;
  /* ══ [v4.94] 입장 화면이 걷힌 뒤에 로그인 창을 띄운다 ═══════════════════════
     예전에는 곧바로 띄워, 입장 화면이 아직 떠 있는데 그 위로 로그인 창이 먼저
     보였다(첨부 사진). 입장 화면이 사라졌다는 신호를 기다렸다가 연다.
     이미 걷혔거나 신호가 오지 않아도 1.6초 뒤에는 반드시 열어, 갇히지 않게 한다. */
  /* ══ [v8.3] 입장 화면이 걷히는 순간 홈이 잠깐 보이던 문제 ═══════════════════
     [무엇이 잘못됐나] 순서가 뒤집혀 있었다.
       ① 로그인 창은 '입장 화면이 사라졌다는 신호'를 기다렸다가 열고
       ② 그 아래에서 __boot.done() 으로 입장 화면을 걷었다
     그래서 입장 화면이 사라진 직후 ~ 로그인 창이 열리기 전까지 홈이 노출됐다.
     [고침] 로그인 창을 '먼저' 띄우고, 그다음에 입장 화면을 걷는다.
     로그인 창은 입장 화면(z-index 2000000)보다 아래에 있으므로 미리 열어 두어도
     보이지 않는다. 입장 화면이 걷히면 그 자리에 로그인 창이 이미 있다. */
  const g2=$('authGate');
  if(g2){g2.hidden=false;g2.classList.add('auth-force');}
  try{document.body.classList.add('locked');}catch(e){}
  try{oaBind();}catch(e){}
  try{ window.__gateShown=true; }catch(e){}   // [v8.4] 로그인 창을 거쳤음을 남긴다
  /* 창이 실제로 그려진 뒤에 입장 화면을 걷는다(한 프레임 뒤) */
  /* ══ [v14.0] 입장 화면을 걷지 않고 붙잡아 둔다 ═══════════════════════════════
     예전에는 여기서 __boot.done() 으로 입장 화면을 걷었다. 그래서 로그인이
     끝나지 않았는데도 로그인 창 뒤로 홈 화면이 그대로 드러났다.
     이제 막대는 100%까지 채우되 화면은 남기고(hold), 로그인 창을 그 위에 둔다.
     실제로 걷는 것은 로그인·회원가입이 끝난 뒤 unlockApp 에서 한다. */
  try{ document.body.classList.add('needs-auth'); }catch(e){}
  const finish=()=>{ try{window.__boot&&(__boot.step(4),__boot.step(5),__boot.step(6),__boot.hold());}catch(e){} };
  try{ requestAnimationFrame(()=>requestAnimationFrame(finish)); }catch(e){ finish(); }
}
function unlockApp(){
  /* ══ [v8.8] 순서가 또 뒤집혀 있었다 ═══════════════════════════════════════
     [영상에서 본 것] '확인 중…' 이 떠 있는데 배경에 이미 홈이 그려져 있었다.
     [왜] 이 함수가 ① 로그인 창을 닫고 ② 그 다음에 입장 화면을 띄웠다.
     ①과 ② 사이에 아무것도 없는 순간이 생겨 홈이 그대로 드러났다.
     [고침] 입장 화면을 '먼저' 덮고, 그것이 화면을 가린 뒤에 로그인 창을 닫는다.
     입장 화면은 z-index 2000000 이라 로그인 창(200)보다 위에 있으므로
     먼저 띄워도 어색하지 않고, 오히려 자연스럽게 이어진다. */
  const closeGate=()=>{
    const g=$('authGate');
    if(g){g.hidden=true;g.classList.remove('auth-force');}
    try{document.body.classList.remove('locked');}catch(e){}
  };
  /* ══ [v14.0] 이제 입장 화면은 인증이 끝날 때까지 계속 떠 있다 ═══════════════
     예전에는 로그인 창이 열릴 때 입장 화면을 걷었다가, 로그인이 끝나면 다시
     띄우는(replay) 구조였다. 그 사이사이에 홈이 드러나는 순간이 생겼다.
     지금은 애초에 걷지 않으므로 다시 띄울 필요가 없다.
     로그인 창만 조용히 닫고, 그 위를 덮고 있던 입장 화면을 마지막에 걷는다.
     순서: 로그인 창 닫기 → (입장 화면이 여전히 화면 전체를 덮음) → 걷기 */
  try{
    closeGate();
    try{ document.body.classList.remove('needs-auth'); }catch(e){}
    if(window.__boot){
      if(__boot.release)__boot.release();   // 붙잡아 둔 것을 풀어 준다
      else __boot.done();
      /* 화면이 준비될 시간을 조금 준 뒤 걷는다 — 덜 그려진 홈이 스치지 않게 */
      try{ requestAnimationFrame(()=>requestAnimationFrame(()=>{
        try{ __boot.release?__boot.release():__boot.done(); }catch(e){}
      })); }catch(e){}
    }
  }catch(e){ closeGate(); }
}
/* 계정 전환 시 개인 기록을 그 계정 키에서 다시 읽는다 */
function reloadPerUser(){
  try{srchHist=pget('srchHist',[]);}catch(e){srchHist=[];}
  try{viewHist=pget('viewHist',[]);}catch(e){viewHist=[];}
  watchSortMode=pget('watchSort',userPrefs.watchDefaultSort||'chg');
  idxFilter=pget('idxFilter','전체');
  try{priceTargets=pget('priceTargets',{})||{};}catch(e){priceTargets={};}
}
function seedTradeLog(){
  const day=(n)=>kstDayAgo(n);
  const mk=(date,code,name,side,qty,price,avg)=>{const amount=price*qty,fee=Math.round(amount*0.00015),tax=side==='sell'?Math.round(amount*0.0018):0;
    const pnl=side==='sell'?Math.round((price-avg)*qty-fee-tax):0,base=side==='sell'?avg*qty:amount;
    return{ts:Date.parse(date)||Date.now(),date,code,name,side,qty,price,amount,fee,tax,avg:avg||price,pnl,roi:base?pnl/base*100:0};};
  return [
    mk(day(8),'005930','삼성전자','buy',20,71000,71000),
    mk(day(5),'005930','삼성전자','sell',20,66200,71000),
    mk(day(3),'000660','SK하이닉스','buy',5,178000,178000),
    mk(day(1),'000660','SK하이닉스','sell',5,169500,178000),
    mk(day(1),'035420','NAVER','buy',6,205000,205000),
  ];
}

/* ══ [v6.7] 구글 간편 로그인 — 앱 쪽 ═══════════════════════════════════════
   버튼을 누르면 서버가 구글로 보내고, 돌아올 때 주소에 표(t)가 붙는다.
   그 표로 계정 정보를 한 번 받아 로그인 상태로 만든다. */
/* 구글 가입 완료 안내 — 아이디와 '비밀번호가 없다'는 사실을 알린다 */
function googleWelcome(j){ return welcomeBox({...j,google:1}); }
/* ══ [v7.5] 가입 완료 안내 — 구글·일반 모두 같은 창을 쓴다 ═══════════════════
   어느 쪽으로 가입했든 '내 아이디가 무엇인지'는 똑같이 중요하다. */
function welcomeBox(j){
  const id=String(j.id||''), em=String(j.email||'');
  const isG=!!j.google;
  const changed=isG&&em&&em!==id;   // 구글에서 대소문자가 바뀌었는지
  try{
    const ov=document.createElement('div');
    ov.className='overlay gw-gate';
    ov.innerHTML=`<div class="modal gw-box">
      <div class="gw-ic">🎉</div>
      <div class="gw-t">가입이 완료되었습니다</div>
      <div class="gw-d">${htmlEsc(j.name||id)}님, 환영합니다.</div>

      <div class="gw-id">
        <span>내 아이디</span>
        <b id="gwId">${htmlEsc(id)}</b>
        <button type="button" class="gw-copy" id="gwCopy">복사</button>
      </div>
      ${changed?`<div class="gw-note warn">입력하신 <b>${htmlEsc(em)}</b> 는
        모두 <b>소문자</b>로 바뀌어 아이디가 되었습니다. 대소문자를 구분하지 않으니
        그대로 적으셔도 로그인됩니다.</div>`:''}

      ${isG?`<div class="gw-pw">
        <div class="gw-pw-t">🔑 별도 비밀번호가 없습니다</div>
        <div class="gw-pw-d">구글 계정으로 가입하셔서 이 앱만의 비밀번호는 만들지 않았습니다.
          다음에도 로그인 화면에서 <b>「Google로 간편 로그인」</b> 버튼을 누르시면 됩니다.<br>
          아이디·비밀번호 칸에 입력해도 로그인되지 않습니다.</div>
      </div>`:`<div class="gw-pw plain">
        <div class="gw-pw-t">🔑 비밀번호를 잘 보관하세요</div>
        <div class="gw-pw-d">다음 로그인 때 <b>아이디와 비밀번호</b>가 필요합니다.
          비밀번호는 되돌릴 수 없는 형태로만 저장되어 저희도 알 수 없습니다.<br>
          잊으셨다면 <b>계정 설정</b>에서 바꾸시거나 새로 가입하셔야 합니다.</div>
      </div>`}

      <div class="gw-next">다음은 <b>내 계좌 → 계좌 개설</b>에서 거래에 쓸 계좌를 여시면 됩니다.</div>
      <button class="modal-btn" id="gwOk">확인했습니다</button>
    </div>`;
    document.body.appendChild(ov);
    const close=()=>{try{ov.remove();}catch(e){}};
    ov.querySelector('#gwOk').onclick=close;
    const cp=ov.querySelector('#gwCopy');
    if(cp)cp.onclick=async()=>{
      try{ await navigator.clipboard.writeText(id); cp.textContent='복사됨'; 
        setTimeout(()=>{try{cp.textContent='복사';}catch(e){}},1500); }
      catch(e){ toast('warn','복사하지 못했습니다','길게 눌러 직접 복사해 주세요'); }
    };
    /* 바깥을 눌러도 닫히지 않게 — 아이디를 꼭 보고 넘어가도록 */
  }catch(e){
    toast('buy','가입 완료',`아이디는 ${id} 입니다`);
  }
}
function oaBind(){
  const b=$('oaGoogle'); if(!b||b._w)return; b._w=1;
  b.onclick=()=>{
    b.disabled=true;
    b.querySelector('b').textContent='구글로 이동 중…';
    location.href='/api/oauth/google';
  };
}
var _oaDone=false;
async function oaConsume(){
  if(_oaDone)return false;                       // [v7.3] 한 번만 처리한다
  let q; try{ q=new URLSearchParams(location.search); }catch(e){ return false; }
  const g=q.get('glogin'); if(!g)return false;
  _oaDone=true;
  /* 주소창을 깨끗이 — 새로고침해도 다시 처리되지 않게 */
  try{ history.replaceState(null,'',location.pathname); }catch(e){}
  /* [v8.0] 처음 오는 사람 — 일반 가입과 같은 창을 열어 본인 정보를 받는다 */
  if(g==='new'){
    try{
      const r=await fetch('/api/oauth/google?pending=1',
        {cache:'no-store',credentials:'same-origin'});
      const j=await r.json();
      if(!j||!j.ok){ toast('warn','구글 가입 실패','인증 시간이 지났습니다. 다시 시도해 주세요.'); return false; }
      /* 로그인 창을 열고 회원가입 탭으로 이동 */
      try{ const gt=$('authGate'); if(gt){gt.hidden=false;gt.classList.add('auth-force');}
        document.body.classList.add('locked'); }catch(e){}
      try{ $('tabSignup').classList.add('on'); $('tabLogin').classList.remove('on');
        $('signupForm').hidden=false; $('loginForm').hidden=true; }catch(e){}
      suInit('google',{email:j.email,gname:j.gname});
      renderSu();
      toast('ok','조금만 더','가입을 마치려면 본인 정보와 약관 동의가 필요합니다');
      return true;                      // 로그인 창을 따로 띄우지 않는다
    }catch(e){ toast('warn','구글 가입 실패','잠시 후 다시 시도해 주세요.'); return false; }
  }
  if(g!=='ok'){
    if(g==='noconfig'){
      /* [v7.2] 서버에 열쇠가 없다 — 관리자가 손봐야 하는 문제다 */
      toast('warn','구글 로그인을 쓸 수 없습니다',
        '서버에 로그인 열쇠가 등록되지 않았습니다. 아이디·비밀번호로 로그인해 주세요.');
      try{ const b=$('oaGoogle');
        if(b){ b.disabled=true; b.querySelector('b').textContent='지금은 사용할 수 없습니다'; } }catch(e){}
      return false;
    }
    const why={state:'요청이 만료되었습니다. 다시 시도해 주세요.',
      token:'구글 인증에 실패했습니다.',profile:'구글 계정 정보를 받지 못했습니다.',
      email:'이메일이 확인되지 않은 구글 계정입니다.',
      error:'로그인 중 오류가 났습니다.'}[g]||'로그인에 실패했습니다.';
    toast('warn','구글 로그인 실패',why);
    return false;
  }
  /* [v7.4] 표는 이제 쿠키로 온다 — 주소의 t 는 없어도 된다 */
  try{
    const r=await fetch('/api/oauth/google?claim=1',
      {cache:'no-store',credentials:'same-origin'});
    const j=await r.json();
    if(!j||!j.ok){ toast('warn','구글 로그인 실패','인증 정보가 만료되었습니다. 다시 시도해 주세요.'); return false; }
    const accs=accounts();
    accs[j.id]={pass:j.pass,name:j.name||j.id,email:j.email||'',
      acctPass:(accs[j.id]&&accs[j.id].acctPass)||legacyHash('0000'),
      created:(accs[j.id]&&accs[j.id].created)||Date.now(),google:1};
    store.set('accounts',accs);
    if(j.user&&!store.get('user:'+j.id))store.set('user:'+j.id,j.user);
    applyUser(j.id); unlockApp(); initApp();
    /* ══ [v6.9] 발급된 아이디를 반드시 보여 준다 ═══════════════════════════
       [왜] 구글이 준 이메일을 소문자로 통일해 아이디로 쓴다. 대문자로 쓰던 분은
       자기 아이디가 무엇인지 모른 채 지나가게 된다. 토스트는 몇 초 뒤 사라져
       안내로 삼기에 약하다. 가입한 그 순간에 창을 띄워 분명히 알린다. */
    /* [v7.5] initApp() 이 화면을 다시 그리는 중에 창을 띄우면 곧바로 지워진다.
       화면이 자리 잡은 뒤에 띄운다. */
    if(j.created)setTimeout(()=>{try{googleWelcome(j);}catch(e){}},700);
    else toast('buy','로그인 완료',`${j.name||j.id}님, 환영합니다`);
    return true;
  }catch(e){ toast('warn','구글 로그인 실패','잠시 후 다시 시도해 주세요.'); return false; }
}
try{ oaBind(); }catch(e){}
/* [v7.3] 부팅에서 이미 처리하므로 여기서는 '세션이 살아 있는데 돌아온 경우'만 맡는다.
   (이미 로그인된 채로 다른 구글 계정으로 바꾼 경우) */
try{ setTimeout(()=>{ try{
  if(currentUser)oaConsume();
}catch(e){} },300); }catch(e){}

/* ===== 로그인/회원가입 UI ===== */
$('tabLogin').onclick=()=>{$('tabLogin').classList.add('on');$('tabSignup').classList.remove('on');$('loginForm').hidden=false;$('signupForm').hidden=true;};
$('tabSignup').onclick=()=>{$('tabSignup').classList.add('on');$('tabLogin').classList.remove('on');$('signupForm').hidden=false;$('loginForm').hidden=true;
  suInit('normal'); renderSu();};

/* ══ [v6.6] 회원가입 — 계좌 개설과 같은 단계식 ═══════════════════════════════
   [왜 바꿨나] 계좌 개설은 3단계로 나눠 약관까지 받는데 가입은 한 화면에 몰아넣고
   약관이 아예 없었다. 개인정보(이름·이메일)를 받으면서 동의를 구하지 않는 것도
   맞지 않는다. 절차를 맞추고, 이메일도 계좌 개설과 같이 '필수'로 통일한다.
     1단계 계정 정보 — 아이디·비밀번호
     2단계 본인 정보 — 이름·이메일
     3단계 약관 동의 — 필수 3종 + 선택 1종 */
var SU_STEP=1, suForm=null;
var SU_TERMS=[
  ['s1',1,'서비스 이용약관',
   '이 서비스는 학습용 모의투자입니다. 실제 매매·실제 자금 이동이 발생하지 않으며 화면의 모든 손익은 가상입니다. 투자 판단이나 권유를 목적으로 하지 않습니다.'],
  ['s2',1,'개인정보 수집·이용 동의',
   '수집 항목: 아이디, 비밀번호(암호화 저장), 이름, 생년월일, 휴대전화, 이메일.\n이용 목적: 계정 확인과 여러 기기에서 기록을 이어 보기 위함.\n보관 기간: 회원 탈퇴 시까지.\n비밀번호는 원문을 저장하지 않고 되돌릴 수 없는 형태로만 보관합니다. 동의를 거부할 수 있으나 그 경우 가입할 수 없습니다.'],
  ['s3',1,'만 14세 이상 확인',
   '만 14세 미만은 법정대리인 동의가 필요합니다. 이 모의 서비스는 실제 자금이 오가지 않지만, 개인정보 보호를 위해 만 14세 이상만 가입받습니다.'],
  ['s4',0,'마케팅 정보 수신 동의 (선택)',
   '새 기능과 학습 콘텐츠 안내를 앱 알림으로 받습니다. 동의하지 않아도 가입과 모든 기능 이용에 제한이 없습니다.']
];
/* ══ [v8.0] 구글도 같은 가입 절차를 밟는다 ═══════════════════════════════════
   [왜 바꾸나] 구글은 창 하나 없이 바로 계정이 만들어져, 실명·생년·연락처를
   받을 곳이 없었다. 그래서 계좌 개설 때 닉네임이 실명 칸에 들어가는 일이 생겼다.
   [어떻게] 구글 인증이 끝나면 '가입 완료' 대신 같은 가입 창을 연다.
   아이디·이메일은 구글이 준 값으로 고정하고, 본인 정보와 약관은 똑같이 받는다.
   여기서 받은 값이 프로필(닉네임)과 계좌 개설(실명·생년·연락처)에 그대로 쓰인다. */
var suMode='normal', suGoogle=null;
function suInit(mode,g){
  SU_STEP=(mode==='google')?2:1;          // 구글은 아이디·비밀번호가 이미 정해졌다
  suMode=mode||'normal'; suGoogle=g||null;
  suForm={id:(g&&g.email)||'',pw:'',pw2:'',
    name:(g&&g.gname)||'',                 // 이름(구글 이름을 첫 값으로 제안)
    realName:'',birth:'',phone:'',
    email:(g&&g.email)||'',terms:{}};
}
function suSave(){
  const g=(k)=>{const e=$(k);return e?e.value:'';};
  if(SU_STEP===1){ suForm.id=g('suId'); suForm.pw=g('suPw'); suForm.pw2=g('suPw2'); }
  if(SU_STEP===2){ suForm.email=g('suEmail');
    suForm.realName=g('suReal'); suForm.birth=g('suBirth'); suForm.phone=g('suPhone');
    suForm.name=suForm.realName; }        /* [v8.1] 이름 하나로 쓴다 */
}
function suGo(step){ suSave(); SU_STEP=step; renderSu(); }
function suSay(h){ const m=$('suMsg'); if(m)m.innerHTML=h||''; }
function renderSu(){
  if(!suForm)suInit(suMode);
  const st=$('suSteps'), bd=$('suBody'), nv=$('suNav');
  if(!st||!bd||!nv)return;
  /* 구글은 아이디·비밀번호가 이미 정해져 1단계를 건너뛴다 */
  const isG=(suMode==='google');
  const LB=isG?['본인 정보','약관 동의']:['계정 정보','본인 정보','약관 동의'];
  const base=isG?2:1;                       // 화면에 보이는 첫 단계의 실제 번호
  st.innerHTML=LB.map((t,i)=>{const n=base+i;
    return `<div class="su-st ${SU_STEP===n?'on':SU_STEP>n?'done':''}">
    <i>${SU_STEP>n?'✓':i+1}</i><span>${t}</span></div>`;}).join('');
  suSay('');
  if(SU_STEP===1){
    bd.innerHTML=`
      <div class="fld2"><label>아이디</label>
        <input id="suId" placeholder="4자 이상 · 영문·숫자" value="${htmlEsc(suForm.id)}" autocomplete="username"></div>
      <div class="fld2 two">
        <div><label>비밀번호</label><input id="suPw" type="password" autocomplete="new-password" placeholder="비밀번호" value="${htmlEsc(suForm.pw)}"></div>
        <div><label>비밀번호 확인</label><input id="suPw2" type="password" autocomplete="new-password" placeholder="다시 입력" value="${htmlEsc(suForm.pw2)}"></div></div>
      <div class="fld-help">8자 이상 · 영문 + 숫자 + 특수문자를 모두 포함해 주세요</div>
      <div class="pw-meter" id="suPwMeter" hidden></div>`;
    /* 비밀번호 세기 표시 — 입력하는 동안 무엇이 모자란지 알려 준다 */
    try{ const pw=$('suPw'); if(pw)pw.oninput=()=>{
      const mt=$('suPwMeter'); if(!mt)return;
      const v=pw.value||'';
      if(!v){mt.hidden=true;return;}
      const has=[/[a-z]/i.test(v),/[0-9]/.test(v),/[^a-zA-Z0-9]/.test(v),v.length>=8];
      const n=has.filter(Boolean).length;
      const lb=['매우 약함','약함','보통','강함','매우 강함'][n];
      mt.hidden=false;
      mt.innerHTML=`<div class="pwm-bar"><i style="width:${n*25}%" class="s${n}"></i></div>
        <div class="pwm-t">${lb} · ${['영문','숫자','특수문자','8자 이상'].filter((_,i)=>!has[i]).join(' · ')||'모두 충족'}</div>`;
    }; }catch(e){}
  }
  if(SU_STEP===2){
    const isG=(suMode==='google');
    bd.innerHTML=`
      ${isG?`<div class="su-gid"><span class="su-gbadge">G</span>
        <div><small>구글 계정으로 가입합니다</small><b>${htmlEsc(suForm.id)}</b>
        <i>이 주소가 그대로 아이디가 되고, 별도 비밀번호는 없습니다</i></div></div>`:''}
      <div class="fld2 two">
        <div><label>이름</label>
          <input id="suReal" placeholder="홍길동" value="${htmlEsc(suForm.realName)}" autocomplete="name" maxlength="20"></div>
        <div><label>생년월일</label>
          <input id="suBirth" placeholder="2000-01-01" value="${htmlEsc(suForm.birth)}" inputmode="numeric" maxlength="10"></div>
      </div>
      <div class="fld2 two">
        <div><label>휴대전화</label>
          <input id="suPhone" placeholder="010-1234-5678" value="${htmlEsc(suForm.phone)}" inputmode="tel" maxlength="13"></div>
        <div><label>이메일</label>
          <input id="suEmail" type="email" placeholder="you@example.com" value="${htmlEsc(suForm.email)}"
            autocomplete="email" ${isG?'readonly style="opacity:.7"':''}></div>
      </div>
      <div class="fld-help">입력하신 이름은 <b>계좌 개설</b>과 <b>클랜·친구</b>에 함께 쓰입니다.
        이 기기와 회원 계정에만 저장되며 외부로 나가지 않습니다.</div>`;
    /* 생년월일·전화번호를 입력하는 대로 다듬는다 */
    const b=$('suBirth');
    if(b)b.oninput=()=>{ const v=b.value.replace(/[^0-9]/g,'').slice(0,8);
      b.value=v.length>6?`${v.slice(0,4)}-${v.slice(4,6)}-${v.slice(6)}`
             :v.length>4?`${v.slice(0,4)}-${v.slice(4)}`:v; };
    const ph=$('suPhone');
    if(ph)ph.oninput=()=>{ const v=ph.value.replace(/[^0-9]/g,'').slice(0,11);
      ph.value=v.length>7?`${v.slice(0,3)}-${v.slice(3,7)}-${v.slice(7)}`
              :v.length>3?`${v.slice(0,3)}-${v.slice(3)}`:v; };
  }
  if(SU_STEP===3){
    const allOn=SU_TERMS.every(t=>suForm.terms[t[0]]);
    /* ══ [v7.1] 체크 아이콘이 안 보이던 이유 ═══════════════════════════════
       계좌 개설 약관은 .ae-ck 라는 동그란 표시 요소를 쓰는데,
       회원가입은 <i> 만 넣어 스타일이 하나도 걸리지 않았다.
       같은 클래스(.ae-ck · .ae-trow)를 그대로 써서 생김새를 맞춘다. */
    bd.innerHTML=`
      <button type="button" class="ae-all ${allOn?'on':''}" id="suAll">
        <span class="ae-ck">${allOn?'✓':''}</span><b>전체 동의</b>
        <small>선택 항목까지 모두 포함합니다</small></button>
      <div class="ae-terms">${SU_TERMS.map(t=>`
        <div class="ae-t">
          <button type="button" class="ae-trow ${suForm.terms[t[0]]?'on':''}" data-su-t="${t[0]}">
            <span class="ae-ck">${suForm.terms[t[0]]?'✓':''}</span>
            <span class="ae-tt"><i class="${t[1]?'req':'opt'}">${t[1]?'필수':'선택'}</i>${htmlEsc(t[2])}</span>
          </button>
          <button type="button" class="ae-tmore" data-su-m="${t[0]}">내용 보기 ▾</button>
          <div class="ae-tbox" id="suT-${t[0]}" hidden>${htmlEsc(t[3]).replace(/\n/g,'<br>')}</div>
        </div>`).join('')}</div>`;
    $('suAll').onclick=()=>{ const on=!SU_TERMS.every(t=>suForm.terms[t[0]]);
      SU_TERMS.forEach(t=>suForm.terms[t[0]]=on); renderSu(); };
    bd.querySelectorAll('[data-su-t]').forEach(b=>b.onclick=()=>{
      const k=b.dataset.suT; suForm.terms[k]=!suForm.terms[k]; renderSu(); });
    /* 내용 보기 — 계좌 개설과 같은 방식으로 접었다 편다 */
    bd.querySelectorAll('[data-su-m]').forEach(b=>b.onclick=()=>{
      const el=$('suT-'+b.dataset.suM); if(!el)return;
      el.hidden=!el.hidden;
      b.textContent=el.hidden?'내용 보기 ▾':'접기 ▴';
    });
  }
  nv.innerHTML=`${SU_STEP>(isG?2:1)?`<button class="modal-ghost" id="suPrev">이전</button>`:''}
    <button class="modal-btn" id="suNext">${SU_STEP<3?'다음':'가입하고 시작하기'}</button>`;
  const pv=$('suPrev'); if(pv)pv.onclick=()=>suGo(SU_STEP-1);
  $('suNext').onclick=()=>suNext();
}
async function suNext(){
  suSave();
  if(SU_STEP===1){
    const id=normId(suForm.id);
    if(id.length<4)return suSay('아이디는 4자 이상으로 정해 주세요.');
    if(!/^[a-z0-9_.-]+$/.test(id))return suSay('아이디는 영문·숫자와 <b>_ . -</b> 만 쓸 수 있습니다.');
    const ck=pwCheck(suForm.pw,id,suForm.name);
    if(!ck.ok)return suSay(ck.msg);
    if(suForm.pw!==suForm.pw2)return suSay('비밀번호가 일치하지 않습니다.');
    return suGo(2);
  }
  if(SU_STEP===2){
    const rn=String(suForm.realName||'').trim();
    if(rn.length<2)return suSay('이름(실명)을 2자 이상 입력해 주세요.');
    const bd=String(suForm.birth||'').trim();
    if(!/^\d{4}-\d{2}-\d{2}$/.test(bd))return suSay('생년월일을 <b>2000-01-01</b> 형식으로 입력해 주세요.');
    {const d=new Date(bd), y=+bd.slice(0,4);
     if(isNaN(d)||y<1900||d>new Date())return suSay('생년월일을 다시 확인해 주세요.');
     /* 만 14세 미만은 가입받지 않는다 — 약관에 적은 그대로 실제로 막는다 */
     const age=(Date.now()-d.getTime())/(365.25*864e5);
     if(age<14)return suSay('만 14세 이상만 가입할 수 있습니다.');}
    const ph=String(suForm.phone||'').replace(/[^0-9]/g,'');
    if(ph.length<10)return suSay('휴대전화 번호를 정확히 입력해 주세요.');
    const em=String(suForm.email||'').trim();
    if(!em)return suSay('이메일을 입력해 주세요.');
    if(!/^[^\s@]+@[^\s@]+\.[a-z]{2,}$/i.test(em))return suSay('이메일 형식이 올바르지 않습니다.');
    return suGo(3);
  }
  /* 3단계 — 필수 동의 확인 후 실제 가입 */
  const miss=SU_TERMS.filter(t=>t[1]&&!suForm.terms[t[0]]);
  if(miss.length)return suSay(`필수 항목 <b>${miss.length}가지</b>에 동의해야 가입할 수 있습니다.`);
  if(suMode==='google')await doGoogleSignupRun();
  else await doSignupRun();
}
/* [v8.0] 구글 가입 마무리 — 입력한 정보를 서버에 넘겨 계정을 만든다 */
async function doGoogleSignupRun(){
  const btn=$('suNext'); if(btn)btn.disabled=true;
  suSay('가입 처리 중…');
  try{
    const r=await fetch('/api/oauth/google?finish=1',{method:'POST',
      cache:'no-store',credentials:'same-origin',
      headers:{'content-type':'application/json'},
      body:JSON.stringify({name:suForm.name,realName:suForm.realName,
        birth:suForm.birth,phone:suForm.phone,terms:suForm.terms})});
    const j=await r.json();
    if(!j||!j.ok){
      if(btn)btn.disabled=false;
      return suSay(j&&j.err==='expired'
        ?'인증 시간이 지났습니다. 창을 닫고 다시 <b>Google로 간편 로그인</b>을 눌러 주세요.'
        :'가입을 마치지 못했습니다. 잠시 후 다시 시도해 주세요.');
    }
    const accs=accounts();
    accs[j.id]={pass:j.pass,name:j.name||j.id,email:j.email||'',
      acctPass:legacyHash('0000'),created:Date.now(),google:1,
      realName:suForm.realName,birth:suForm.birth,phone:suForm.phone,
      terms:{...suForm.terms,at:Date.now()}};
    store.set('accounts',accs);
    /* [v13.2] 로그인 경로와 같은 방어 — 빈 응답으로 기존 데이터를 덮지 않는다 */
    try{
      const _sv=j.user, _lo=store.get('user:'+j.id);
      if(_sv&&(hasRealData(_sv)||!hasRealData(_lo))){
        store.set('user:'+j.id,_sv);
      }
    }catch(e){}
    applyUser(j.id); unlockApp(); initApp();
    setTimeout(()=>{try{ welcomeBox({id:j.id,name:j.name,email:j.email,google:1}); }catch(e){}},700);
  }catch(e){
    if(btn)btn.disabled=false;
    suSay('가입 중 오류가 났습니다. 잠시 후 다시 시도해 주세요.');
  }
}
async function doSignupRun(){
  const id=normId(suForm.id), name=String(suForm.name).trim(), email=String(suForm.email).trim();
  const btn=$('suNext'); if(btn)btn.disabled=true;
  suSay('가입 처리 중…');
  try{
    const passH=await pwHash(suForm.pw), acctH=await pwHash('0000');
    acctPassHash=acctH;
    const cj=await cloudCall({action:'signup',id,pass:passH,name,email,acctPass:acctH,cash:0});
    if(!cj||!cj.ok){
      if(btn)btn.disabled=false;
      return suSay(cj&&cj.err==='exists'?'이미 존재하는 아이디입니다.'
        :cj&&cj.err==='weak'?'비밀번호가 보안 규칙을 만족하지 않습니다.'
        :'서버에 연결하지 못해 가입을 완료할 수 없습니다.<br><small>계정을 이 기기에만 만들면 다른 기기에서 로그인할 수 없어 막았습니다.</small>');
    }
    const accs=accounts();
    accs[id]={pass:passH,name,email,acctPass:acctH,created:Date.now(),
      realName:suForm.realName,birth:suForm.birth,phone:suForm.phone,
      terms:{...suForm.terms,at:Date.now()}};
    store.set('accounts',accs);
    /* 계좌는 만들지 않는다 — 가입과 계좌 개설은 별개 절차다(v4.99) */
    store.set('user:'+id,{watchlist:[],watchFolders:[],holdings:[],cash:0,usdCash:0,
      ipoPlans:[],acctPass:acctH,acctType:'general',acctActive:'',acctList:[],acctBooks:{}});
    applyUser(id); unlockApp(); initApp();
    /* [v7.5] 일반 가입도 같은 안내창을 띄운다 — 아이디를 분명히 알려 준다 */
    setTimeout(()=>{try{ welcomeBox({id,name,email,google:0}); }catch(e){}},700);
  }catch(e){
    if(btn)btn.disabled=false;
    suSay('가입 중 오류가 났습니다. 잠시 후 다시 시도해 주세요.');
  }
}
/* [v4.18] 아이디는 서버와 똑같은 규칙(소문자·공백제거)으로 정규화한다.
   기기마다 대소문자가 달라 '같은 아이디인데 다른 계정'이 되던 문제의 절반이 여기 있었다. */
function normId(v){return String(v==null?'':v).trim().toLowerCase();}

/* ══════════════════════════════════════════════════════════════════════════════
   [v13.1] 데이터 유실 방지 — 네 겹
   ─────────────────────────────────────────────────────────────────────────────
   [무엇이 일어났나] 로그인할 때 서버 응답을 로컬에 그대로 덮어썼다.
       if (j && j.user) store.set('user:'+id, j.user);
   서버는 데이터를 못 찾으면 user:{} 를 보내는데, 자바스크립트에서 빈 객체는
   참이라 이 조건을 통과한다. 그래서 서버가 한 번 삐끗하면
     ① 로컬이 {} 로 덮여 쓰이고
     ② applyUser 가 전부 기본값으로 되돌리고
     ③ saveState 가 그 빈 상태를 저장하고
     ④ cloudSync 가 서버로 밀어 올려 서버 사본까지 지운다
   한 번의 순간 장애로 되돌릴 수 없는 전손이 났다.

   [막는 방법]
     1겹 — 내용이 없는 서버 응답으로는 덮어쓰지 않는다
     2겹 — 저장할 때마다 직전 상태를 스냅샷으로 남긴다(5개 회전)
     3겹 — 갑자기 텅 비는 저장은 스냅샷을 먼저 확보한 뒤에만 진행
     4겹 — 서버도 내용 있는 기록을 빈 것으로 덮지 않는다(_worker.js)
   ══════════════════════════════════════════════════════════════════════════════ */

/* 이 데이터에 '지킬 만한 내용'이 있는가 */


/* ══════════════════════════════════════════════════════════════════════════════
   [v13.4] 서버에서 되찾기 — 로컬 스냅샷을 대신한다
   ─────────────────────────────────────────────────────────────────────────────
   로컬에 사본을 여러 벌 두면 저장 공간(약 5MB)을 잡아먹어, 정작 본 데이터를
   저장하지 못하는 더 큰 사고가 난다. 그래서 사본은 두지 않는다.
   대신 서버(usr:<id>)를 백업으로 쓴다. 서버는 빈 것으로 덮이지 않게 막아 두었으므로
   로컬이 비거나 깨져도 서버 사본은 남아 있다. 로컬과 서버가 서로의 백업이다.
     · 로컬이 비었는데 서버에 있으면  → 서버에서 가져온다
     · 서버가 비었는데 로컬에 있으면  → 로컬을 올린다
     · 양쪽 다 있으면                → 건드리지 않는다(사용자 판단이 우선)
   ══════════════════════════════════════════════════════════════════════════════ */
/* ══════════════════════════════════════════════════════════════════════════════
   [v13.5] 여러 탭에서 열었을 때 서로 덮어쓰는 것을 막는다
   ─────────────────────────────────────────────────────────────────────────────
   [무엇이 문제인가] 같은 브라우저에서 탭을 둘 열면 두 탭이 각자 데이터를 기억한다.
   탭 A 에서 매수하면 저장소가 바뀌지만, 탭 B 는 옛 값을 그대로 들고 있다.
   그 상태에서 탭 B 가 무엇이든 저장하면 탭 A 의 거래가 통째로 사라진다.
   실제로 시험해 보니 예수금·보유·거래기록이 전부 옛 값으로 되돌아갔다.
   [고침] 저장할 때마다 판번호를 하나씩 올린다. 저장 직전에 저장소의 판번호를
   확인해, 내가 읽은 뒤 남이 더 새 판을 썼다면 덮어쓰지 않고 화면을 다시 읽는다.
   먼저 쓴 사람이 이긴다 — 잃는 것은 '아직 반영되지 않은 이 탭의 조작'뿐이고,
   이미 저장된 거래가 사라지는 일은 없다. */
function revKey(u){ return 'rev:'+u; }
function revGet(u){ try{ return +(localStorage.getItem(revKey(u))||0)||0; }catch(e){ return 0; } }
function revSet(u,v){ try{ localStorage.setItem(revKey(u),String(v)); }catch(e){} }
var _myRev=0;                 /* 이 탭이 마지막으로 읽거나 쓴 판번호 */
var _staleWarnAt=0;
/* 다른 탭이 저장하면 브라우저가 알려 준다 — 즉시 따라잡는다 */
try{
  window.addEventListener('storage',(e)=>{
    try{
      if(!currentUser||!e||!e.key)return;
      if(e.key!==revKey(currentUser))return;
      const now=+(e.newValue||0)||0;
      if(now>_myRev){
        _myRev=now;
        applyUser(currentUser);
        try{ renderAll&&renderAll(); }catch(x){}
        try{ console.info('[LIVE] 다른 탭의 변경을 반영했습니다'); }catch(x){}
      }
    }catch(x){}
  });
}catch(e){}
var _localBroken=false;
async function pullFromServer(manual){
  try{
    if(!currentUser){ if(manual)toast('warn','로그인이 필요해요',''); return false; }
    const acc=accounts()[currentUser];
    if(!acc||!acc.pass){ if(manual)toast('warn','계정 정보를 찾지 못했어요',''); return false; }
    if(manual)toast('ok','서버에서 확인하는 중…','');
    const r=await fetch('/api/accounts',{method:'POST',headers:{'content-type':'application/json'},
      body:JSON.stringify({action:'login',id:currentUser,pass:acc.pass})});
    const j=await r.json();
    if(!j||!j.ok){ if(manual)toast('warn','서버에서 확인하지 못했어요','잠시 후 다시 시도해 주세요'); return false; }
    const srv=(j.user&&typeof j.user==='object')?j.user:null;
    /* 깨졌던 경우에는 지금 로컬(방금 만들어진 기본값)을 없는 것으로 본다 */
    const loc=_localBroken?null:store.get('user:'+currentUser);
    if(srv&&hasUserContent(srv)&&!hasUserContent(loc)){
      _localBroken=false;
      store.set('user:'+currentUser,srv);
      toast('ok','서버에서 데이터를 되찾았어요','화면을 새로 불러옵니다');
      setTimeout(()=>{ try{ location.reload(); }catch(e){} }, 900);
      return true;
    }
    if(srv&&hasUserContent(srv)&&hasUserContent(loc)){
      if(manual)toast('ok','이 기기의 데이터가 최신입니다','되찾을 필요가 없어요');
      return false;
    }
    if(hasRealData(loc)){
      try{ cloudSync(); }catch(e){}
      if(manual)toast('ok','이 기기의 데이터를 서버에 올렸어요','다른 기기에서도 쓰실 수 있습니다');
      return false;
    }
    if(manual)toast('warn','서버에도 저장된 기록이 없어요','');
    return false;
  }catch(e){ if(manual)toast('warn','서버에 연결하지 못했어요',''); return false; }
}
/* ══ [v13.9] '사람이 실제로 만든 내용'이 있는가 ═══════════════════════════════
   hasRealData 는 계좌 껍데기 하나만 있어도 참이다. 그런데 앱은 계좌가 없으면
   기본 계좌를 자동으로 만든다. 그래서 기기를 바꿔 로컬이 비어 있어도 부팅 직후엔
   '내용 있음'이 되어, 서버에서 되찾아 오는 길이 막혔다(실제로 잔고가 복구되지 않았다).
   여기서는 돈·보유·거래·메모·둘 이상의 계좌만 내용으로 센다. */
function hasUserContent(d){
  try{
    if(!d||typeof d!=='object')return false;
    if(Array.isArray(d.holdings)&&d.holdings.length)return true;
    if(Array.isArray(d.tradeLog)&&d.tradeLog.length)return true;
    if(+d.cash>0||+d.usdCash>0)return true;
    if(d.stockMemos&&Object.keys(d.stockMemos).length)return true;
    if(Array.isArray(d.acctList)&&d.acctList.length>1)return true;
    if(d.acctBooks&&Object.values(d.acctBooks).some(b=>b&&(+b.cash>0||(b.holdings||[]).length||(b.tradeLog||[]).length)))return true;
    return false;
  }catch(e){ return false; }
}
function hasRealData(d){
  try{
    if(!d||typeof d!=='object')return false;
    if(Array.isArray(d.acctList)&&d.acctList.length)return true;
    if(d.acctBooks&&Object.keys(d.acctBooks).length)return true;
    if(Array.isArray(d.holdings)&&d.holdings.length)return true;
    if(Array.isArray(d.tradeLog)&&d.tradeLog.length)return true;
    if(+d.cash>0||+d.usdCash>0)return true;
    if(Array.isArray(d.watchFolders)&&d.watchFolders.length)return true;
    if(d.stockMemos&&Object.keys(d.stockMemos).length)return true;
    return false;
  }catch(e){ return false; }
}
/* 얼마나 들어 있는지 — 스냅샷 고를 때 쓴다 */
function dataWeight(d){
  try{
    if(!d||typeof d!=='object')return 0;
    return (Array.isArray(d.acctList)?d.acctList.length*10:0)
      +(d.acctBooks?Object.keys(d.acctBooks).length*10:0)
      +(Array.isArray(d.holdings)?d.holdings.length*5:0)
      +(Array.isArray(d.tradeLog)?d.tradeLog.length:0)
      +((+d.cash>0)?5:0)+((+d.usdCash>0)?5:0);
  }catch(e){ return 0; }
}
/* ── 2겹: 스냅샷 ─────────────────────────────────────────────────────────
   저장 직전의 상태를 최대 5개까지 돌려 가며 남긴다. 무슨 일이 있어도
   바로 앞 상태로는 돌아갈 수 있게 하는 것이 목적이다. */
/* ══ [v13.2] 스냅샷 — 시간 회전 4장 + '가장 알찬 것' 1장 ═══════════════════════
   [앞 판의 결함] 새 스냅샷이 오래된 것을 순서대로 밀어내기만 했다. 그런데 데이터가
   비워진 뒤에도 계좌 껍데기 하나는 남아 '내용 있음'으로 판정되므로, 그 빈 상태가
   계속 쌓이면서 멀쩡한 스냅샷 5장을 전부 밀어냈다. 실제로 시험에서 그렇게 됐다.
   [고침] 마지막 칸(4번)은 회전에서 빼고 '지금까지 본 것 중 가장 알찬 상태'를 지킨다.
   이 칸은 더 알찬 것이 나타날 때만 바뀐다. 무슨 일이 있어도 최선의 상태 하나는
   반드시 남는다. */


$('doLogin').onclick=async()=>{
  const raw=$('liId').value.trim();
  const id=normId(raw),pw=$('liPw').value,m=$('liMsg');
  if(!id||!pw){m.textContent='아이디와 비밀번호를 입력하세요.';return;}
  const passH=await pwHash(pw), legacyH=legacyHash(pw);
  const local=accounts()[id]||accounts()[raw];
  const localOk=!!(local&&(local.pass===passH||local.pass===legacyH));
  m.textContent='확인 중…';
  const enter=(j)=>{
    const accs=accounts();
    accs[id]={pass:passH,name:(j&&j.name)||(local&&local.name)||id,email:(j&&j.email)||(local&&local.email)||'',
      acctPass:(j&&j.user&&j.user.acctPass)||(local&&local.acctPass)||legacyHash('0000'),
      created:(j&&j.created)||(local&&local.created)||Date.now()};
    store.set('accounts',accs);
    /* ══ [v13.1] 1겹 — 내용 없는 서버 응답으로는 덮어쓰지 않는다 ═══════════
       서버가 데이터를 못 찾으면 user:{} 를 보낸다. 빈 객체도 참이므로
       예전 조건(j&&j.user)은 이것을 통과해 로컬을 통째로 지웠다. */
    try{
      const _srv=(j&&j.user&&typeof j.user==='object')?j.user:null;
      const _loc=store.get('user:'+id)||null;
      /* ══ [v13.9] 양쪽 다 내용이 있으면 '더 새것'을 지킨다 ═══════════════════════
         [무엇이 위험했나] 서버에 내용이 있으면 무조건 로컬을 덮었다. 그런데
         매수한 뒤 동기화(4초 지연)가 나가기 전에 로그아웃하면, 서버에는 매수 전
         값이 남는다. 그 상태로 다시 로그인하면 서버의 옛 값이 이 기기의 새 거래를
         덮어써 매수가 통째로 사라졌다. 실제로 재현됐다.
         [고침] 저장 시각을 비교해 새것을 남긴다. 로컬이 새것이면 서버로 올린다. */
      const _st=+(_srv&&_srv.savedAt)||0, _lt=+(_loc&&_loc.savedAt)||0;
      if(_srv&&hasRealData(_srv)&&hasRealData(_loc)&&_lt>_st){
        /* 이 기기가 더 새것 — 지키고 서버에 올린다 */
        try{ setTimeout(()=>{ try{ cloudSyncNow&&cloudSyncNow(); }catch(e){} }, 1200); }catch(e){}
        try{ toast('ok','이 기기의 최신 기록을 지켰어요','서버에 다시 올립니다'); }catch(e){}
      }else if(_srv&&hasRealData(_srv)){
        store.set('user:'+id,_srv);
      }else if(_srv&&!hasRealData(_loc)){
        store.set('user:'+id,_srv);              // 양쪽 다 비었으면 그냥 받는다
      }else if(_srv&&hasRealData(_loc)){
        /* 서버는 비었는데 로컬에는 있다 — 로컬을 지키고 서버에 다시 올린다 */
        try{ setTimeout(()=>{ try{ cloudSync(); }catch(e){} }, 1500); }catch(e){}
        try{ toast('warn','서버 기록을 찾지 못했어요','이 기기의 데이터를 그대로 씁니다'); }catch(e){}
      }
    }catch(e){}
    applyUser(id);unlockApp();initApp();
  };
  /* ══ [v4.24] 로그인 복구 경로 ══════════════════════════════════════════
     서버 우선으로 확인하되, 서버가 '그런 계정 없음'이라고 하면 그대로 막지 않는다.
     서버 저장소가 순간 장애로 비었거나 키가 어긋난 경우 멀쩡한 사용자가
     자기 계정에서 통째로 잠기기 때문이다. 이 기기의 비밀번호가 맞으면
     로컬 데이터로 들여보낸 뒤, 그 데이터를 서버에 되올려 계정을 복원한다. */
  let cj=await cloudCall({action:'login',id,pass:passH,legacy:legacyH});
  if(cj&&cj.ok){ enter(cj); return; }
  if((!cj||cj.err==='nouser') && raw && raw!==id){          // 옛 대소문자 키 구제
    const cj2=await cloudCall({action:'login',id:raw,pass:passH,legacy:legacyH});
    if(cj2&&cj2.ok){ enter(cj2); return; }
    if(cj2&&cj2.ok===false)cj=cj2;
  }
  if(cj&&cj.err==='toomany'){
    m.innerHTML='로그인 시도가 너무 잦습니다. <b>15분 뒤</b>에 다시 시도해 주세요.'; return;
  }
  if(cj&&cj.err==='invalid'&&!localOk){
    /* [v6.9] 구글로 가입한 아이디로 비밀번호 로그인을 시도한 경우를 짚어 준다 */
    const la=accounts()[id];
    if((la&&la.google)||/@/.test(id)){
      m.innerHTML='이 아이디는 <b>구글 간편 로그인</b>으로 만든 계정입니다.<br>'
        +'아래 <b>「Google로 간편 로그인」</b> 버튼을 눌러 주세요.';
      return;
    }
    m.textContent='비밀번호가 올바르지 않습니다.'; return;
  }
  /* 서버가 계정을 못 찾았거나 응답이 없다 — 이 기기 자격증명으로 복구 시도 */
  if(localOk){
    enter(null);
    const kind=(cj&&cj.err==='nouser')?'서버에 계정이 없어 이 기기 기록으로 복구합니다'
              :'서버에 연결하지 못해 이 기기 기록으로 열었습니다';
    toast('warn','계정 복구 중',kind+' — 잠시 뒤 자동으로 서버에 저장됩니다.');
    cloudCall({action:'ensure',id,pass:passH,legacy:legacyH,
      name:(local&&local.name)||id,email:(local&&local.email)||'',
      acctPass:(local&&local.acctPass)||'',created:(local&&local.created)||Date.now(),
      user:store.get('user:'+id)||store.get('user:'+raw)||{}})
      .then(r=>{ if(r&&r.ok)toast('ok','계정 복구 완료','이제 다른 기기에서도 같은 아이디로 로그인할 수 있어요.'); });
    return;
  }
  if(cj&&cj.err==='nouser'){
    m.innerHTML='이 아이디로 저장된 계정을 찾지 못했습니다.<br>'
      +'<b>회원가입</b> 탭에서 새로 만들거나, 아래 <b>다른 주소·기기에서 쓰던 계정 복원</b>을 눌러 백업 코드로 되살릴 수 있어요.';
    return;
  }
  m.innerHTML='서버에 연결하지 못했고, 이 기기에도 저장된 계정이 없습니다.<br>잠시 후 다시 시도해 주세요.';
};
/* [v4.1] 게스트 진입 경로 제거 */
// 전체 종목 검사 버튼 연결($ 정의 이후·요소 존재 이후에 바인딩)
if($('saStart'))$('saStart').onclick=runStockAudit;
if($('laStart'))$('laStart').onclick=runLogoAudit;
if($('laStop'))$('laStop').onclick=()=>{laRun=false;$('laStop').hidden=true;$('laStart').hidden=false;};
if($('laReset'))$('laReset').onclick=()=>{
  /* [v3.3.1] toast 는 (종류, 제목, 내용) 3개 인자를 받는데 제목만 넘겨서
     화면에 'undefined / undefined' 가 찍혔다. 인자를 맞추고,
     새로고침을 요구하는 대신 그 자리에서 다시 그려 곧바로 재탐색되게 한다. */
  let n=0;
  try{ const st=window.__lgStat&&window.__lgStat(); n=st?((st.ok||0)+(st.fail||0)):0; }catch(e){}
  try{ window.__lgReset&&window.__lgReset(); }catch(e){}
  try{ document.querySelectorAll('.lgo').forEach(el=>{
    el.classList.remove('on','alt','fade'); el.style.backgroundImage=''; }); }catch(e){}
  safeRun('lgResetPaint',()=>{ if(currentView==='search')renderSearch(); else if(currentView==='watch')renderWatch(); });
  toast('buy','로고 캐시를 비웠습니다',(n?n.toLocaleString()+'종 판정을 지웠습니다. ':'')+'지금부터 전부 다시 찾습니다.');
};
if($('saStop'))$('saStop').onclick=()=>{saRun=false;$('saStop').hidden=true;$('saStart').hidden=false;};
/* ══ [v4.32] 계좌 개설 — 종류 선택 UI ══════════════════════════════════════ */
let suAcctSel='general';
/* [v6.5] 가입 화면에서 계좌 개설을 뺐으므로(v4.95) 이 함수는 쓰이지 않는다.
   호출부가 남아 있어도 조용히 넘어가도록 비워 둔다. */
function renderAcctPick(){ return; }
/* ══ [v6.8] 계정 설정 탭 ═══════════════════════════════════════════════════
   [무엇이 문제였나] 구글로 로그인하면 비밀번호를 모르는데, 계정 삭제가
   비밀번호를 물어봐서 '비밀번호가 올바르지 않습니다'로 막혔다(첨부 사진).
   구글 계정은 비밀번호 대신 아이디를 입력해 확인한다. */
function renderAcctSet(){
  const box=$('asInfo'); if(!box)return;
  const acc=(currentUser&&accounts()[currentUser])||{};
  const isG=!!acc.google;
  box.innerHTML=`
    <div class="as-kv"><span>아이디</span><b class="as-id">${htmlEsc(currentUser||'')}</b></div>
    <div class="as-kv"><span>이름</span><b>${htmlEsc(acc.realName||acc.name||'-')}</b></div>
    <div class="as-kv"><span>생년월일</span><b>${htmlEsc(acc.birth||'-')}</b></div>
    <div class="as-kv"><span>휴대전화</span><b>${htmlEsc(acc.phone||'-')}</b></div>
    <div class="as-kv"><span>이메일</span><b>${htmlEsc(acc.email||'-')}</b></div>
    <div class="as-kv"><span>로그인 방식</span><b>${isG?'<i class="as-g">Google 간편 로그인</i>':'아이디 · 비밀번호'}</b></div>
    <div class="as-kv"><span>가입일</span><b>${acc.created?new Date(acc.created).toLocaleDateString('ko-KR'):'-'}</b></div>
    ${isG?`<div class="as-note">
      <b>이메일 주소가 그대로 아이디</b>입니다. 대문자로 쓰셨더라도 모두 소문자로 저장됩니다.<br>
      <b>별도 비밀번호는 없습니다.</b> 로그인은 항상 <b>「Google로 간편 로그인」</b> 버튼으로 하세요 —
      아이디·비밀번호 칸에 입력해도 로그인되지 않습니다.
      <button type="button" class="as-inline" id="asCopyId">아이디 복사</button></div>`:''}`;
  /* 구글 계정은 비밀번호가 없으므로 변경 항목을 감춘다 */
  const pw=$('asPwChange');
  if(pw){
    const row=pw.closest('.as-row');
    if(row)row.hidden=isG;
    pw.onclick=()=>changeAcctPw();
  }
  const del=$('asDelete'); if(del)del.onclick=()=>deleteAccount();
  const cp=$('asCopyId');
  if(cp)cp.onclick=async()=>{
    try{ await navigator.clipboard.writeText(currentUser||''); toast('ok','복사했습니다',currentUser||''); }
    catch(e){ toast('warn','복사하지 못했습니다','길게 눌러 직접 복사해 주세요'); }
  };
}
/* 로그인 비밀번호 변경 */
async function changeAcctPw(){
  if(!currentUser)return;
  const cur=await askText('현재 비밀번호',{password:true,placeholder:'지금 쓰는 비밀번호'});
  if(!cur)return;
  const nw=await askText('새 비밀번호',{password:true,placeholder:'8자 이상 · 영문+숫자+특수문자'});
  if(!nw)return;
  const ck=pwCheck(nw,currentUser,(accounts()[currentUser]||{}).name);
  if(!ck.ok){toast('warn','바꿀 수 없습니다',ck.msg);return;}
  const nw2=await askText('새 비밀번호 확인',{password:true,placeholder:'다시 입력'});
  if(nw2!==nw){toast('warn','바꿀 수 없습니다','새 비밀번호가 일치하지 않습니다');return;}
  const curH=await pwHash(cur), curL=legacyHash(cur), newH=await pwHash(nw);
  const j=await cloudCall({action:'changepw',id:currentUser,pass:curH,legacy:curL,newPass:newH});
  if(!j||!j.ok){
    toast('warn','바꾸지 못했습니다',
      j&&(j.err==='wrongpass'||j.err==='invalid')?'현재 비밀번호가 올바르지 않습니다':'잠시 후 다시 시도해 주세요');
    return;}
  const accs=accounts(); if(accs[currentUser]){accs[currentUser].pass=newH; store.set('accounts',accs);}
  toast('buy','비밀번호를 바꿨습니다','다음 로그인부터 새 비밀번호를 쓰세요');
}
/* 계정 삭제 — 구글 계정은 아이디 입력으로 확인 */
async function deleteAccount(){
  if(!currentUser){toast('warn','로그인이 필요합니다','다시 로그인해 주세요');requireAuth();return;}
  const acc=accounts()[currentUser]||{};
  const isG=!!acc.google;
  if(!await askConfirm('계정 삭제',
    `'${currentUser}' 계정과 서버의 모든 데이터가 영구 삭제됩니다.\n되돌릴 수 없습니다.`,
    {okLabel:'영구 삭제',danger:true}))return;
  let body;
  if(isG){
    const t=await askText('삭제 확인',{placeholder:currentUser,
      html:`정말 지우시려면 아래에 아이디를 그대로 입력해 주세요.<br><b>${htmlEsc(currentUser)}</b>`});
    if(!t)return;
    if(String(t).trim().toLowerCase()!==String(currentUser).toLowerCase()){
      toast('warn','삭제 취소','아이디가 일치하지 않습니다');return;}
    body={action:'delete',id:currentUser,pass:acc.pass};   // 서버가 발급한 무작위 비밀번호
  }else{
    const pw=await askText('비밀번호 확인',{password:true,placeholder:'로그인 비밀번호'});
    if(!pw)return;
    body={action:'delete',id:currentUser,pass:await pwHash(pw),legacy:legacyHash(pw)};
  }
  const j=await cloudCall(body);
  if(!j||!j.ok){
    /* [v7.6] 서버가 준 코드를 그대로 보여 주면 무슨 뜻인지 알 수 없다 */
    const why={
      wrongpass:isG?'인증 정보가 만료되었습니다. 로그아웃 후 다시 로그인해 주세요'
                   :'비밀번호가 올바르지 않습니다',
      noacct:'서버에서 계정을 찾지 못했습니다. 잠시 후 다시 시도해 주세요',
      param:'요청 정보가 부족합니다. 다시 로그인 후 시도해 주세요',
      net:'서버에 연결하지 못했습니다'
    }[(j&&j.err)||'net']||'잠시 후 다시 시도해 주세요';
    toast('warn','삭제 실패',why);
    return;}
  const accs=accounts(); delete accs[currentUser]; store.set('accounts',accs);
  store.del('user:'+currentUser); store.del('session');
  toast('warn','계정이 삭제되었어요','이 기기에 저장된 거래 내역도 함께 지워집니다'); setTimeout(()=>location.reload(),700);
}
function setPmTab(t){document.querySelectorAll('#pmTabs button').forEach(b=>b.classList.toggle('on',b.dataset.pm===t));document.querySelectorAll('.pm-pane').forEach(p=>p.hidden=(p.id!=='pm-'+t));
  if(t==='data')try{renderAcctSet();}catch(e){}}
/* ══ [v2.3] 프로필 확장 — 아바타 · 내 통계 · 게스트 지원 ══ */
const AVATARS=['🐣','🐻','🐰','🦊','🐼','🐯','🦄','🐸','🐳','🚀','⭐','💎'];
function avatarOf(nm){return (userPrefs&&userPrefs.avatar)||String(nm||'?').slice(0,1).toUpperCase();}
function paintHeaderUser(){
  const nm=currentUser?((accounts()[currentUser]||{}).name||currentUser):'';
  if($('uName'))$('uName').textContent=nm;
  if($('uAv')){$('uAv').textContent=avatarOf(nm);
    $('uAv').style.background=(userPrefs&&userPrefs.avColor)||'';}   // [v4.19]
  if($('pmAv'))$('pmAv').style.background=(userPrefs&&userPrefs.avColor)||'';
}
const AV_COLORS=['','#6366f1','#0ea5e9','#10b981','#f59e0b','#ef4444','#ec4899','#8b5cf6','#64748b'];
/* [v4.19] 아바타 배경색 */
function renderAvColors(){
  const g=$('avColors'); if(!g)return;
  const cur=(userPrefs&&userPrefs.avColor)||'';
  g.innerHTML=AV_COLORS.map(c=>'<button class="avc '+(cur===c?'on':'')+'" data-c="'+c+'" style="'+(c?('background:'+c):'')+'">'+(c?'':'기본')+'</button>').join('');
  g.querySelectorAll('button').forEach(b=>b.onclick=()=>{
    userPrefs=userPrefs||{}; userPrefs.avColor=b.dataset.c;
    try{savePrefs();}catch(e){}
    renderAvColors(); try{paintHeaderUser();}catch(e){}
    const av=$('pmAv'); if(av)av.style.background=b.dataset.c||'';
  });
}
function renderAvGrid(nm){
  const g=$('avGrid');if(!g)return;
  const cur=userPrefs&&userPrefs.avatar;
  g.innerHTML=AVATARS.map(a=>`<button class="av-o ${cur===a?'on':''}" data-av="${a}">${a}</button>`).join('')
    +`<button class="av-o txt ${!cur?'on':''}" data-av="">${String(nm||'?').slice(0,1).toUpperCase()}<i>이니셜</i></button>`;
  g.querySelectorAll('button').forEach(b=>b.onclick=()=>{
    userPrefs.avatar=b.dataset.av||'';if(!userPrefs.avatar)delete userPrefs.avatar;
    savePrefs();renderAvGrid(nm);
    $('pmAv').textContent=avatarOf(nm);paintHeaderUser();
    toast('buy','아바타 변경',b.dataset.av||'이니셜');});
}
function renderPmStats(){
  try{
    const totEval=holdings.reduce((a,h)=>a+hEvalKRW(h),0);
    const cost=holdings.reduce((a,h)=>a+hCostKRW(h),0);
    const pnl=totEval-cost,rate=cost?pnl/cost*100:0;
    const set=(id,v,cls)=>{const el=$(id);if(el){el.textContent=v;if(cls!==undefined)el.className='num '+cls;}};
    set('psAssets',KRW(cash+totEval)+'원');
    set('psPnl',signed(pnl),dirOf(pnl));set('psRate',pctS(rate),dirOf(pnl));
    set('psCash',KRW(cash)+'원');
    set('psHold',holdings.length+'종목');set('psWatch',watchlist.length+'종목');set('psFolder',watchFolders.length+'개');
    set('psTrades',tradeLog.length.toLocaleString()+'건');   // [v2.5] 실제 체결 기록
    /* ══ [v4.99] 가입 당일인데 '가입 7일차' 배지가 붙던 이유 ═══════════════════
       firstUseAt 은 '이 브라우저를 처음 쓴 날'이다. 계정 가입일이 아니다.
       그래서 예전 사용자가 쓰던 브라우저에서 새로 가입하면, 그 브라우저의 옛 날짜를
       그대로 물려받아 하루 만에 7일·30일 배지가 붙었다.
       → 계정에 기록된 가입일(created)을 쓴다. 없으면 오늘 가입한 것으로 본다. */
    /* ══ [v6.0] 여기서 계정이 통째로 날아가고 있었다 ═══════════════════════════
       accounts()[currentUser] 가 없으면 빈 객체 {} 를 받는데, 그것을 그대로
       계정 자리에 저장했다. 비밀번호(pass)가 사라진 계정이 만들어지고,
       그 뒤로 서버가 나를 알아보지 못해 클랜·친구·송금이 전부 'auth' 로 막혔다.
       → 이미 있는 계정에만 가입일을 덧붙이고, 없으면 저장하지 않는다. */
    let d0=0;
    try{ const all=accounts(), acc=all[currentUser];
      d0=(acc&&+acc.created)||0;
      if(!d0&&acc){ d0=Date.now(); acc.created=d0; all[currentUser]=acc; store.set('accounts',all); }
      if(!d0)d0=Date.now();
    }catch(e){ d0=Date.now(); }
    const days=d0?Math.max(1,Math.ceil((Date.now()-d0)/86400000)):0;
    set('psDays',days?('D+'+days+'일'):'—');
    /* ══ [v4.19] 매매 성적 · 투자 성향 · 배지 ══════════════════════════════
       기존 프로필은 자산 숫자 9칸이 전부라 '내가 어떻게 하고 있는지'를 알 수 없었다.
       매도 기록에서 승률·최고·최저·수수료·평균보유일을 뽑고, 그것으로 성향을 진단한다. */
    const sells=tradeLog.filter(t=>t&&t.side==='sell');
    const wins=sells.filter(t=>(+t.pnl||0)>0), losses=sells.filter(t=>(+t.pnl||0)<0);
    const realized=sells.reduce((a,t)=>a+(+t.pnl||0),0);
    const feeSum=tradeLog.reduce((a,t)=>a+(+t.fee||0)+(+t.tax||0),0);
    const best=sells.length?Math.max(...sells.map(t=>+t.pnl||0)):0;
    const worst=sells.length?Math.min(...sells.map(t=>+t.pnl||0)):0;
    set('psReal',signed(realized),dirOf(realized));
    set('psWin',sells.length?Math.round(wins.length/sells.length*100)+'%':'—',
        sells.length?dirOf(wins.length*2-sells.length):'');
    set('psWinN',wins.length+'건'); set('psLossN',losses.length+'건');
    set('psBest',sells.length?signed(best):'—',dirOf(best));
    set('psWorst',sells.length?signed(worst):'—',dirOf(worst));
    set('psFee',KRW(Math.round(feeSum))+'원');
    /* 평균 보유일 — 종목별 첫 매수 → 매도 간격 */
    const firstBuy={},spans=[];
    tradeLog.slice().sort((a,b)=>(a.ts||0)-(b.ts||0)).forEach(t=>{
      if(!t||!t.code)return;
      if(t.side==='buy'){if(firstBuy[t.code]==null)firstBuy[t.code]=t.ts||0;}
      else if(firstBuy[t.code]!=null){spans.push(Math.max(0,((t.ts||0)-firstBuy[t.code])/86400000));delete firstBuy[t.code];}});
    set('psHoldDays',spans.length?(spans.reduce((a,b)=>a+b,0)/spans.length).toFixed(1)+'일':'—');
    const cnt={};tradeLog.forEach(t=>{if(t&&t.code)cnt[t.code]=(cnt[t.code]||0)+1;});
    const top=Object.entries(cnt).sort((a,b)=>b[1]-a[1])[0];
    set('psTop',top?(((byCode[top[0]]||{}).name||top[0])+' '+top[1]+'회'):'—');
    renderPmStyle({sells:sells.length,win:sells.length?wins.length/sells.length:0,
      span:spans.length?spans.reduce((a,b)=>a+b,0)/spans.length:0,
      trades:tradeLog.length,days,hold:holdings.length,watch:watchlist.length,
      realized,cashRatio:(cash+totEval)?cash/(cash+totEval):1});
    renderPmBadges({trades:tradeLog.length,days,win:sells.length?wins.length/sells.length:0,
      sells:sells.length,watch:watchlist.length,folders:watchFolders.length,realized,hold:holdings.length});
  }catch(e){}
}
/* [v4.32] 프로필의 계좌 카드 — 종류·혜택 확인과 변경 */
function renderPmAcct(){
  const box=$('pmAcctBox'); if(!box)return;
  const a=ACCT_TYPES[acctType]||ACCT_TYPES.general;
  box.innerHTML=`<div class="acct-card"><div class="acct-card-h"><i>${a.ic}</i>
      <div><b>${a.n}</b><span>${currentUser||''} · 개설 완료</span></div>
      <button class="acct-chg" id="pmAcctChg">변경</button></div>
    <div class="acct-kv"><span>국내 수수료</span><b>${(FEE_RATE_BASE*a.feeKr*100).toFixed(4)}%</b></div>
    <div class="acct-kv"><span>해외 수수료</span><b>${(US_FEE_BASE*a.feeUs*100).toFixed(2)}%</b></div>
    <div class="acct-kv"><span>환전 우대</span><b>${Math.round((a.fxPref!=null?a.fxPref:0.95)*100)}%</b></div>
    <div class="acct-kv"><span>연 납입한도</span><b>${a.limit?KRW(a.limit)+'원':'없음'}</b></div>
    <div class="acct-tags">${a.pros.map(x=>`<span class="acct-pro">✓ ${x}</span>`).join('')}</div></div>
    <div id="pmAcctPick" hidden></div>`;
  /* ══ [v4.94] 개설하지 않은 계좌로 바뀌던 심각한 결함 ═══════════════════════
     [무엇이 잘못됐나] 이 화면은 계좌 '종류'(acctType)만 바꿨다. 그런데 acctType 은
     원래 '지금 활성인 계좌를 따라가는 값'이다(acctLoad 에서 매번 덮어쓴다).
     그래서 개설한 적 없는 IRP 를 골라도 그대로 적용됐고, 수수료·한도까지 바뀌었다.
     실제 계좌 목록(acctList)과 어긋난 상태가 되어 잔고·주문 기준이 뒤엉킨다.
     [고침] 개설한 계좌 중에서만 고르게 하고, 고르면 진짜 '계좌 전환'을 한다.
     개설하지 않은 종류는 눌리지 않게 하고, 어디서 개설하는지 알려 준다. */
  $('pmAcctChg').onclick=()=>{
    const p=$('pmAcctPick');
    if(!p.hidden){p.hidden=true;return;}
    p.hidden=false;
    const mine=Array.isArray(acctList)?acctList:[];
    if(mine.length<=1){
      p.innerHTML=`<div class="pm-note">개설한 계좌가 ${mine.length}개뿐입니다.
        계좌를 더 만들려면 <b>내 계좌 → 계좌 개설</b>에서 진행해 주세요.</div>
        <button class="acct-open-go" id="pmAcctOpen">내 계좌로 이동</button>`;
      const go=$('pmAcctOpen');
      if(go)go.onclick=()=>{ try{$('profileGate').hidden=true;}catch(e){} try{showView('account');}catch(e){} };
      return;
    }
    p.innerHTML=`<div class="acct-pick">${mine.map(a=>{const t=ACCT_TYPES[a.type]||ACCT_TYPES.general;
      const on=a.id===acctActive;
      return `<button type="button" class="acct-chip ${on?'on':''}" data-pacct="${a.id}">
        <i>${t.ic}</i><b>${t.n}</b><span class="acct-chip-sub">${KRW(intOf((acctBooks[a.id]||{}).cash,on?cash:0))}원</span></button>`;}).join('')}</div>
      <div class="pm-note">개설한 계좌끼리만 전환됩니다. 계좌마다 예수금·보유 종목이 따로 관리돼요.<br>
        새 계좌는 <b>내 계좌 → 계좌 개설</b>에서 만들 수 있습니다.</div>`;
    p.querySelectorAll('[data-pacct]').forEach(b=>b.onclick=()=>{
      const id=b.dataset.pacct;
      if(id===acctActive){ toast('on','이미 쓰고 있는 계좌','');return; }
      if(!acctList.some(x=>x.id===id)){ toast('warn','전환할 수 없습니다','개설되지 않은 계좌입니다');return; }
      acctSwitch(id);
      renderPmAcct();
    });
  };
}
/* 투자 성향 진단 — 거래빈도·보유기간·현금비중으로 4축을 매긴다 */
function renderPmStyle(s){
  const box=$('pmStyleBox'); if(!box)return;
  if(!s.trades){box.innerHTML='<div class="pm-note">아직 매매 기록이 없어요. 몇 번 거래해 보면 성향을 분석해 드립니다.</div>';return;}
  const perDay=s.days?s.trades/s.days:s.trades;
  const axes=[
    ['매매 빈도', Math.min(100,Math.round(perDay/1.5*100)), perDay>=1.2?'단타 성향':perDay>=0.4?'적당한 빈도':'느긋한 매매'],
    ['보유 기간', Math.min(100,Math.round((s.span/20)*100)), s.span>=10?'중장기 보유':s.span>=3?'스윙':'초단기'],
    ['현금 비중', Math.round(s.cashRatio*100), s.cashRatio>=.6?'보수적':s.cashRatio>=.25?'균형':'공격적'],
    ['분산 정도', Math.min(100,Math.round(s.hold/10*100)), s.hold>=8?'넓게 분산':s.hold>=4?'적당히 분산':'집중 투자'],
  ];
  const label=perDay>=1.2?(s.cashRatio<.25?'⚡ 공격적 단타형':'🔥 활발한 단타형')
            :s.span>=10?'🌳 장기 투자형':(s.cashRatio>=.6?'🛡 신중한 관망형':'⚖ 균형 스윙형');
  box.innerHTML=`<div class="pm-style-label">${label}</div>`
    +axes.map(([n,v,t])=>`<div class="pm-ax"><span>${n}</span>
      <i><b style="width:${Math.max(4,Math.min(100,v))}%"></b></i><em>${t}</em></div>`).join('')
    +`<div class="pm-note">최근 매매 기록으로 추정한 참고 지표입니다.</div>`;
}
/* 활동 배지 — 달성한 것만 색이 들어온다 */
function renderPmBadges(s){
  const box=$('pmBadges'); if(!box)return;
  const B=[
    ['🌱','첫 걸음','첫 거래를 마쳤어요',s.trades>=1],
    ['📘','기록가','거래 20건 달성',s.trades>=20],
    ['🏦','베테랑','거래 100건 달성',s.trades>=100],
    ['⭐','수집가','관심종목 10종 이상',s.watch>=10],
    ['🗂','정리왕','관심 폴더 3개 이상',s.folders>=3],
    ['🧺','분산 투자','보유 5종목 이상',s.hold>=5],
    ['🎯','승률왕','매도 10건 이상·승률 60%↑',s.sells>=10&&s.win>=.6],
    ['💰','수익 실현','실현손익 플러스',s.realized>0],
    ['📅','일주일','가입 7일차',s.days>=7],
    ['🗓','한 달','가입 30일차',s.days>=30],
  ];
  const got=B.filter(b=>b[3]).length;
  box.innerHTML=`<div class="pm-badge-n">${got} / ${B.length} 획득</div>`
    +B.map(([ic,t,d,on])=>`<div class="pm-badge ${on?'on':''}" title="${d}"><i>${ic}</i><b>${t}</b><span>${d}</span></div>`).join('');
}
function openProfile(){
  const guest=!currentUser;
  const acc=guest?{}:(accounts()[currentUser]||{});
  const nm=guest?((userPrefs&&userPrefs.nick)||'게스트'):(acc.name||currentUser);
  $('pmAv').textContent=avatarOf(nm);$('pmName').textContent=nm;
  $('pmId').textContent=guest?'게스트 · 이 브라우저에만 저장':'@'+currentUser;
  /* [v8.1] 이름 하나 — 계좌 개설에 쓴 이름(realName)을 우선한다 */
  $('pmNameIn').value=guest?((userPrefs&&userPrefs.nick)||''):(acc.realName||acc.name||'');
  $('pmEmailIn').value=guest?'':(acc.email||'');
  if($('pmBioIn'))$('pmBioIn').value=(userPrefs&&userPrefs.bio)||'';
  /* [v4.19] 프로필 첫 화면 요약 카드 — 아이디만 덩그러니 있던 자리를 채운다 */
  try{
    const hero=$('pmHero');
    if(hero){
      let ev=0;(holdings||[]).forEach(x=>{const st=byCode[x.code]||{};ev+=((st.price!=null?st.price:x.avg)||0)*(x.qty||0);});
      const tot=(cash||0)+ev, base=(holdings||[]).reduce((a,x)=>a+(x.avg||0)*(x.qty||0),0);
      const pnl=ev-base, rate=base?pnl/base*100:0;
      /* ══ [v4.99] 가입 당일인데 '가입 7일차' 배지가 붙던 이유 ═══════════════════
       firstUseAt 은 '이 브라우저를 처음 쓴 날'이다. 계정 가입일이 아니다.
       그래서 예전 사용자가 쓰던 브라우저에서 새로 가입하면, 그 브라우저의 옛 날짜를
       그대로 물려받아 하루 만에 7일·30일 배지가 붙었다.
       → 계정에 기록된 가입일(created)을 쓴다. 없으면 오늘 가입한 것으로 본다. */
    /* ══ [v6.0] 여기서 계정이 통째로 날아가고 있었다 ═══════════════════════════
       accounts()[currentUser] 가 없으면 빈 객체 {} 를 받는데, 그것을 그대로
       계정 자리에 저장했다. 비밀번호(pass)가 사라진 계정이 만들어지고,
       그 뒤로 서버가 나를 알아보지 못해 클랜·친구·송금이 전부 'auth' 로 막혔다.
       → 이미 있는 계정에만 가입일을 덧붙이고, 없으면 저장하지 않는다. */
    let d0=0;
    try{ const all=accounts(), acc=all[currentUser];
      d0=(acc&&+acc.created)||0;
      if(!d0&&acc){ d0=Date.now(); acc.created=d0; all[currentUser]=acc; store.set('accounts',all); }
      if(!d0)d0=Date.now();
    }catch(e){ d0=Date.now(); }
      const days=d0?Math.max(1,Math.ceil((Date.now()-d0)/86400000)):1;
      hero.innerHTML='<div class="pmh-top"><b>'+KRW(Math.round(tot))+'원</b><span>총자산</span></div>'
        +'<div class="pmh-row"><span class="'+dirOf(pnl)+'">'+signed(pnl)+' ('+pctS(rate)+')</span>'
        +'<span>보유 '+holdings.length+' · 관심 '+watchlist.length+' · D+'+days+'</span></div>';
    }
  }catch(e){}
  try{renderAvColors();}catch(e){}
  try{renderPmAcct();}catch(e){}
  const em=$('pmEmailIn');if(em)em.closest('.fld2').style.display=guest?'none':'';
  if($('pmPw'))$('pmPw').value='';if($('pmAcct'))$('pmAcct').value='';
  $('pmProfileMsg').textContent='';$('pmSecMsg').textContent='';$('pmDataMsg').textContent='';
  /* 게스트: 보안·계정이전 숨기고 로그인 유도 카드 표시 */
  document.querySelectorAll('#pmTabs button').forEach(b=>{
    if(b.dataset.pm==='security'||b.dataset.pm==='data')b.style.display=guest?'none':'';});
  const gn=$('pmGuestNote');if(gn)gn.hidden=!guest;
  const lo=$('pmLogout');if(lo)lo.style.display=guest?'none':'';
  const lg=$('pmLoginGo');if(lg)lg.onclick=()=>{$('profileGate').hidden=true;$('authGate').hidden=false;};
  renderAvGrid(nm);renderPmStats();
  document.querySelectorAll('#pm-stats .pm-quick button[data-go]').forEach(b=>b.onclick=()=>{$('profileGate').hidden=true;showView(b.dataset.go);});
  const sg=$('psSetGo');if(sg)sg.onclick=()=>{$('profileGate').hidden=true;const gear=$('setGear');if(gear)gear.click();};
  $('pmCloudNote').innerHTML=CLOUD?'계정이 <b>서버에 저장</b>되어 브라우저를 지워도 같은 주소에서 다시 로그인할 수 있어요. 다른 주소로 옮길 땐 아래 백업을 쓰세요.':'계정을 다른 주소·기기로 옮기려면 백업 파일을 내려받아 새 주소의 로그인 화면에서 복원하세요.';
  setPmTab('profile');$('profileGate').hidden=false;
}
