/* 검색 */
let searchToken=0,searchTimer=null,searchRankTab='거래대금';const remoteCache={};   /* [v9.94] 기본을 거래대금으로 */
let searchMkt='kr';   // [v4.38] 순위 시장 선택 (kr | us)
let rankStale={};   /* [v15.4.1] 탭별: 마지막 거래일 기준 여부 */

const rankCache={},rankError={},rankType={'조회수':'search','상승률':'rise','하락률':'fall'};
/* [v15.4.4] 목록 세션 캐시 — 재방문·탭 전환 시 fetch 왕복을 기다리지 않고
   직전 목록을 즉시 그린다. ※ 반드시 rankCache 선언 "뒤"에서 복원해야 한다 —
   앞에 두면 TDZ 로 조용히 실패해 복원이 무산된다(실측으로 확인한 함정). */
try{ const c=sessionStorage.getItem('rankCacheV1');
  if(c){ const j=JSON.parse(c); if(j&&j.at&&Date.now()-j.at<10*60e3&&j.data)
    Object.assign(rankCache,j.data), Object.assign(rankStale,j.stale||{}); } }catch(e){}
function rankCacheSave(){ try{ sessionStorage.setItem('rankCacheV1',
  JSON.stringify({at:Date.now(),data:rankCache,stale:rankStale})); }catch(e){} }
let nxtBatchTimer=null,nxtBatchQ=new Set();
async function primeQuotes(codes){
  const uniq=[...new Set(codes.filter(Boolean))];
  /* [수정] NXT 시간대 배지·가격 누락의 근본 원인 — NXT 보완 프라임(primeNxtQuotes)이
     순위·테마 경로에만 연결돼 있어, 텍스트 검색 결과(케이씨텍·케이아이엔엑스 등)와
     캘린더 칩·비교표처럼 primeQuotes 만 타는 화면은 NXT 체결가를 영영 못 받았다.
     이제 범용 프라임이 KRX 조회와 무관하게 NXT 보완도 항상 함께 시도한다(창구 단일화). */
  try{primeNxtQuotes(uniq);}catch(e){}
  const now=Date.now();
  const need=uniq.filter(c=>{const st=byCode[c];if(!st)return false;
    if(st.price==null){
      /* [v3.6 · 치명] 조회했는데 응답에 실리지 않는 종목(거래정지·상장폐지 예정 등)을
         화면을 그릴 때마다 다시 요청했다. 검색 화면은 시세가 올 때마다 재렌더되므로
         '재렌더 → 재요청 → 응답 도착 → 재렌더 → …' 고리가 닫혀 요청이 폭주했다.
         응답에 빠진 횟수만큼 재시도 간격을 1분씩 늘린다(최대 6분). */
      const miss=st._pxMiss||0;
      if(miss&&now-(st._pxTry||0)<Math.min(miss,6)*60e3)return false;
      st._pxTry=now;return true;
    }
    /* [v3.4] 예전엔 '가격이 비어 있을 때'만 받아 왔다. 한 번 값이 차면 다시는 조회하지 않아,
       실시간 구독에 없는 화면(순위·테마·비교·캘린더)은 첫 값에서 그대로 굳었다.
       장중에는 오래된 값(20초 초과)을 다시 받는다. */
    /* [v3.9] 정규장·동시호가는 20초, 시간외 단일가는 10분 단위 체결이라 60초 */
    {const _k=krSession();
     if(_k.krx.open&&now-(st._px_at||0)>20e3)return true;
     if(_k.krx.tradable&&!_k.krx.open&&now-(st._px_at||0)>60e3)return true;}
    /* [v1.99.2] 장외 시간: NXT 종목인데 통합가 소스(uniPx/nxtPx)가 없으면 — 순위 폴백처럼
       가격만 미리 채워진 경로 — 배치 재조회로 통합가를 받아 온다(10분 간 1회만). */
    if(!krxRegularOpen()&&nxtCapability(c)!==false&&!st.uniPx&&!st.nxtPx&&!nxtPx[c]
       &&now-(st._uniTry||0)>10*60e3){st._uniTry=now;return true;}
    return false;});
  if(!need.length)return;
  // [수정] 45개에서 잘라 버리던 것을 40개씩 나눠 전부 조회
  const parts=[];for(let i=0;i<need.length&&i<200;i+=40)parts.push(need.slice(i,i+40));
  fnBump(parts.length);
  const res=await Promise.all(parts.map(cs=>
    fetch('/api/quote?codes='+cs.join(','),{cache:'no-store'}).then(r=>r.json()).catch(()=>null)));
  res.forEach(j=>((j&&j.quotes)||[]).forEach(q=>applyQuote(q,true)));
  const got=new Set(); res.forEach(j=>((j&&j.quotes)||[]).forEach(q=>{if(q&&q.code)got.add(q.code);}));
  need.forEach(c=>{const st=byCode[c];if(!st)return; if(got.has(c))st._pxMiss=0; else st._pxMiss=(st._pxMiss||0)+1;});
}
// [수정] 실패 시 빈 배열이 캐시에 남아(빈 배열도 truthy) 해당 탭이 세션 내내 비어 보이던 버그 수정
/* [v15.4.4] 순위 항목 → 시세 주입(공용) — 캐시 경로도 fetch 경로와 똑같이
   byCode 를 채운다. 리로드 후 세션 캐시로 복원된 목록이 "행 렌더에 필요한
   시세가 없어" 통째로 스킵돼 빈 화면이 되던 병의 수리. */
function hydrateRankItems(items){
  (items||[]).forEach(it=>{ if(it&&it.code&&it.market){
    try{ mktCache[String(it.code).toUpperCase()]=it.market; }catch(e){}
  }});
  (items||[]).forEach(it=>{ if(it&&it.code&&it.price){
    const st=ensureStock(it.code,it.name||'','');
    if(st&&st.price==null){ st.price=it.price;
      if(it.rate!=null&&it.rate!==0)st.prevClose=Math.round(it.price/(1+it.rate/100));
      else if(st.prevClose==null)st.prevClose=it.price; }
  }});
}
async function loadRank(tab){
  if(rankCache[tab]&&rankCache[tab].length){ hydrateRankItems(rankCache[tab]); return rankCache[tab]; }
  try{const r=await fetch('/api/popular?type='+rankType[tab]   /* [v4.3] t=Date.now() 제거 — 매 요청이 서로 다른 주소가 돼 CDN 이 절대 캐시하지 못했다 */,{cache:'no-store'});const j=await r.json();
    const items=(j&&j.items)||[];
    try{ rankStale[tab]=!!(j&&j.stale); }catch(e){}      /* [v15.4.1] 마지막 거래일 스냅샷 여부 */
    /* [추가] 폴백 경로(JSON)는 시세·등락률까지 함께 준다. 받은 즉시 반영해
       '순위는 떴는데 값이 비어 보이는' 구간을 없앤다. */
    hydrateRankItems(items);
    if(items.length){rankCache[tab]=items; rankCacheSave();rankError[tab]=false;}
    else{rankError[tab]=true;}
  }catch{rankError[tab]=true;}
  return rankCache[tab]||[];
}
/* 명단 하나로 전 종목이 결정되므로, 코드 목록을 받아도 할 일은
   "명단이 아직 없으면 한 번 불러오기" 뿐이다. (기존 배치 API 호출 제거) */
function ensureNxtBatch(codes){
  if(NXTLIST.ready){
    (codes||[]).forEach(c=>{ if(byCode[c])byCode[c].nxt=NXTLIST.set.has(c); });
    return;
  }
  loadNxtList(false);
}
// 소속 시장 배지(코스피/코스닥/코넥스) — 확인된 경우에만 표시
function mktTag(code,market){
  const s=byCode[code];
  // ETF·ETN은 유가증권시장 상장이라 거래소 값이 '코스피'로 오지만,
  // 개별 주식과 혼동되므로 상품 종류 배지로 대체한다.
  if(isFundLike(code)){
    const k=(s&&/ETN/i.test(s.kind||''))?'ETN':'ETF';
    return `<span class="mkt-tag etf">${k}</span>`;
  }
  const mk=market||(s&&s.market)||mktCache[String(code).toUpperCase()]||'';
  if(!mk)return '';
  const cls=mk==='코스닥'?'kq':mk==='코넥스'?'kx':'kp';
  return `<span class="mkt-tag ${cls}">${mk}</span>`;
}
/* ══ [v2.0] 시장 세션 배지 — 사용자 확정 규칙 ══
   · 주말/휴장일(KR_HOLIDAYS): 노랑 '휴장'
   · KRX 전용(거래 08:30~18:00): 00:00~08:30 '장 전' / 08:30~18:00 청록 'KRX' / 18:00~ '장 종료'
   · NXT 종목(거래 08:00~20:00): 00:00~08:00 '장 전' / 08~09·15:30~20 핑크 'NXT' /
       09~15:30 남색 '통합' / 20:00~ '장 종료'
   가격 값은 기존 dispQuote(통합가 사슬)가 계속 담당하고, 배지는 시계+명단만으로 결정되므로
   시세 수신 여부와 무관하게 모든 종목에서 즉시·동일하게 뜬다(클릭 의존성 원천 제거). */
function kstNow(){return new Date(Date.now()+9*3600e3);}
function isKrHolidayTodayKST(){
  const k=kstNow();
  const iso=`${k.getUTCFullYear()}-${String(k.getUTCMonth()+1).padStart(2,'0')}-${String(k.getUTCDate()).padStart(2,'0')}`;
  return !!(typeof KR_HOLIDAYS!=='undefined'&&KR_HOLIDAYS[iso]);
}
function marketSessionKST(){
  const k=kstNow(),w=k.getUTCDay(),hm=k.getUTCHours()*60+k.getUTCMinutes();
  if(w===0||w===6||isKrHolidayTodayKST())return 'holiday';
  if(hm<480)return 'pre';
  if(hm>=1200)return 'post';
  return 'day';
}
function nxtLiveBandKST(){
  const k=kstNow(),hm=k.getUTCHours()*60+k.getUTCMinutes();
  return (hm>=480&&hm<540)||(hm>=930&&hm<1200);
}
function mktBadgeInfo(code){
  if(marketSessionKST()==='holiday')return ['휴장','hol'];
  const hm=(()=>{const k=kstNow();return k.getUTCHours()*60+k.getUTCMinutes();})();
  if(nxtCapability(code)===false){
    /* [v2.0.1] KRX 전용 — KRX 실제 거래 시간표 기준(사용자 첨부 표):
       장전 시간외 종가 08:30 시작 ~ 시간외 단일가 18:00 종료 */
    if(hm<510)return ['장 전','prem'];       // 00:00~08:30
    if(hm>=1080)return ['장 종료','post'];   // 18:00~24:00
    return ['KRX','krx'];                    // 08:30~18:00
  }
  /* NXT 종목 — NXT 시간표(프리 08:00 ~ 애프터 20:00) */
  if(hm<480)return ['장 전','prem'];
  if(hm>=1200)return ['장 종료','post'];
  return nxtLiveBandKST()?['NXT','nxt']:['통합','uni'];
}
function mktBadgeHtml(code){const b=mktBadgeInfo(code);return `<span class="px-src ${b[1]}">${b[0]}</span>`;}
/* [구버전 호환] 시세 출처 배지 — 항상 KRX/NXT/통합 중 하나를 반환한다.
   기존엔 'NXT 취급 종목인데 NXT 체결가가 아직 안 붙은' 경우(케이씨처럼) src가 'KRX'로 떨어지며
   배지가 통째로 사라졌다. 어떤 src 값이 와도(undefined 포함) 빈 문자열이 나올 수 없다. */
function srcBadgeHtml(src){
  if(src==='NXT')return '<span class="px-src nxt">NXT</span>';
  if(src==='통합')return '<span class="px-src uni">통합</span>';
  return '<span class="px-src krx">KRX</span>';   // 'KRX'·'KRXONLY'·미판정 전부 KRX로 명시
}
/* ══ [v4.65] ETF 로고를 앱 전체에서 통일 ═══════════════════════════════════
   ETF 목록에서만 운용사 로고를 쓰고, 종목 상세·검색·관심종목은 여전히 이미지
   탐색을 태우고 있었다. 그래서 같은 KODEX 200 이 화면마다 다르게 보였다.
   로고를 부르는 길목 하나를 감싸 ETF 면 운용사 로고로 돌린다. */
/* ══ [v4.86] 종목이 속한 시장 이름 ═══════════════════════════════════════
   로고를 못 찾았을 때 빈 칸 대신 적어 줄 말이다. 거래소를 아는 만큼만 적는다. */
function mktLabel(code){
  try{
    const t=String(code||'').toUpperCase();
    if(usMeta[t]){ const x=usMeta[t].sfx;
      return x==='O'?'나스닥':x==='N'?'뉴욕':x==='A'?'아멕스':'미국'; }
    const s0=byCode[code];
    const mk=String((s0&&(s0.market||s0.mkt))||'');
    if(/코스닥|KOSDAQ/i.test(mk))return '코스닥';
    if(/코스피|KOSPI/i.test(mk))return '코스피';
    if(/코넥스|KONEX/i.test(mk))return '코넥스';
    /* 시장을 모르면 종목코드 모양으로 가늠한다 — 국내는 여섯 자리 숫자다 */
    if(/^\d{6}$/.test(String(code||'')))return '국내';
    return '';
  }catch(e){ return ''; }
}
/* ══ [v8.7] 이름·코드로 미국 티커를 찾는다 ═══════════════════════════════════
   ETF 구성종목은 'Apple Inc', 'Alphabet Inc Class A' 처럼 영문 이름만 온다.
   내장 종목 이름과 맞춰 티커를 찾아내면 진짜 로고를 붙일 수 있다. */
/* 이름을 맞춰 보기 좋게 다듬는다.
   'Amazon.com Inc' → 'amazon', 'Alphabet Inc Class A' → 'alphabet',
   'JPMorgan Chase & Co' → 'jpmorganchase' 처럼 회사 형태·등급 표기를 걷어낸다. */
function usNameNorm(v){
  let x=String(v||'').toLowerCase();
  x=x.replace(/\.com\b/g,'');                       // amazon.com → amazon
  x=x.replace(/\bclass\s+[a-c]\b/g,'');             // class a/b/c
  x=x.replace(/\b(incorporated|inc|corporation|corp|company|co|limited|ltd|plc|holdings|holding|group|the|sponsored|adr|sa|nv|ag)\b/g,'');
  x=x.replace(/[^a-z0-9가-힣]/g,'');
  return x;
}
var _usNameIdx=null;
function usNameIndex(){
  if(_usNameIdx)return _usNameIdx;
  const m={};
  try{
    for(const u of US_UNI){
      const tk=u[0];
      const norm=usNameNorm;
      if(u[2])m[norm(u[2])]=tk;      // 한글명
      if(u[3])m[norm(u[3])]=tk;      // 영문명
      m[norm(tk)]=tk;
    }
  }catch(e){}
  /* 흔히 다르게 적히는 이름을 별칭으로 더한다 —
     ETF 구성종목 표기와 내장 이름이 달라 못 찾던 것들이다. */
  const alias={
    alphabet:'GOOGL', google:'GOOGL', jpmorganchase:'JPM', jpmorgan:'JPM',
    berkshirehathaway:'BRK.B', metaplatforms:'META', facebook:'META',
    exxonmobil:'XOM', johnsonjohnson:'JNJ', procterandgamble:'PG',
    proctergamble:'PG', unitedhealth:'UNH', eversource:'ES',
    homedepot:'HD', tsmc:'TSM', taiwansemiconductor:'TSM',
    walmart:'WMT', visa:'V', mastercard:'MA', netflix:'NFLX',
    walkdisney:'DIS', waltdisney:'DIS', disney:'DIS',
    advancedmicrodevices:'AMD', internationalbusinessmachines:'IBM',
    eliLilly:'LLY', elililly:'LLY', costcowholesale:'COST'
  };
  for(const [k,v] of Object.entries(alias))if(!m[k])m[k]=v;
  _usNameIdx=m; return m;
}
function usTickerOf(code,name){
  const c=String(code||'').trim();
  /* 코드가 이미 미국 티커인 경우 */
  if(/^[A-Z][A-Z.-]{0,5}$/.test(c)&&(US_DOMAIN[c]||US_DOMAIN[c.replace('-','.')]))return c;
  if(!name)return '';
  const norm=usNameNorm(name);
  if(!norm)return '';
  const idx=usNameIndex();
  return idx[norm]||'';
}
/* 해외 로고 배지 — 서버 경로를 그대로 쓴다 */
function usLogoTag(t,size){
  const cls=size?('lgo '+size):'lgo';
  const d=US_DOMAIN[t]||US_DOMAIN[String(t).replace('-','.')]||'';
  const u='/api/uslogo?t='+encodeURIComponent(String(t).replace('.','-'))
    +(d?'&d='+encodeURIComponent(d):'');
  return `<span class="${cls} on"><img src="${u}" alt="" loading="lazy"
    onerror="this.style.display='none';this.parentNode.classList.remove('on');
             this.parentNode.textContent='${htmlEsc(String(t).slice(0,4))}'"></span>`;
}
function anyLogo(code,name,size){
  /* ══ [v8.7] 해외 종목이 회색 배지로만 나오던 이유 ═══════════════════════════
     이 함수는 국내 종목코드(6자리)를 전제로 만들어졌다. ETF 구성종목처럼
     'NVIDIA Corp' 같은 영문 이름만 있는 줄은 코드가 티커가 아니어서
     로고를 찾을 길이 없었고, 전부 회색 배지가 됐다.
     [고침] 코드가 미국 티커거나 이름으로 티커를 찾을 수 있으면 해외 로고를 쓴다. */
  try{
    const tk=usTickerOf(code,name);
    if(tk)return usLogoTag(tk,size);
  }catch(e){}
  try{
    const s0=byCode[code];
    const nm=name||(s0&&s0.name)||'';
    const isEtf=(typeof isFundLike==='function'&&isFundLike(code))
      ||/^(KODEX|TIGER|SOL|ACE|RISE|PLUS|KOSEF|ARIRANG|HANARO|TIMEFOLIO|KIWOOM|WOORI|BNK|마이티|히어로즈|마이다스|파워|FOCUS|트루)/i.test(nm);
    if(isEtf&&typeof etfLogo==='function')return etfLogo(nm,size);
  }catch(e){}
  /* [v4.86] 로고를 못 찾으면 회색 바탕에 시장 이름이 나오도록 넘겨 준다 */
  return stockLogo(code,name,size,mktLabel(code));
}
function stockRow(code,name,market,tag,rank){
  const s=byCode[code];
  // [수정] 프리마켓에는 NXT 취급 종목의 NXT 체결가를 보여 준다(KRX 전용은 그대로 0.00%).
  const q=dispQuote(code);
  const price=q?q.price:(s?s.price:null), prev=q?q.prevClose:(s?s.prevClose:null);
  /* ══ [v9.3] 말이 안 되는 등락률을 걸러낸다 ═══════════════════════════════════
     [무엇이 있었나] 시스웍이 'KRX 50원 · -94.38%' 로 나왔다.
     국내 주식은 하루 ±30% 가 한계다. 94% 하락은 있을 수 없다.
     [왜 그런가] 액면분할·병합·감자가 있으면 전일 종가가 '조정 전 값'으로
     남는 경우가 있다. 890원이던 주식이 50원으로 보이면 -94% 가 된다.
     실제로는 병합 같은 사건이지 주가가 무너진 게 아니다.
     [어떻게] ±31% 를 넘으면 등락률을 표시하지 않는다.
     상·하한가(±30%)는 정상이므로 31% 로 잡았다. */
  let diff=(price!=null&&prev)?price-prev:null;
  let p=diff!=null?diff/prev*100:null;
  let odd=false;
  /* ══ [v9.4] 신규 상장주는 걸러내면 안 된다 ═══════════════════════════════════
     [확인한 사실] 케이앤에스아이앤씨(+90.45%)는 8월 13일 상장한 신규 종목이다.
     공모가 11,000원 대비 두 배 가까이 오른 것으로, 정상적인 가격이다.
     신규 상장일에는 공모가의 60~400% 범위에서 시작해 ±30% 제한이 적용되지 않는다.
     [어떻게 가려내나] '기준가 변경'은 가격이 크게 내려앉고(1/2 이하)
     시가·고가·저가가 모두 새 가격대에 있는 경우다. 신규 상장은 반대로
     가격이 위로 뛰며, 시가도 그 가격대에 함께 있다.
     → 아래로 60% 넘게 빠진 경우만 막는다. 위로 오르는 것은 그대로 보여 준다. */
  if(p!=null&&p<-60&&!usMeta[code]){
    const st2=byCode[code]||{};
    const o2=+st2.open||0;
    /* 시가도 이미 새 가격대라면 '하루 만에 폭락'이 아니라 기준가가 바뀐 것이다 */
    if(!(o2>0)||Math.abs(o2-price)/Math.max(price,1)<0.5){ odd=true; diff=null; p=null; }
  }
  const dir=diff==null?'flat':dirOf(diff);
  const cap=nxtCapability(code);
  // NXT 가능 종목에만 배지를 붙인다. 그 외(KRX 전용·확인 중)는 배지 없음.
  const badge=cap===true?(NXTLIST.halted.has(code)
      ?'<span class="nxt-badge sm halt" title="NXT 매매체결대상이지만 현재 매매거래정지 상태">NXT 정지</span>'
      /* ══ [v9.3] 목록 전체에 'NXT 일시제외' 가 붙던 이유 ═══════════════════════
         이 줄이 code(그 줄의 종목)가 아니라 selected(지금 보고 있는 종목)를
         검사하고 있었다. 그래서 선택한 종목 하나가 경보 대상이면
         목록의 모든 종목에 같은 배지가 붙었다. 반대로 실제 경보 종목은
         선택하지 않는 한 표시되지 않았다. */
      :(nxtSuspendInfo(code)
        ?'<span class="nxt-badge sm sus" title="시장경보·거래정지 지정으로 NXT 매매가 일시 중단된 종목 · 해제 시 자동 복귀">NXT 일시제외</span>'
        :'<span class="nxt-badge sm" title="넥스트레이드 매매체결대상종목 · 08:00~20:00 거래">NXT</span>'))
    :'';
  const srcTag=mktBadgeHtml(code);   // [v2.0] 세션 배지 — 시계+명단 기반, 시세 수신과 무관
  const rk=rank?`<span class="rk${rank<=3?' top':''}">${rank}</span>`:'';
  const mk=market||(s&&s.market)||'';
  /* [v4.65] 순위 유무를 클래스로 알려 준다 — 2단 배치에서 칸 수가 달라지고,
     :has() 를 못 쓰는 브라우저에서도 어긋나지 않게 하기 위해서다. */
  return `<div class="sr${rank?' has-rk':''}" data-code="${code}" data-name="${String(name||'').replace(/"/g,'')}" data-market="${mk}">
    <div class="sr-l">${rk}${anyLogo(code,name||(s&&s.name)||code)}<div class="sr-t"><div class="nm"><span class="nm-t">${name||code}</span>${mktTag(code,mk)}${tag?`<span class="tag">${tag}</span>`:''}${badge}</div><div class="cd num">${code}${mk?' · '+mk:''}</div></div></div>
    <div class="px num ${dir}">${srcTag}${price!=null?KRW(price):'—'}</div><div class="ch num ${dir}">${diff==null?(odd?'<span class="ch-odd" title="액면분할·병합 등으로 기준가가 바뀌어 등락률을 계산할 수 없습니다">기준가 변경</span>':''):arrow(dir)+' '+pctS(p)}</div>
    <div class="sr-sp"><canvas class="sr-spark" id="srsp-${code}"></canvas></div></div>`;
}
/* [v9.2] 이 두 줄이 v9.0 작업 때 덮여 'stockAll is not defined' 가 났다.
   전 종목 목록과 그 캐시 수명을 정하는 자리다. */
let stockAll=null,stockLoading=false;
function stockCacheTtl(){
  const d=new Date(), h=d.getHours(), wd=d.getDay();
  if(wd===0||wd===6)return 12*3600e3;        // 주말 — 신규 상장이 없다
  if(h>=7&&h<=20)return 2*3600e3;            // 평일 장 전후
  return 8*3600e3;                           // 평일 심야
}
/* ══ [v9.1] 종목 목록 — 당일 캔들 ═══════════════════════════════════════════
   [무엇을 그리나] 증권사 앱 목록에 흔히 붙는 '오늘 하루 봉' 하나다.
     · 몸통 = 시가 ~ 현재가   (오르면 빨강, 내리면 파랑)
     · 꼬리 = 저가 ~ 고가     (장중에 어디까지 갔다 왔는지)
     · 가운데 점선 = 전일 종가 (오늘의 기준선)
   [왜 이게 나은가] 한 달 흐름은 '요즘 어땠나'를 말하지만, 목록에서 정작
   궁금한 건 '오늘 지금 어떤가'다. 시가 대비 어디에 있고, 위아래로 얼마나
   흔들렸는지가 한 칸에 담긴다.
   [자료] 시세에 이미 open·high·low 가 들어 있어 따로 받아올 필요가 없다.
   장이 바뀌면 그 값이 새로 오므로 다음 날 저절로 초기화된다. */
/*QC-CORE-BEGIN*/
/* ══ [v15.4.1] 오늘 봉의 범위 계산 — 세션을 알고 그린다 ═══════════════════════
   [무엇이 잘못됐나] NXT 프리마켓(다음 날 아침)에는 시세의 open·high·low 가
   아직 "어제 KRX 장"의 값인데 현재가만 NXT 실시간이었다. 그래서 몸통이
   '어제 시가 → 오늘 프리마켓가'로 이어져 모든 종목이 칸을 가득 채운
   풀바가 됐다(실기 사진 — 08:22, 전부 굵은 통봉).
   [고침] 장 시작 전(pre)에는 어제 OHL 을 버리고 "전일 종가 → 현재가"만으로
   작은 몸통을 그린다. 정규장·애프터에는 당일 OHL 이 유효하니 그대로 쓴다.
   순수 함수로 분리해 하네스가 세션별 범위를 직접 검증한다. */
function srCandleRange(st,px,prev,tone){
  let o=+st.open||0, hi=+st.high||0, lo=+st.low||0;
  if(tone==='pre'){
    /* ══ [v15.4.6] 프리마켓 봉 3차 — 실기 MTS 와 같은 "전일 확정 봉" ═══════════
       [무엇이 어긋났나] v15.4.2 는 어제 고저를 통째로 버리고 전일종가→프리가
       비례봉만 남겨, 고가·저가 꼬리가 사라졌다(사용자 지적). 실제 MTS 는
       프리마켓에 "전일의 확정 봉(시·고·저·종)"을 보여 준다 — 그것이 확정된
       사실이고 정보량도 가장 많다.
       [고침] 시세가 전일 OHL 을 유효하게 들고 있으면 그대로 완성 봉을 그린다:
       몸통 = 전일 시가→전일 종가, 꼬리 = 전일 고저. 오늘 프리 등락은 봉에
       섞지 않는다(그것이 v15.4.1 원병이었다) — 등락 숫자와 점선 기준선이
       담당한다. OHL 이 비어 있으면 v15.4.2 비례봉으로 폴백한다. */
    const p0=prev>0?prev:px;
    if(o>0&&hi>0&&lo>0&&hi>=lo&&hi>=Math.max(o,p0)&&lo<=Math.min(o,p0)){
      return {o,hi,lo,px:p0,wick:true,base:p0,prevBar:true};
    }
    const chg=p0>0?Math.abs(px/p0-1):0;
    const w=Math.max(0.03,chg*1.25);
    return {o:p0,hi:p0*(1+w),lo:p0*(1-w),wick:false,base:p0};
  }
  if(!(o>0))o=prev>0?prev:px;
  if(!(hi>0))hi=Math.max(px,o);
  if(!(lo>0))lo=Math.min(px,o);
  hi=Math.max(hi,px,o); lo=Math.min(lo,px,o);
  return {o,hi,lo,wick:true,base:(prev>0&&prev>=lo&&prev<=hi)?prev:null};
}
/*QC-CORE-END*/
function srCandlePaint(code){
  const cv=$('srsp-'+code); if(!cv)return;
  const st=byCode[code]||{};
  const q=(typeof dispQuote==='function')?dispQuote(code):null;
  let px=(q&&q.price!=null)?q.price:st.price;   /* [v15.4.6] 전일 봉 모드에서 몸통 끝점 교체 가능해야 */
  const prev=(q&&q.prevClose)||st.prevClose;
  if(!(px>0)){ cv.style.display='none'; return; }
  /* ══ [v15.4.3] 종목의 '자기 시장' 세션으로 판정한다 ═══════════════════════════
     [무엇이 잘못됐나] 봉의 세션 판정이 국내(marketSession)만 봤다. 해외 종목은
     미국 세션을 봐야 하는데 한국 시계로 판정하니, 미국 프리마켓(한국 저녁)에
     해외 봉이 옛 OHL+프리가로 뒤섞이는 같은 병이 남아 있었다. 또 한국 아침
     (pre)에는 미국 장이 "끝난 뒤"라 당일 OHL 이 완성돼 있는데도 프리마켓
     취급으로 꼬리를 지워 버렸다.
     [고침] 해외 종목은 usSession().phase 로: pre→'pre'(프리 정규화 봉),
     그 외(regular·after·closed)→'on'(완성/진행 중인 당일 OHL 그대로). */
  let tone='on';
  try{
    if(typeof usMeta!=='undefined'&&usMeta[code]){
      const ph=(usSession()||{}).phase||'closed';
      tone=(ph==='pre')?'pre':'on';
    }else{
      const ms=marketSession(); tone=ms.tone;
      if(tone==='off'&&/장 시작 전/.test(ms.label||''))tone='pre';
    }
  }catch(e){}
  if(window.__sessToneOverride)tone=window.__sessToneOverride;   /* 하네스 전용 훅 */
  const R=srCandleRange(st,px,prev,tone);
  let {o,hi,lo}=R;
  if(R.prevBar&&R.px>0)px=R.px;   /* [v15.4.6] 전일 확정 봉 — 몸통은 전일 종가까지 */
  /* [v9.3] 기준가가 바뀐 종목은 봉도 그리지 않는다 — 시가와 현재가가 30% 넘게
     벌어지면 그날의 실제 움직임이 아니라 분할·병합 때문이다. */
  /* [v9.4] 신규 상장주는 시가 대비 크게 움직여도 정상이다.
     아래로 60% 넘게 빠진 경우만 봉을 그리지 않는다(기준가 변경 의심). */
  if(o>0&&(px-o)/o<-0.6&&!usMeta[code]){ cv.style.display='none'; return; }
  cv.style.display='';

  const dpr=Math.min(2,window.devicePixelRatio||1);
  const W=cv.clientWidth||26, H=cv.clientHeight||44;
  cv.width=W*dpr; cv.height=H*dpr;
  const x=cv.getContext('2d'); if(!x)return;
  x.setTransform(dpr,0,0,dpr,0,0); x.clearRect(0,0,W,H);

  /* ══ [v9.2] 미래에셋 방식으로 맞춘다 ═══════════════════════════════════════
     [사진에서 본 것] 세로로 긴 꼬리 + 그 위 어딘가에 놓인 작은 몸통.
     저가~고가가 칸 전체를 쓰고, 몸통은 그 안에서 시가~현재가만큼만 차지한다.
     그래서 '오늘 얼마나 흔들렸고 지금 그 안 어디쯤인지'가 한눈에 들어온다.
     [예전에 이상했던 이유] 전일 종가까지 범위에 넣고 여백을 18%나 둬서
     실제 등락폭이 눌려 보였다. 이제 저가~고가만으로 칸을 채운다. */
  let top=hi, bot=lo;
  let span=top-bot;
  if(!(span>0)){                       // 상·하한가 등으로 종일 한 값이면
    span=Math.max(px*0.002,1);
    top=px+span/2; bot=px-span/2;
  }
  const padY=2;
  const Y=(v)=>H-padY-(H-padY*2)*((v-bot)/(top-bot));

  const up=px>=o;
  const col=up?'#e5484d':'#3b82f6';
  const cx=Math.round(W/2)+0.5;

  /* 기준선 — 전일 종가 자리 점선(프리마켓·장중 공통, 범위 안일 때만) */
  if(R.base!=null){
    x.save(); x.strokeStyle='rgba(140,150,170,.55)'; x.lineWidth=1; x.setLineDash([2,2]);
    const yb=Y(R.base); x.beginPath(); x.moveTo(1,yb); x.lineTo(W-1,yb); x.stroke(); x.restore();
  }
  /* 꼬리 — 당일 저가~고가가 실재할 때만(프리마켓엔 없다) */
  if(R.wick!==false){
    x.strokeStyle=col; x.lineWidth=1.2;
    x.beginPath(); x.moveTo(cx,Y(hi)); x.lineTo(cx,Y(lo)); x.stroke();
  }

  /* 몸통 — 시가~현재가. 폭은 꼬리보다 확실히 넓게 */
  const bw=Math.max(6,Math.min(10,Math.round(W*0.52)));
  const yA=Y(Math.max(o,px)), yB=Y(Math.min(o,px));
  const bh=Math.max(2,yB-yA);
  x.fillStyle=col;
  x.fillRect(Math.round(cx-bw/2),yA,bw,bh);
}
/* 목록 안 캔들을 다시 그린다 — [v15.4.7] 화면 근처 행만.
   예전엔 시세가 올 때마다 200행 전부의 캔버스를 메인 스레드에서 다시 칠했다.
   스크롤·클릭과 그 작업이 겹치면 프레임이 통째로 밀려 백지가 번쩍였다.
   이제 뷰포트 ±300px 안의 행만 칠한다 — 화면 밖 행은 스크롤로 들어오는 순간
   quote 갱신 주기에 자연히 칠해지고, content-visibility 가 그 전까지 숨긴다. */
function srCandlesPaint(root){
  try{
    const H=window.innerHeight||800;
    const els=(root||document).querySelectorAll('.sr[data-code]');
    const near=[];
    els.forEach(el=>{
      const r=el.getBoundingClientRect();
      if(r.bottom>-300&&r.top<H+300)near.push(el.dataset.code);
    });
    let i=0;
    const step=()=>{const end=Math.min(i+24,near.length);
      for(;i<end;i++)srCandlePaint(near[i]);
      if(i<near.length)requestAnimationFrame(step);};
    step();
  }catch(e){}
}
function loadStockCache(){
  try{const raw=JSON.parse(localStorage.getItem('stockAll')||'null');
    if(raw&&raw.at&&(Date.now()-raw.at)<stockCacheTtl()&&Array.isArray(raw.items)&&raw.items.length){stockAll=raw.items;return true;}
  }catch(e){}
  return false;
}
/* [v2.9.7] 신규 상장 감지 — 직전 목록에 없던 코드를 찾아 기록하고 알린다. */
function noteNewListings(prev,cur){
  if(!prev||prev.size<100)return;             // 첫 수집이면 전부 신규가 되므로 건너뛴다
  const add=(cur||[]).filter(x=>x&&x.code&&!prev.has(x.code));
  if(!add.length)return;
  let log=[]; try{log=JSON.parse(localStorage.getItem('newListings')||'[]')||[];}catch(e){}
  const seen=new Set(log.map(x=>x.code));
  const fresh=add.filter(x=>!seen.has(x.code)).map(x=>({code:x.code,name:x.name||'',market:x.market||'',at:Date.now()}));
  if(!fresh.length)return;
  log=fresh.concat(log).slice(0,80);
  try{localStorage.setItem('newListings',JSON.stringify(log));}catch(e){}
  try{toast('buy',`신규 상장 ${fresh.length}종 반영`,fresh.slice(0,3).map(x=>x.name||x.code).join(', ')+(fresh.length>3?` 외 ${fresh.length-3}종`:''));}catch(e){}
}
/* [v2.9.7] 앱을 켠 뒤 캐시 수명의 절반이 지났으면 뒤에서 조용히 새 목록을 받아 둔다.
   받는 동안 stockAll 은 옛 값을 그대로 유지하다가 끝날 때 한 번에 교체되므로
   검색 중이어도 화면이 비지 않는다. 신규 상장이 있으면 그때 알림이 뜬다. */
let _bgRefreshed=false;
function refreshStockListSoon(){
  if(_bgRefreshed)return; _bgRefreshed=true;
  setTimeout(async()=>{
    try{
      const raw=JSON.parse(localStorage.getItem('stockAll')||'null');
      if(!raw||!raw.at)return;
      if(Date.now()-raw.at<stockCacheTtl()/2)return;
      await loadStockAll(null,true);
      if(currentView==='search')safeRun('bgSearch',()=>renderSearch());
    }catch(e){}
  },9000);
}
function recentListings(days){
  let log=[]; try{log=JSON.parse(localStorage.getItem('newListings')||'[]')||[];}catch(e){}
  const cut=Date.now()-(days||14)*86400e3;
  return log.filter(x=>x&&x.at>cut);
}
function saveStockCache(){try{localStorage.setItem('stockAll',JSON.stringify({at:Date.now(),items:stockAll}));}catch(e){}}
/* [v2.9.5] 예전엔 다른 곳에서 로딩이 진행 중이면 곧바로 null 을 돌려줬다.
   그래서 로고 검사가 목록을 못 받고 화면에 떠 있던 109종만 검사했다.
   이제 진행 중이면 같은 약속(Promise)을 돌려줘 호출한 쪽이 끝까지 기다린다. */
let stockAllP=null;
async function loadStockAll(onProgress,force){
  if(stockAll&&!force)return stockAll;
  if(stockAllP)return stockAllP;
  stockAllP=_loadStockAll(onProgress,force);
  try{ return await stockAllP; } finally { stockAllP=null; }
}
async function _loadStockAll(onProgress,force){
  if(stockAll&&!force)return stockAll;
  if(!force&&loadStockCache())return stockAll;
  /* 새로 받기 전에 직전 목록을 기억해 둔다 — 신규 상장 비교 기준 */
  let prevCodes=null;
  try{const raw=JSON.parse(localStorage.getItem('stockAll')||'null');
    if(raw&&Array.isArray(raw.items)&&raw.items.length)prevCodes=new Set(raw.items.map(x=>x.code));}catch(e){}
  stockLoading=true;
  const acc=new Map();
  for(const mk of ['KOSPI','KOSDAQ','KONEX']){
    for(let page=1;page<=60;page++){
      let j=null;
      try{fnBump();const r=await fetch(`/api/stocklist?market=${mk}&page=${page}`,{cache:'default'});j=await r.json();}catch(e){}
      if(!j||!j.ok||!j.n)break;
      (j.items||[]).forEach(x=>{if(!acc.has(x.code))acc.set(x.code,x);});
      if(onProgress)onProgress(acc.size,mk,page);
      /* [v2.9.6] 예전엔 'n<40이면 마지막'으로 봤다. 그런데 쪽 크기는 100(모바일)
         또는 50(HTML 대체)이라 기준 자체가 틀렸고, 중간 쪽이 일시적으로 적게 오면
         남은 종목을 전부 버렸다. 빈 응답이 올 때까지만 진행한다. */
      if(!j.n)break;
      await new Promise(r=>setTimeout(r,60));
    }
  }
  stockAll=[...acc.values()];
  stockLoading=false;
  if(stockAll.length){ saveStockCache(); noteNewListings(prevCodes,stockAll); }
  fillNamesFromAll();                       // 이미 화면에 있는 코드들의 이름·시장 채우기
  return stockAll;
}
function fillNamesFromAll(){
  if(!stockAll||!stockAll.length)return;
  const m=new Map(stockAll.map(x=>[x.code,x]));
  let changed=false;
  Object.values(byCode).forEach(s=>{const a=m.get(s.code);if(!a)return;
    if((!s.name||s.name===s.code)&&a.name){s.name=a.name;changed=true;}
    if(!s.market&&a.market)s.market=a.market;});
  if(changed)scheduleNamePaint();
}

/* ===== 최근 검색 기록 ===== */
let srchHist=[];   // 계정별 값은 reloadPerUser()에서 로드
/* ══ [v5.03] 검색·열람 기록을 한곳에 모은다 ═══════════════════════════════════
   국내·해외를 가리지 않고, 검색해서 들어갔든 목록에서 눌러 들어갔든 여기에 남는다.
   (앞서 '최근 본 종목'을 없애면서 이 함수도 함께 지워졌던 것을 다시 세운다) */
function pushHist(code,name,market){
  if(!code)return;
  srchHist=srchHist.filter(x=>x&&x.code!==code);
  srchHist.unshift({code,name:name||code,market:market||'',t:Date.now()});
  srchHist=srchHist.slice(0,20); saveHist();
  try{ if(currentView==='search')renderHist(); }catch(e){}
}
function pushHistQ(q){
  q=String(q||'').trim(); if(!q)return;
  srchHist=srchHist.filter(x=>x&&x.q!==q);
  srchHist.unshift({q,t:Date.now()});
  srchHist=srchHist.slice(0,20); saveHist();
}
/* [D3] 최근 본 종목 — 검색 기록과 별개로, 상세를 연 종목을 최신순으로 보관 */
let viewHist=[];   // 계정별 값은 reloadPerUser()에서 로드
function saveViewHist(){pset('viewHist',viewHist.slice(0,12));}
/* ══ [v5.4] saveHist 가 아예 없었다 ═══════════════════════════════════════════
   pushHist() 를 만들면서 존재하지도 않는 saveHist() 를 불렀다.
   그래서 종목을 열 때마다 'saveHist is not defined' 가 터졌고,
   검색 기록이 저장되지 않아 최근 검색이 제대로 쌓이지 않았다. */
function saveHist(){ try{ pset('srchHist',srchHist.slice(0,20)); }catch(e){} }
/* ══ [v5.03] '최근 본 종목'은 걷어냈다 ═══════════════════════════════════════
   '최근 검색'과 '최근 본 종목'이 나란히 있어 거의 같은 내용이 두 줄로 반복됐다.
   검색 기록 하나로 합치고, 보기 좋았던 '최근 본 종목'의 칩 모양을 그대로 물려받는다.
   종목을 열면 검색 기록에도 남으므로 국내·해외가 한곳에 모인다. */
function renderViewHist(){ const el=$('viewHist'); if(el)el.hidden=true; }
function renderHist(){
  const el=$('srchHist');if(!el)return;
  const typing=(($('searchInput')||{}).value||'').trim();
  if(typing||!srchHist.length){el.hidden=true;return;}
  el.hidden=false;
  el.innerHTML=`<div class="sh-head"><span>최근 검색</span><button id="shClear">전체 삭제</button></div>
    <div class="sh-chips">${srchHist.map((h,i)=>h.q
      ?`<span class="sh-chip q" data-i="${i}"><i class="sh-ic">🔍</i><b>${h.q}</b><i class="sh-x" data-x="${i}">✕</i></span>`
      /* ══ [v9.71c] 줄마다 칩 높이가 달라 보이던 이유 ═══════════════════════
         해외 종목 칩은 usTick(44×34)을, 국내 칩은 .lgo.xs(24×24)를 쓴다.
         칩을 담는 .sh-chips 는 flex 이고 기본값이 align-items:stretch 라,
         한 줄에 해외 칩이 하나만 끼어 있어도 그 줄 전체가 34px 높이로 늘어난다.
         그래서 해외 종목이 섞인 첫 줄만 유독 두꺼웠다(첨부 1번).
         작게 만드는 규칙(.sh-chip.us .us-tick)은 이미 있었는데 정작 마크업에
         us 클래스를 붙이지 않아 한 번도 적용된 적이 없었다. 이제 붙인다. */
      :`<span class="sh-chip${(h.market==='US'||usMeta[h.code])?' us':''}" data-i="${i}">${(h.market==='US'||usMeta[h.code])?usTick(h.code,'xs'):anyLogo(h.code,h.name,'xs')}<b>${htmlEsc(h.name)}</b><i class="sh-x" data-x="${i}">✕</i></span>`).join('')}</div>`;
  el.querySelectorAll('.sh-chip').forEach(c=>c.onclick=(e)=>{
    if(e.target.classList.contains('sh-x'))return;
    const h=srchHist[+c.dataset.i]; if(!h)return;
    if(h.q){const inp=$('searchInput');if(inp)inp.value=h.q;renderSearch();renderHist();return;}
    if(h.market==='US'||usMeta[h.code]){openUS(h.code);return;}   // [v5.4] 해외는 해외 화면으로
    else{ensureStock(h.code,h.name,h.market);openTrade(h.code);}
  });
  el.querySelectorAll('.sh-x').forEach(x=>x.onclick=(e)=>{e.stopPropagation();
    srchHist.splice(+x.dataset.x,1);saveHist();renderHist();});
  const cb=$('shClear');if(cb)cb.onclick=()=>{srchHist=[];saveHist();renderHist();};
}
let srchPage=1;
const SRCH_PER=30;
/* [수정] rankSection()이 호출만 되고 정의되어 있지 않아 ReferenceError가 발생 →
   종목검색 화면의 결과 영역이 통째로 비어 있었다. 순위 목록 렌더러를 구현한다. */
let _rankBusy={};
/* [수정] 이 스크립트는 <script type="module"> 이라 최상위 함수가 window 에 붙지 않는다.
   그래서 inline onclick="rankRetry(...)" 는 항상 ReferenceError 였다(2·3번 사진의 그 오류).
   → 인라인 핸들러를 없애고 addEventListener 로 연결한다. */
function rankRetry(tab){rankCache[tab]=null;rankError[tab]=false;_rankBusy[tab]=false;
  $('searchResults').classList.remove('two-col');$('searchResults').innerHTML=rankSection();bindStockClicks($('searchResults'));bindRankRetry();paintRankBox($('searchResults'));}
function bindRankRetry(){
  const b=$('rankRetryBtn');
  if(b)b.addEventListener('click',(e)=>{e.stopPropagation();rankRetry(b.dataset.tab||searchRankTab);});
  const u=$('usRankRetry'); /* [v4.48] 해외 순위 다시 시도 */
  if(u)u.addEventListener('click',(e)=>{e.stopPropagation();_usQFail=0;
    usPop=null; usPopAt=0; _usPopTry=0;          // [v4.58] 인기 목록도 새로 받는다
    /* [v14.5] 전체 시장 상승/하락 순위도 처음부터 다시 */
    try{ usRk={up:null,down:null}; usRkFail={up:0,down:0}; usRkBusy={up:false,down:false}; }catch(e2){}
    $('searchResults').classList.remove('two-col');$('searchResults').innerHTML=rankSection(); bindStockClicks($('searchResults')); bindRankRetry(); paintRankBox($('searchResults'));});
  const pd=$('usPopDiag');                       // [v4.59] 어느 사이트에서 왔는지 직접 확인
  if(pd)pd.addEventListener('click',(e)=>{e.stopPropagation();openUsPopDiag();});
  const rd=$('usRankDiag');                      /* [v14.5.1] 순위 원천 진단 */
  if(rd)rd.addEventListener('click',(e)=>{e.stopPropagation();openUsRankDiag();});
}
try{ window.rankRetry=rankRetry; }catch(e){}   /* [v8.9] 인라인 onclick 에서 부른다 — 모듈 스코프라 노출이 필요하다 */

/* ══ [v4.38] 해외 순위 — 국내와 같은 세 가지 기준으로 정렬한다 ═══════════════
   조회수는 미국 종목에 공개 지표가 없어, 거래대금(가격×거래량)으로 대신한다.
   실제 증권사도 해외는 '거래대금 상위'를 인기 지표로 쓴다. */
/* ══ [v4.58] 해외 순위 — '조회수'는 진짜 조회수로 ═══════════════════════════
   예전에는 조회수 탭이 거래대금 순서였다. 상단에 그렇게 밝히긴 했지만, 탭 이름과
   내용이 다른 건 결국 사용자를 속이는 일이다. 이제 서버가 세는 실제 조회수를 쓴다.
   목록도 유니버스 113종 안에서만 뽑지 않고, 서버가 준 인기 종목 중 모르는 티커는
   즉석에서 등록해(usRegister) 시세까지 받아 온다 → 진짜 TOP 100 이 된다. */
var usPop=null, usPopAt=0, usPopBusy=false, usPopBasis=null, usByVal=[];   /* [v9.96] usValShown 제거 — 200줄을 한 번에 그린다 */
/* ══ [v14.5] 미국 전체 상승률·하락률 순위(/api/usrank) 상태 ═══════════════════
   usRk.up / usRk.down = {items, src, mktOpen, at}. 저장소에 하루까지 보관해
   진입 즉시 그리고, 새 값이 오면 조용히 갈아 끼운다(usPop 과 같은 방식). */
var usRk={up:null,down:null}, usRkBusy={up:false,down:false}, usRkFail={up:0,down:0}, usRkTry={up:0,down:0};
function usRkSave(kind){
  try{ const st=usRk[kind]; if(!st||!st.items||!st.items.length)return;
    localStorage.setItem('usRank_'+kind+'_v1',JSON.stringify(st)); }catch(e){}
}
function usRkRestore(kind){
  try{
    const raw=localStorage.getItem('usRank_'+kind+'_v1'); if(!raw)return false;
    const c=JSON.parse(raw);
    if(!c||!Array.isArray(c.items)||!c.items.length)return false;
    if(Date.now()-(c.at||0)>24*3600e3)return false;
    usRk[kind]={items:c.items,src:c.src,mktOpen:c.mktOpen,at:0};   // at:0 → 곧바로 새 값도 요청
    return true;
  }catch(e){ return false; }
}
function usRankLoad(kind,cb){
  if(usRkBusy[kind])return;
  usRkBusy[kind]=true;
  fetch('/api/usrank?type='+kind,{cache:'no-store'}).then(r=>r.json()).then(j=>{
    usRkBusy[kind]=false;
    if(!j||!j.ok||!Array.isArray(j.items)||!j.items.length){
      usRkFail[kind]++;
      /* 순간 오류일 수 있으니 한 번만 곧바로 더 두드린다 — 두 번째도 실패하면
         화면은 113종 폴백으로 넘어가고, 재개는 '다시 시도' 버튼 몫이다 */
      if(usRkFail[kind]<2){ setTimeout(()=>{ usRkBusy[kind]=false; usRankLoad(kind,cb); },800); return; }
      cb&&cb(); return; }
    usRkFail[kind]=0;
    usRk[kind]={items:j.items.slice(0,100),src:j.src||'',mktOpen:j.mktOpen,at:Date.now()};
    usRkSave(kind);
    cb&&cb();
  }).catch(()=>{ usRkBusy[kind]=false; usRkFail[kind]++;
    if(usRkFail[kind]<2){ setTimeout(()=>usRankLoad(kind,cb),800); return; }
    cb&&cb(); });
}
/* [v14.5.1] 순위 원천 진단 — 네이버(2경로)·TradingView·야후를 각각 두드려
   어느 원천이 살아 있는지 화면에서 바로 본다(조회수 진단과 같은 창). */
async function openUsRankDiag(){
  openLiteGate('전체 시장 순위 · 원천 확인','<div class="usdg"><div class="usdg-wait">순위 원천 4곳을 직접 두드리는 중… 최대 30초</div></div>');
  let j=null,err='';
  try{ const r=await fetch('/api/usrankdiag?type=up',{cache:'no-store'}); j=await r.json(); }
  catch(e){ err=String(e).slice(0,80); }
  const body=$('liteBody'); if(!body)return;
  if(!j){ body.innerHTML=`<div class="usdg"><div class="usdg-bad">진단 서버에 연결하지 못했습니다<br><small>${htmlEsc(err)}</small></div></div>`; return; }
  const rows=(j.tried||[]).map(t=>{
    const ok=(t.parsed||0)>0;
    return `<div class="usdg-r ${ok?'ok':'no'}">
      <span class="usdg-b">${ok?'정상':'실패'}</span>
      <span class="usdg-n">${htmlEsc(t.label||'')}</span>
      <span class="usdg-s">${htmlEsc(String(t.err?'ERR':(t.detail||'—')).slice(0,40))}</span>
      <span class="usdg-l">${ok?t.parsed+'건':''}</span></div>`;}).join('');
  const u=j.usable||[];
  body.innerHTML=`<div class="usdg">
    <div class="usdg-sum ${u.length?'ok':'no'}">${u.length
      ?`전체 시장 순위를 가져올 수 있는 곳 <b>${u.length}곳</b><br><small>${htmlEsc(u.join(' · '))}</small>`
      :'순위 원천에 <b>하나도</b> 연결하지 못했습니다.'}</div>
    <div class="usdg-list">${rows||'<div class="usdg-bad">응답이 비었습니다</div>'}</div>
    <div class="usdg-note">정상인 곳이 하나라도 있으면 '다시 시도'로 곧바로 전체 시장 순위가 뜹니다.</div></div>`;
}
/* [v4.59] 조회수 원천 진단 — 어느 사이트가 응답하는지 화면에서 바로 본다 */
