    if(vp.lostVal)sc-=8;                                                        // 하단 이탈
    if(vp.trap>=22)sc-=5; else if(vp.trap>=14)sc-=2;                            // 본전 매물 압력
    if(vp.gapUp&&vp.res&&vp.gapUp.p<vp.res.p)sc+=4;                             // 위쪽이 빈 구간이면 가볍다
    if(vp.res&&vp.res.w>=4.5&&vp.res.p<px*1.05)sc-=4;                           // 코앞에 두꺼운 매물벽
