var usMeta={}; US_UNI.forEach(([t,sfx,kr,en,theme,etf])=>{usMeta[t]={t,sfx,kr,en,theme,etf,reu:t.replace('.','/')+'.'+sfx};});
function isUS(code){return !!usMeta[code];}
/* ══ [v4.31] 내장 목록 밖의 미국 종목도 다루기 ═══════════════════════════════
   US_UNI 는 큐레이션 113종이라 그 밖의 종목은 검색은커녕 열 수조차 없었다.
   검색 결과로 들어온 종목을 실행 중에 등록하면 시세·차트·주문이 모두 그대로 돌아간다.
   등록분은 localStorage 에 남겨 다음 접속에도 즉시 검색된다. */
var usDyn={};
try{ const s=JSON.parse(localStorage.getItem('usDyn1')||'null');
  if(s&&typeof s==='object')usDyn=s; }catch(e){}
function usRegister(it){
  if(!it||!it.t)return null;
  const t=String(it.t).toUpperCase();
  if(usMeta[t])return t;
  const sfx=/^[ONA]$/.test(it.sfx)?it.sfx:'O';
  /* [v4.73] 한글명이 없으면 영문명이라도 쓴다 — 'SPCX · SPCX' 처럼 티커가 두 번
     나오면 무슨 종목인지 알 수 없다. 흔히 붙는 법인 꼬리표는 떼어 읽기 좋게 만든다. */
  /* ══ [v4.76] 영문 회사명 정리 ═══════════════════════════════════════════
     'United Parcel Service, Inc.' · 'Fluence Energy Inc - Ordinary Shares - Class A'
     처럼 법인 형태와 증권 종류가 뒤에 길게 붙어 화면을 어지럽혔다.
     레버리지 표기는 국내식으로 2X·3X 로 맞춘다. */
  const LEGAL='(?:Inc|Corp|Corporation|Company|Co|Ltd|Limited|plc|PLC|N\\.V|S\\.A|LP|LLC|AG|SE)';
  const clean=(v)=>{
    let x=String(v||'');
    /* 순서가 중요하다 — 증권 종류 꼬리표를 먼저 떼고, 그 다음 법인 형태를 뗀다.
       거꾸로 하면 'Fluence Energy Inc - Ordinary Shares' 에서 Inc 가 살아남는다. */
    /* 'Ord Shs' · 'Cl A' 같은 줄임 표기와, ' - ' 뒤에 붙는 상품 설명을 떼어낸다 */
    x=x.replace(/\s*[-–]\s*(Ordinary|Common|Class|Depositary|American|Registered)[\s\S]*$/i,'');
    x=x.replace(/\s+(Ord|Com|Cl)\.?\s+(Shs|Shares|Stk|[A-Z])\b[\s\S]*$/i,'');
    x=x.replace(/\s+(Shs|Shares)\s+(of\s+)?(Beneficial\s+Interest|Common\s+Stock)[\s\S]*$/i,'');
    /* [v9.71] 대시 없이 붙는 꼬리표 — '... Common Shares'(리튬 아메리카스),
       '... Class A Common Stock (New)'(매디슨스퀘어가든)도 뗀다 */
    x=x.replace(/\s+Class\s+[A-C]\b(\s+Common\s+Stock)?[\s\S]*$/i,'');
    x=x.replace(/\s+(Common|Ordinary)\s+(Stock|Shares?)(\s*\(New\))?[\s\S]*$/i,'');
    x=x.replace(/\s*\((?:New|The)\)\s*$/i,'');
    /* 운용사 신탁명이 앞에 붙고 뒤에 진짜 상품명이 오는 ETF 는 뒤쪽을 쓴다 */
    x=x.replace(/^[A-Za-z.\s]+(?:ETF\s+Trust|Trust\s+[IVX]+|Funds?\s+Trust)\s*[-–]\s*/i,'');
    x=x.replace(/\s*[-–]\s*ADR\s*$/i,'\u0001ADR');
    x=x.replace(/\b(\d)\s*(?:x|X|배)\b/g,'$1X');          // 2배·2 x → 2X (국내 표기와 통일)
    for(let i=0;i<3;i++)
      x=x.replace(new RegExp(',?\\s+'+LEGAL+'\\.?(?=\\s|\\u0001|$)','g'),'');
    x=x.replace(/\s+(Holdings?|Group|Trust|Fund)\.?(?=\s|\u0001|$)/gi,'');
    x=x.replace(/\u0001ADR/,' (ADR)');
    return x.replace(/\s{2,}/g,' ').replace(/[\s,.]+$/,'').trim();
  };
  const en=clean(it.en)||String(it.en||'').trim();
  /* 이름 정하기 — ① 한글 표 ② 넘겨받은 한글 ③ 정리한 영문. 티커는 이름으로 쓰지 않는다.
     (HPSP 처럼 원래 알파벳인 회사는 영문 그대로 두는 게 맞다) */
  const krFromMap=(typeof US_KRNAME!=='undefined'&&US_KRNAME[t])||'';
  const krIn=/[가-힣]/.test(String(it.kr||''))?String(it.kr).trim():'';
  /* [v4.89] 이름이 비었으면 전 종목 목록에서 찾아 채운다 — 티커가 두 번 찍히지 않게.
     (다시 usRegister 를 부르지 않는다 — 되돌아가면 끝없이 반복될 수 있다) */
  let en2=en;
  if(!en2&&typeof usAll!=='undefined'&&usAll){
    try{ const hit=usAll.find(r=>r[0]===t); if(hit&&hit[1])en2=clean(hit[1])||hit[1]; }catch(e){}
  }
  const rec={t,sfx,kr:krFromMap||krIn||en2||t,en:en2||t,theme:'etc',etf:it.etf?1:0,
    reu:t.replace('.','/')+'.'+sfx,dyn:1};
  usMeta[t]=rec; usDyn[t]={sfx,kr:rec.kr,en:rec.en,etf:rec.etf};
  try{ const keys=Object.keys(usDyn); if(keys.length>400)delete usDyn[keys[0]];
    localStorage.setItem('usDyn1',JSON.stringify(usDyn)); }catch(e){}
  return t;
}
Object.keys(usDyn).forEach(t=>{ const d=usDyn[t];
  if(!usMeta[t])usMeta[t]={t,sfx:d.sfx||'O',kr:d.kr||t,en:d.en||t,theme:'etc',etf:d.etf||0,
    reu:t.replace('.','/')+'.'+(d.sfx||'O'),dyn:1}; });

