/* ══ [v4.42] 시세가 도착해도 목록이 안 바뀌던 이유 — 라운지에서만 돌게 막혀 있었다.
   어느 화면이든 눈에 보이는 행을 갱신한다. */
function usPaintRows(root){
  (root||document).querySelectorAll('.us-row[data-us], .us-star[data-us]').forEach(el=>{
    /* [v14.5.2] 전체 시장 순위 화면의 '서버 값 고정 행' — 순위의 기준 시점 값을
       실시간 시세로 덧칠하면 1위가 +6% 처럼 보이는 사고가 난다(하네스 재현).
       data-srvfix 가 붙은 행은 시세 페인트를 건너뛴다. */
    if(el.dataset.srvfix)return;
    const t=el.dataset.us,q=usQ[t]; if(!q||q.price==null)return;
    /* [v9.93] 목록 구조를 국내와 통일하면서 칸 클래스가 .px/.ch 로 바뀌었다.
       예전 셀렉터(.us-px/.us-rt)만 보면 시세가 와도 갱신되지 않는다 — 둘 다 본다. */
    const px=el.querySelector('.us-px')||el.querySelector('.px');
    const rt=el.querySelector('.us-rt')||el.querySelector('.ch');
    const cls=usRateCls(q);
    if(px){px.innerHTML=usBadgeHtml()+'$'+USD2(q.price)+`<small class="us-krw">${USDKR(q.price)}</small>`;
      px.classList.remove('up','down','flat'); px.classList.add('num',cls);}
    if(rt){rt.textContent=usRateTxt(q);
      rt.classList.remove('up','down','flat'); rt.classList.add('num',cls);}
    try{ el.classList.remove('skel'); usCandlePaint(t); }catch(e){}
    const p=el.querySelector('.p'), r=el.querySelector('.r');
    if(p)p.textContent='$'+USD2(q.price);
    if(r){r.textContent=usRateTxt(q);
      r.classList.remove('up','down','flat'); r.classList.add('num',usRateCls(q));}
  });
  /* [v9.3] 숫자를 갈아 끼운 뒤 당일 캔들도 다시 그린다 */
  try{ usCandlesPaint(root); }catch(e){}
}
/* ══ [v4.85] 순위가 실제로 바뀌었을 때만 다시 그린다 ═══════════════════════
   [왜] 20초마다 시세가 들어올 때마다 순위표를 통째로 다시 만들면, 순서가 그대로여도
   로고 그림이 새로 시작되고 스크롤이 흔들린다. 값은 usPaintRows 가 이미 칠한다.
   [어떻게] 지금 화면에 그려진 종목 차례와, 새 시세로 다시 매긴 차례를 견준다.
   같으면 건너뛰고, 달라졌을 때만 다시 그린다. */
function usRankOrderChanged(){
  try{
    /* [v14.5.2] 상승·하락 탭의 순서는 이제 서버(/api/usrank)가 정한다 —
       실시간 시세로 재정렬 비교를 하면 매 틱 '바뀌었다'로 판정돼 통째로
       다시 그려진다(로고 깜빡임·스크롤 흔들림). 서버 갱신은 renderUsRankBody
       안의 TTL 로직이 맡으므로 여기서는 그대로 둔다. */
    if(usRankTab==='up'||usRankTab==='down')return false;
    const box=$('usRankBody'); if(!box)return true;
    const shown=[...box.querySelectorAll('[data-us]')].map(e=>e.dataset.us);
    if(!shown.length)return true;
    const rate=(t)=>{const q=usQ[t]; return (q&&q.prev)?(q.price-q.prev)/q.prev*100:0;};
    const val =(t)=>{const q=usQ[t]; return (q&&q.price&&q.vol)?q.price*q.vol:0;};
    const cap =(t)=>{const q=usQ[t]; return (q&&q.cap)||0;};
    let next=shown.slice();
    if(usRankTab==='up')next.sort((a,b)=>rate(b)-rate(a));
    else if(usRankTab==='down')next.sort((a,b)=>rate(a)-rate(b));
    else if(usRankTab==='val')next.sort((a,b)=>val(b)-val(a));
    else if(usRankTab==='cap')next.sort((a,b)=>cap(b)-cap(a));
    else return false;                       // 조회수 탭은 시세로 순서가 바뀌지 않는다
    return next.join(',')!==shown.join(',');
  }catch(e){ return true; }
}
function renderUsLive(){
  /* ══ [v4.85] 시세가 들어올 때마다 목록을 통째로 다시 그리지 않는다 ═══════════
     usPaintRows 가 이미 가격·등락률만 골라 칠해 준다. 그런데도 아래에서 목록
     전체를 다시 만들어 붙이고 있었다 → 로고 그림이 매번 새로 시작되고,
     스크롤 위치까지 흔들려 화면이 깜빡였다.
     순서가 바뀌는 순위표만 다시 그리고, 나머지는 숫자만 갈아 끼운다. */
  usPaintRows();                                   // 화면 종류와 무관하게 먼저 칠한다
  if(currentView!=='us')return;
  renderUsBreadthChip();
  /* 순위표도 '순서가 실제로 바뀌었을 때만' 다시 그린다 */
  if(usPane==='rank'&&usRankOrderChanged())renderUsRankBody();
  if(usPane==='mine')renderUsMine();
  const fx=usFx();
  if(fx){const el=document.querySelector('#usHero .uz-hero-fx b'); if(el)el.textContent=KRW(Math.round(fx));}
}
function wireUsLounge(){
  document.querySelectorAll('#usNav button').forEach(b=>b.onclick=()=>usPaneShow(b.dataset.uspane));
  document.querySelectorAll('[data-ustheme]').forEach(b=>b.onclick=()=>{usThemeSel=b.dataset.ustheme;
    document.querySelectorAll('[data-ustheme]').forEach(x=>x.classList.toggle('on',x===b));renderUsThemeBody();});
  /* 마켓 클록은 1분마다 스스로 움직인다 — 화면을 떠나면 멈춘다 */
  if(!window._usClockT)window._usClockT=setInterval(()=>{
    if(currentView==='us')renderUsHero(); },60e3);
  const inp=$('usSearch'), clr=$('usSearchClear');
  if(inp&&!inp._wired){inp._wired=true;
    const paint=(q)=>{
      const box=$('usSearchOut'), main=$('usFindMain');
      if(clr)clr.hidden=!q;
      if(main)main.hidden=!!q;
      if(!q){box.innerHTML='';return;}
      const local=usLocalMatch(q);
      const draw=(list,note)=>{ box.innerHTML=(list.length
          ? `<div class="uz-note">'${q}' 검색 <b>${list.length}종</b>${note?' · '+note:''}</div>
             <div class="uz-list">${list.slice(0,20).map(t=>usRow(t)).join('')}</div>`
          : `<div class="uz-empty"><b>'${q}' 검색 결과가 없습니다</b><span>${note||'티커(AAPL) 또는 한글·영문 종목명으로 찾아 보세요.'}</span></div>`);
        if(list.length)usEnsureQuotes(list.slice(0,20),true).then(()=>usPaintRows($('usSearchOut'))); };
      draw(local, local.length?'':'전 종목에서 찾는 중…');
      usSearchRemote(q,(items)=>{
        if(inp.value.trim()!==q)return;                       // 입력이 바뀌었으면 버린다
        const merged=[...new Set(local.concat(items.map(x=>x.t)))];
        draw(merged, merged.length>local.length?`내장 ${local.length}종 + 전 종목 ${merged.length-local.length}종`
          :(merged.length?'':'미국 상장 종목에서도 찾지 못했습니다'));
      });
    };
    let _t=null;
    inp.oninput=()=>{const q=inp.value.trim(); clearTimeout(_t); _t=setTimeout(()=>paint(q),220);};
    if(clr)clr.onclick=()=>{inp.value='';paint('');inp.focus();};
  }
}
document.addEventListener('click',(e)=>{const n=e.target.closest('[data-us]');
  if(n&&n.dataset.us){openUS(n.dataset.us);}});

/* ── 7. 해외 거래 화면 ── */
var usSel=null, usSide='buy', usRange=132, usCandles=null, usOrdPx=null, usOrdQty=1;
var usTF='D';    // [v4.42] 봉 종류 — D 일봉 / W 주봉 / M 월봉
/* 일봉을 주·월봉으로 묶는다 — 시가는 첫 봉, 종가는 마지막 봉, 고저는 구간 최대·최소 */
function usAgg(cs,tf){
  if(tf==='D'||!cs||!cs.length)return cs||[];
  const key=(t)=>{
    const s=String(t), y=+s.slice(0,4), m=+s.slice(4,6), d=+s.slice(6,8);
    if(tf==='M')return y*100+m;
    const dt=new Date(Date.UTC(y,m-1,d));
    const th=new Date(dt); th.setUTCDate(dt.getUTCDate()-((dt.getUTCDay()+6)%7));   // 그 주 월요일
    return +(th.getUTCFullYear()+String(th.getUTCMonth()+1).padStart(2,'0')+String(th.getUTCDate()).padStart(2,'0'));
  };
  const out=[]; let cur=null,k0=null;
  cs.forEach(c=>{
    const k=key(c.t);
    if(k!==k0){ if(cur)out.push(cur); k0=k; cur={t:c.t,o:c.o,h:c.h,l:c.l,c:c.c,v:c.v}; }
    else { cur.h=Math.max(cur.h,c.h); cur.l=Math.min(cur.l,c.l); cur.c=c.c; cur.v+=c.v; cur.t=c.t; }
  });
  if(cur)out.push(cur);
  return out;
}
/* ══ [v4.57] 해외 차트를 국내 차트와 같은 것으로 만든다 ═══════════════════
   [무엇이 달랐나] 국내 차트에는 봉 종류(일·주·월·분), 이동평균 4개, 확대·축소,
   드래그 이동, 툴팁, 매물대, 차트 설정(캔들/선/하이킨아시)이 있는데
   해외 차트는 캔버스 하나에 기간 버튼만 있었다. 같은 앱에서 두 화면이 딴판이었다.
   [어떻게 했나] 해외용 차트를 새로 만들지 않는다 — 국내 차트 카드(#chartCard)를
   해외 정보 패널로 '옮겨' 같은 엔진이 그리게 한다. 화면에는 어차피 하나만 보이므로
   충돌하지 않고, 기능·모양·조작이 자동으로 100% 같아진다.
   앞으로 국내 차트를 고치면 해외도 함께 좋아진다. */
function usChartMount(on){
  const card=$('chartCard'); if(!card)return;
  const host=on?$('usChartHost'):$('chartHome');
  if(host&&card.parentElement!==host)host.appendChild(card);
  card.hidden=!on&&currentView!=='trade';
}
/* 해외 일봉을 국내 엔진이 읽는 모양(d: 'YYYYMMDD')으로 바꾼다 */
function usToEngine(cs){
  return (cs||[]).map(c=>({d:String(c.t),o:+c.o,h:+c.h,l:+c.l,c:+c.c,v:+c.v||0}));
}
var usTfMap={D:'D',W:'W',M:'M'};
/* ══ [v4.60] 일봉은 화면에 들어오는 즉시 받아 둔다 ══════════════════════════
   [무엇이 잘못됐나] v4.57 에서 차트를 국내 엔진으로 옮기면서, 캔들을 '차트 탭에서만'
   불러오게 바뀌었다. 그런데 시세 탭도 같은 캔들을 쓴다 → 차트를 한 번도 안 누르면
   '일별 시세를 불러오는 중입니다'에서 영영 멈춘다. 내가 만든 회귀다.
   → 종목 화면에 들어오면 탭과 무관하게 바로 받고, 받으면 열려 있는 탭을 다시 그린다. */
var _usCdBusy=null;
function usEnsureCandles(){
  if(!usSel)return Promise.resolve();
  if(usCandles&&usCandles.length)return Promise.resolve();
  if(_usCdBusy)return _usCdBusy;
  const want=usSel;
  _usCdBusy=fetch('/api/uscandle?code='+encodeURIComponent(usMeta[want].reu)+'&n=560',{cache:'no-store'})
    .then(r=>r.json()).then(j=>{
      if(usSel!==want)return;
      usCandles=(j&&j.ok&&Array.isArray(j.candles))?j.candles:[];
      if(usCandles.length)usApplyCandleExtras(j);
    }).catch(()=>{ if(usSel===want)usCandles=[]; })
    .then(()=>{ _usCdBusy=null;
      if(currentView==='ustrade'){ if(usInfoTab==='chart')usLoadIntoChart(); else renderUsInfo(); } });
  return _usCdBusy;
}
/* 분봉 — 야후 1분봉을 받아 두고 3·5·10·30·60 분은 여기서 묶는다 */
var usMinRaw=null, usMinSpan=null, _usMinFor=null, _usMinBusy=null, _usMinBkt=0;
/* [v4.62] 요청하는 봉 크기에 따라 서버가 더 먼 과거를 준다 — 봉별로 따로 보관한다 */
function usMinBucket(mins){ return mins>=60?60:mins>=30?30:mins>=5?5:mins>=3?3:1; }
function usEnsureMinutes(){
  if(!usSel)return Promise.resolve();
  const bkt=usMinBucket(minutesOf(chartTf)||1);
  if(_usMinFor===usSel&&usMinRaw&&_usMinBkt===bkt)return Promise.resolve();
  if(_usMinBusy)return _usMinBusy;
  const want=usSel;
  _usMinBusy=fetch('/api/uscandle?tf=MIN&m='+bkt+'&code='+encodeURIComponent(usMeta[want].reu),{cache:'no-store'})
    .then(r=>r.json()).then(j=>{
      if(usSel!==want)return;
      usMinRaw=(j&&j.ok&&Array.isArray(j.candles))?j.candles:[];
      usMinSpan=(j&&j.span)||null;
      _usMinFor=want; _usMinBkt=usMinBucket(minutesOf(chartTf)||1);
    }).catch(()=>{ if(usSel===want){usMinRaw=[];_usMinFor=want;} })
    .then(()=>{ _usMinBusy=null; if(currentView==='ustrade'&&usInfoTab==='chart')usLoadIntoChart(); });
  return _usMinBusy;
}
function usMinAgg(mins){
  const src=usMinRaw||[]; if(!src.length)return [];
  const ms=mins*60000, out=[]; let cur=null,k0=null;
  for(const c of src){
    const k=Math.floor(c.t/ms);
    if(k!==k0){ if(cur)out.push(cur); k0=k; cur={t:c.t,o:c.o,h:c.h,l:c.l,c:c.c,v:c.v}; }
    else { cur.h=Math.max(cur.h,c.h); cur.l=Math.min(cur.l,c.l); cur.c=c.c; cur.v+=c.v; }
  }
  if(cur)out.push(cur);
  /* 국내 엔진은 d(라벨)로 축을 그린다 — 분봉은 시:분으로 준다 */
  return out.map(c=>{ const d=new Date(c.t);
    const lb=''+d.getFullYear()+String(d.getMonth()+1).padStart(2,'0')+String(d.getDate()).padStart(2,'0')
      +String(d.getHours()).padStart(2,'0')+String(d.getMinutes()).padStart(2,'0');
    return {d:lb,o:c.o,h:c.h,l:c.l,c:c.c,v:c.v,t:c.t}; });
}
async function usLoadIntoChart(){
  if(currentView!=='ustrade'||!usSel)return;
  const lg=$('chartLegend');
  if(isMinute(chartTf)){
    if(_usMinFor!==usSel||!usMinRaw||_usMinBkt!==usMinBucket(minutesOf(chartTf)||1)){
      chartLoading=true; if(lg)lg.textContent='분봉 불러오는 중…'; drawChart();
      await usEnsureMinutes(); chartLoading=false;
    }
    curCandles=usMinAgg(minutesOf(chartTf));
    resetView(); drawChart();
    /* [v4.63] 실제로 확보한 기간을 숨기지 않고 적는다 — 1분봉은 원천이 7일씩만 주므로
       아무리 이어 붙여도 두 달 남짓이 한계다. 1년인 척하지 않는다. */
    {const nt=$('usChartNote'), sp=usMinSpan;
     if(nt)nt.innerHTML=sp?`${TFLABEL[chartTf]||''}봉 · 최근 <b>${sp.days}일</b> (${KRW(curCandles.length)}봉)`
       +(sp.note?` <span class="uc-note">· ${sp.note}</span>`:''):'';}
    if(!curCandles.length&&lg)lg.textContent='분봉 데이터를 받지 못했어요 · ⟳ 로 다시 시도';
    return;
  }
  if(!usCandles||!usCandles.length){
    chartLoading=true; if(lg)lg.textContent='차트 불러오는 중…'; drawChart();
    await usEnsureCandles(); chartLoading=false;
  }
  curCandles=usToEngine(usAgg(usCandles||[],usTfMap[chartTf]||'D'));
  resetView(); drawChart();
  {const nt=$('usChartNote'); if(nt)nt.innerHTML='';}
  if(!curCandles.length&&lg)lg.textContent='차트 데이터를 받지 못했어요 · ⟳ 로 다시 시도';
}
/* 52주 고저 보강 + 원천 표시 — 예전 loadUsCandles 가 하던 일을 여기서 이어받는다 */
function usApplyCandleExtras(j){
  try{
    const y=(usCandles||[]).slice(-252);
    if(y.length){
      const cur=usQ[usSel]||{};
      usQ[usSel]=Object.assign(cur,{w52h:cur.w52h!=null?cur.w52h:Math.max(...y.map(c=>c.h)),
        w52l:cur.w52l!=null?cur.w52l:Math.min(...y.map(c=>c.l)),w52n:y.length});
      if(usInfoTab==='summary')renderUsInfo();
    }
  }catch(e){}
}
function openUS(t){ if(!usMeta[t])return;
  usSel=t; usSide='buy'; usOrdPx=null; usOrdQty=1; usCandles=null;
  usMinRaw=null; usMinSpan=null; _usMinFor=null;        // [v4.60] 분봉 캐시도 종목별
  /* [v4.56] 해외도 '최근 본 종목'에 국내와 같은 목록으로 남긴다 —
     예전에는 해외만 '최근 검색'으로 따로 놀아서, 방금 본 미국 종목을
     종목검색 화면에서 다시 찾을 수가 없었다. */
  /* [v4.58] 조회수 집계 — 이 앱의 '조회수 TOP 100'을 만드는 유일한 실제 근거다 */
  safeRun('openUS:count',()=>{ fetch('/api/usview?t='+encodeURIComponent(t),{cache:'no-store'}).catch(()=>{}); });
  /* [v5.03] 해외도 같은 검색 기록에 남긴다 */
  safeRun('openUS:view',()=>{ const m=usMeta[t]||{}; pushHist(t,m.kr||t,'US'); });
  showView('ustrade');
}
var usInfoTab='summary';
/* [v10.5] 해외 관심종목 버튼 — 국내($('starBtn'))와 같은 흐름을 그대로 쓴다 */
function wireUsStar(){
  const go=async()=>{
    const code=usSel; if(!code)return;
    try{
      if(!watchFolders.length){
        const f=await newFolderFlow([code]);
        if(f){ syncWatchUnion(); feed&&feed.addCode(code); saveState();
          toast('buy','관심종목 추가',`${(usMeta[code]&&usMeta[code].kr)||code} → ${f.icon?f.icon+' ':''}${f.name}`);
          renderUsHead(); renderWatch(); }   /* [v10.9] renderUsHead 가 스스로 배선한다 */
        return;
      }
      openFolderPop(code,$('usStarBtn'));
    }catch(e){}
  };
  const b=$('usStarBtn'); if(b){ b.onclick=go; b.onkeydown=(e)=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();go();}} }
  /* [v10.6] 나머지 도구도 국내와 같은 함수를 그대로 쓴다 */
  const wire=(id,fn)=>{ const e=$(id); if(e)e.onclick=()=>{ try{fn();}catch(err){} }; };
  /* 국내 도구들은 전역 selected 를 본다. 해외에서도 같은 함수를 쓰되,
     부르는 동안만 selected 를 이 종목으로 맞췄다가 되돌린다.
     (해외 티커도 byCode 에 껍데기를 만들어 두어야 내부에서 터지지 않는다) */
  const asSel=(fn)=>()=>{
    const keep=selected;
    try{
      if(!byCode[usSel])ensureStock(usSel,(usMeta[usSel]&&usMeta[usSel].kr)||usSel,'해외');
      const q=usQ[usSel];
      if(q&&q.price!=null){ const b=byCode[usSel]; b.price=q.price; b.prevClose=q.prev; }
      selected=usSel; fn();
    }catch(e){}
    finally{ selected=keep; }
  };
  wire('usAlertBtn',asSel(()=>openAlertGate()));
  wire('usCmpBtn',asSel(()=>{ cmpToggle(usSel); toast('on','비교함',cmpList().includes(usSel)?'담았어요':'뺐어요'); renderUsHead(); }));
  wire('usDartBtn',()=>{ window.open('https://finance.yahoo.com/quote/'+encodeURIComponent(usSel),'_blank','noopener'); });
  wire('usHoldBtn',asSel(()=>openHoldGate()));
  wire('usMemoBtn',asSel(async()=>{
    const nm=(usMeta[usSel]&&usMeta[usSel].kr)||usSel;
    const v=await askMemo(nm+' 메모',{value:stockMemos[usSel]||'',placeholder:'매수 이유, 목표가 근거 등을 남겨 두세요'});
    if(v===null)return;
    if(v.trim())stockMemos[usSel]=v.trim(); else delete stockMemos[usSel];
    saveState(); renderUsHead();
  }));
}
function renderUsTrade(){
  if(!usSel){showView('us');return;}
  renderUsHead(); renderUsOrder();
  /* [v4.57] 봉 종류·이동평균·확대축소는 국내 차트 카드가 그대로 들고 온다 —
     해외 전용 세그먼트를 따로 그리지 않는다(그게 두 화면이 달라진 원인이었다). */
  document.querySelectorAll('#usInfoTabs button').forEach(b2=>b2.onclick=()=>{
    usInfoTab=b2.dataset.uinfo;
    document.querySelectorAll('#usInfoTabs button').forEach(x=>x.classList.toggle('on',x===b2));
    renderUsInfo();});
  document.querySelectorAll('#usInfoTabs button').forEach(x=>x.classList.toggle('on',x.dataset.uinfo===usInfoTab));
  renderUsInfo();
  usEnsureQuotes([usSel],true,true).then(()=>{renderUsHead();renderUsOrder();renderUsInfo();renderUsCta();});
  usEnsureCandles();          // [v4.60] 탭과 무관하게 바로 — 시세 탭도 이 데이터를 쓴다
  usPollStart([usSel]);
  /* [v4.50] 하단 고정 주문바 — 모듈이라 inline onclick 을 쓸 수 없어 여기서 묶는다 */
  {const b=$('usCtaBuy'), sl=$('usCtaSell');
   if(b&&!b._w){b._w=1;b.addEventListener('click',()=>usCtaGo('buy'));}
   if(sl&&!sl._w){sl._w=1;sl.addEventListener('click',()=>usCtaGo('sell'));}}
  renderUsCta();
}
/* ══ [v4.37] 해외 종목정보 — 국내와 같은 8개 코너 ═══════════════════════════ */
function renderUsInfo(){
  const el=$('usInfoBody'), cc=$('usChartCard');
  if(usInfoTab==='chart'){ if(cc)cc.hidden=false; el.style.display='none';
    usChartMount(true);                                    // [v4.57] 국내 차트 카드를 이리로
    try{ buildTfSeg(); buildMaSeg(); }catch(e){}
    /* [v4.60] 분봉도 지원하므로 더 이상 감추지 않는다 */
    try{ document.querySelectorAll('#tfSeg [data-tf]').forEach(b=>{b.style.display='';}); }catch(e){}
    usLoadIntoChart();
    requestAnimationFrame(()=>requestAnimationFrame(()=>drawChart()));
    return; }
  if(cc)cc.hidden=true; el.style.display='';
  usChartMount(false);                                     // 다른 탭으로 가면 제자리로
  const f={summary:renderUsSummary,ai:renderUsAi,sise:renderUsSiseTab,news:renderUsNews,
           company:renderUsCompany,consensus:renderUsCons,finance:renderUsFin,
           dividend:renderUsDividend,strength:renderUsStrength}[usInfoTab];
  (f||renderUsSummary)(el);
}
function usNoData(t,d){return `<div class="us-nodata"><b>${t}</b><span>${d}</span></div>`;}
/* ① 종목요약 — 시세·통계·회사 소개 */
function renderUsSummary(el){
  const m=usMeta[usSel]||{}, q=usQ[usSel]||{};
  const d=(q.price!=null&&q.prev)?q.price-q.prev:null;
  const fmt=(v)=>v==null?'—':'$'+USD2(v);
  const vol=(v)=>v==null?'—':(v>=1e6?(v/1e6).toFixed(1)+'M':v>=1e3?(v/1e3).toFixed(1)+'K':KRW(v));
  /* [v4.49] 시가총액은 T/B/M 어느 구간이든 원화 환산을 함께 보여 준다.
     예전에는 1조 달러 이상일 때만 원화를 붙여, B 단위 종목은 감이 안 왔다. */
  const capS=(v)=>{if(v==null)return '—';const fx=usFx();
    const usd=v>=1e12?'$'+(v/1e12).toFixed(2)+'T':v>=1e9?'$'+(v/1e9).toFixed(1)+'B':'$'+(v/1e6).toFixed(0)+'M';
    if(!fx)return usd;
    const krw=v*fx;
    const won=krw>=1e12?(krw/1e12).toFixed(krw>=1e13?0:1)+'조원':(krw/1e8).toFixed(0)+'억원';
    return usd+` <small>≈${won}</small>`;};
  /* 52주 위치 막대 — 국내 '연간 가격 변화'와 같은 형태.
     [v4.49] 캔들에서 계산했고 1년치가 안 되면 몇 거래일 기준인지 밝힌다.
     '52주'라고 적어 놓고 실제로는 3개월치인 상황을 그대로 두면 값이 거짓말이 된다. */
  let band='';
  if(q.w52h!=null&&q.w52l!=null&&q.price!=null&&q.w52h>q.w52l){
    const pos=Math.max(0,Math.min(100,(q.price-q.w52l)/(q.w52h-q.w52l)*100));
    const partial=(q.w52n&&q.w52n<240)?`<small>실제 데이터 ${q.w52n}거래일 기준</small>`:'';
    band=`<div class="us-sec2">52주 가격 위치 ${partial}</div>
      <div class="us-band"><i style="left:${pos}%"></i></div>
      <div class="us-band-lb"><span>최저 ${fmt(q.w52l)}<b class="up">+${((q.price-q.w52l)/q.w52l*100).toFixed(0)}%</b></span>
        <span>최고 ${fmt(q.w52h)}<b class="down">${((q.price-q.w52h)/q.w52h*100).toFixed(0)}%</b></span></div>`;
  }
  /* 시세 자체가 안 왔을 때 빈 표를 보여 주는 대신 무슨 일인지 말해 준다 */
  if(q.price==null){
    el.innerHTML=`<div class="uz-empty"><b>${_usQFail>=2?'시세를 받지 못했습니다':'시세를 받는 중입니다'}</b>
      <span>${_usQFail>=2?'해외 시세 서버가 응답하지 않고 있어요. 잠시 뒤 다시 시도해 주세요.':'잠시만 기다려 주세요.'}</span>
      <button type="button" class="uz-retry" id="usSumRetry">다시 시도</button></div>`;
    const b=$('usSumRetry');
    if(b)b.onclick=()=>{_usQFail=0;el.innerHTML='';usEnsureQuotes([usSel],true).then(()=>renderUsInfo());};
    return;
  }
  const th=(US_THEMES.find(x=>x[0]===m.theme)||[,''])[1];
  el.innerHTML=`<div class="us-px-big"><b class="num ${dirOf(d||0)}">$${USD2(q.price)}</b>
      <span class="num ${dirOf(d||0)}">${d==null?'':(d>=0?'+':'')+USD2(d)+' ('+usRateTxt(q)+')'}</span>
      <i class="num">${USDKR(q.price)}</i></div>
    <div class="us-sum-card"><div class="us-sum-h">기업 개요 <span class="ai-badge">AI</span></div>
      <p>${usCompanyBrief(usSel)}</p>
      <div class="us-tagrow">${th?`<span class="us-tag">${th}</span>`:''}${m.etf?'<span class="us-tag">ETF</span>':''}
        <span class="us-tag">${{O:'NASDAQ',N:'NYSE',A:'AMEX'}[m.sfx]||''}</span></div>
      <div class="us-sum-note">실시간 시세와 거래소 공개 정보를 결합한 요약입니다.</div></div>
    <div class="us-sec2">종목 정보 <small>미국 주식은 상·하한가 제도가 없습니다</small></div>
    <div class="us-stat-g">
      <div class="us-stat"><small>시가</small><b class="num">${fmt(q.open)}</b></div>
      <div class="us-stat"><small>고가</small><b class="num" style="color:var(--up)">${fmt(q.high)}</b></div>
      <div class="us-stat"><small>저가</small><b class="num" style="color:var(--down)">${fmt(q.low)}</b></div>
      <div class="us-stat"><small>거래량</small><b class="num">${vol(q.vol)}</b></div>
      <div class="us-stat"><small>52주 최고</small><b class="num">${fmt(q.w52h)}</b></div>
      <div class="us-stat"><small>52주 최저</small><b class="num">${fmt(q.w52l)}</b></div>
      <div class="us-stat"><small>시가총액</small><b class="num">${capS(q.cap)}</b></div>
      <div class="us-stat"><small>전일 종가</small><b class="num">${fmt(q.prev)}</b></div>
    </div>${band}`;
}
/* 회사 한 줄 소개 — 유니버스 정보로 구성 */
/* ══════════════════════════════════════════════════════════════════════════════
   [v9.91] 해외 종목 개요를 국내 수준으로
   ─────────────────────────────────────────────────────────────────────────────
   [무엇이 부실했나] "팔란티어(PLTR)는 나스닥에 상장된 상장 기업입니다. AI·반도체
   분야에 속하며, 영문명은 Palantir입니다." — 종목 이름만 바꾸면 어느 종목에나
   그대로 들어맞는 문장이다. 읽어도 이 종목에 대해 아무것도 알게 되지 않는다.
   [무엇을 더 쓸 수 있나] 이미 받아 둔 시세에 쓰지 않던 값이 많다.
   시가총액·52주 위치·거래대금·PER·배당·전일 대비 — 전부 usQ 에 들어 있다.
   없는 사실을 지어내지 않고, 가진 숫자를 읽어 주는 문장으로 바꾼다. */

/* ══════════════════════════════════════════════════════════════════════════════
   [v11.0] 등급 — 화면 쪽
   ─────────────────────────────────────────────────────────────────────────────
   서버가 로그인·동기화 응답에 tier 를 실어 준다. 화면은 그 값을 그대로 쓰고,
   스스로 올리지 않는다. localStorage 에도 저장하지 않는다 — 저장해 두면
   그것만 고쳐도 잠금이 풀리는 것처럼 보여, 사용자가 오해하기 쉽다.
   (진짜 잠금은 서버가 하는 것이 맞지만, 지금은 무료 앱이라 화면 잠금까지만 한다)

   [늘리기 쉬운 구조] 배열 순서 = 등급 순서. 등급을 더 넣거나 한도를 바꿀 때
   아래 표만 고치면 되고, 화면 코드(tierAllow/tierLimit)는 손댈 필요가 없다.
   ══════════════════════════════════════════════════════════════════════════════ */
const TIERS=[
  {k:'free',  n:'Free',  c:'#8a97a8', d:'기본 기능을 모두 쓸 수 있어요'},
  {k:'lite',  n:'Lite',  c:'#14b8a6', d:'관심종목을 더 담고 자료를 내려받을 수 있어요'},
  {k:'basic', n:'Basic', c:'#2f74ff', d:'앱을 닫아도 알림을 받고 세금 리포트를 볼 수 있어요'},
  {k:'plus',  n:'Plus',  c:'#7c3aed', d:'손절·익절이 자동으로 실행되고 AI 분석이 전부 열려요'},
  {k:'pro',   n:'Pro',   c:'#e5443b', d:'급등주 예측·매집 포착기·백테스트를 쓸 수 있어요'},
  {k:'max',   n:'Max',   c:'#f5a30d', d:'모든 한도가 사라지고 시세를 우선으로 받아요'},
];
const INF=Infinity;
/* 한도 — 배열 순서가 곧 free→max */
const TIER_LIMITS={
  watch:    [ 20,  40,  80, 200, 500, INF],
  folder:   [  2,   4,   8,  15,  30, INF],
  alert:    [  3,   6,  15,  50, 150, INF],
  fxAlert:  [  1,   2,   5,  10,  20, INF],
  book:     [  3,   6,  15,  30,  80, INF],
  compare:  [  2,   2,   3,   4,   6,   8],
  account:  [  2,   3,   5,   8,  15, INF],
  memo:     [  5, INF, INF, INF, INF, INF],
};
/* [v11.6] 아래 두 가지는 표만 있고 실제로 거는 자리가 없어 뺐다.
   btYears — 백테스트 화면이 기간을 직접 받지 않는다(전 구간을 한 번에 계산).
   pushDev — 기기 수는 서버가 push:<id> 로 관리하며 화면이 셀 수 없다.
   지키지 못할 약속을 표에 남겨 두면 카드의 다른 항목까지 믿을 수 없게 된다.
   나중에 그 자리가 생기면 그때 다시 넣는다. */
/* 기능 — 필요한 최소 등급 번호 */
const TIER_NEED={
  csv:1, push:2, tax:2, consensus:2,
  autoStop:3, trailing:3, aiFull:3,
  surge:4, accum:4, backtest:4,
};
/* ══ [v11.6] 서버가 알려 주기 전까지는 잠그지 않는다 ═══════════════════════
   [무엇이 잘못됐나] _tier 의 처음 값이 free 였다. 그런데 서버 응답이 오기 전
   (앱을 막 켰을 때), 인터넷이 끊겼을 때, 로그인하지 않았을 때도 모두 free 다.
   그러면 Pro 를 쓰던 사람이 지하철에서 앱을 켰을 때 관심종목이 20개로 잠긴다.
   내 잘못이 아닌 이유로 기능이 막히는 것은 나쁜 경험이다.
   [고침] '아직 모름' 상태를 따로 둔다. 모르는 동안에는 한도를 걸지 않고,
   서버가 알려 준 뒤부터 적용한다. 마지막으로 받은 등급은 이 브라우저에
   기억해 두었다가 다음에 켤 때 곧바로 쓴다(서버 값이 오면 덮어쓴다).
   [이래도 되나] 이 앱은 요금을 받지 않는다. 잠금은 '이런 것도 있다'를 알리는
   장치이지 방어벽이 아니다. 확실하지 않을 때는 열어 두는 편이 맞다. */
var _tier={tier:'free', lv:0, until:null, expired:false, known:false};
try{
  const _c=JSON.parse(localStorage.getItem('tierCache')||'null');
  if(_c&&typeof _c.lv==='number'&&(!_c.until||_c.until>Date.now())){
    _tier={tier:_c.tier||'free', lv:_c.lv, until:_c.until||null, expired:false, known:true};
  }
}catch(e){}
function tierSet(p){
  try{
    if(!p||typeof p!=='object')return;
    if(p.tier==null&&p.lv==null)return;
    const prevLv=_tier.known?_tier.lv:-1;
    const lv=Math.max(0,Math.min(TIERS.length-1, p.lv!=null?+p.lv:TIERS.findIndex(t=>t.k===p.tier)));
    _tier={tier:TIERS[lv].k, lv, until:p.until||null, expired:!!p.expired, known:true,
      at:p.at||_tier.at||null, from:p.from||_tier.from||null};
    /* 다음에 앱을 켤 때 곧바로 쓰도록 기억해 둔다 — 서버 값이 오면 덮어쓴다 */
    try{ localStorage.setItem('tierCache',JSON.stringify({tier:_tier.tier,lv,until:_tier.until})); }catch(e){}
    try{ if(currentView==='tier')renderTierView(); else renderTierCard(); }catch(e){}
    try{ paintTierBadge(); }catch(e){}
    /* ══ [v11.8] 등급이 바뀌면 보고 있던 화면도 다시 그린다 ═══════════════════
       예전에는 등급 카드와 배지만 갱신했다. 그래서 쿠폰을 등록해 Pro 가 되어도
       그 순간 보고 있던 화면(고급 서비스·세금 리포트 등)은 잠긴 채로 남았고,
       다른 메뉴에 갔다 돌아와야 풀렸다. "코드를 넣었는데 그대로네?"로 보인다.
       등급이 실제로 달라졌을 때만 다시 그린다(같은 값이면 헛일을 하지 않는다). */
    if(prevLv!==lv){
      /* ══ [v12.4] 멤버십 화면에서는 showView 로 되돌리지 않는다 ═══════════════
         showView 는 화면을 처음부터 다시 그린다. 그런데 멤버십 화면은 바로 위에서
         이미 renderTierView() 로 새로 그린 뒤다. 여기서 showView 를 또 부르면
         requestAnimationFrame 으로 미뤄진 그리기가 나중에 실행되며 방금 그린
         것을 덮는데, 그때 쓰는 값이 옛 상태라 한도가 되돌아갔다.
         (Pro 로 올려도 화면에 20 이 그대로 남던 이유다)
         다른 화면은 잠금 해제를 반영해야 하므로 그대로 다시 그린다. */
      try{
        if(typeof currentView!=='undefined'&&currentView!=='tier'
           &&typeof showView==='function')showView(currentView);
      }catch(e){}
    }
  }catch(e){}
}
function tierLv(){ return _tier.lv||0; }
function tierKey(){ return _tier.tier||'free'; }
function tierInfo(){ return TIERS[tierLv()]||TIERS[0]; }
/* ══ [v12.4] '모름' 상태를 잘못 다뤄 Free 가 무제한으로 보이던 문제 ═══════════
   [무엇이 잘못됐나] 서버 답을 못 받았을 때(known=false) 한도를 무제한으로
   돌려주도록 했다. 인터넷이 끊겼을 때 기능이 잠기지 않게 하려던 것이었는데,
   ① 서버가 tier 를 안 보내는 경우(옛 워커·응답 누락)
   ② 아직 로그인 전
   에도 계속 무제한이 유지됐다. 그래서 화면에 'Free · 관심종목 6/무제한'
   같은 앞뒤가 안 맞는 표시가 나왔다.
   [고침] 두 가지를 나눈다.
     · 실제 동작(막을지 말지)  → 모르면 막지 않는다(예전 의도 유지)
     · 화면에 적는 숫자        → 언제나 지금 등급의 실제 한도를 적는다
   그래서 Free 면 화면에는 반드시 '20'이 적히고, 서버 답을 못 받은 잠깐 동안만
   실제로는 막지 않는다. 보이는 것과 적히는 것이 어긋나지 않는다. */
function tierKnown(){ return !!_tier.known; }
/* 화면 표기용 — 지금 등급의 실제 한도. '모름'이어도 숫자를 그대로 적는다. */
function tierCap(key){ const a=TIER_LIMITS[key]; return a?a[tierLv()]:INF; }
function tierAllow(feat){
  if(!tierKnown())return true;             // 모를 때는 막지 않는다
  const need=TIER_NEED[feat]; return need==null?true:tierLv()>=need;
}
function tierLimit(key){
  if(!tierKnown())return INF;              // 모를 때는 막지 않는다
  return tierCap(key);
}
/* 이 기능·한도를 열려면 어느 등급이 필요한가 */
function tierNeedName(feat){ const n=TIER_NEED[feat]; return n==null?null:(TIERS[n]||{}).n; }
function tierNextFor(key,want){
  const a=TIER_LIMITS[key]; if(!a)return null;
  for(let i=tierLv()+1;i<a.length;i++){ if(a[i]>=want||a[i]===INF)return TIERS[i]; }
  return null;
}

/* ══════════════════════════════════════════════════════════════════════════════
   [v11.3] 쿠폰 관리 — 설정 > 관리자 패널
   ─────────────────────────────────────────────────────────────────────────────
   토큰은 이미 있는 admTok 입력칸을 그대로 쓴다. 관리 창구를 둘로 나누면
   어느 쪽에 넣었는지 헷갈리기만 한다.
   발급한 코드는 화면에 그대로 띄우고 '전체 복사'를 둔다 — 카톡으로 옮겨
   붙이는 것이 실제 사용 흐름이기 때문이다.
   ══════════════════════════════════════════════════════════════════════════════ */

/* ══════════════════════════════════════════════════════════════════════════════
   [v13.0] 관리자 화면
   ─────────────────────────────────────────────────────────────────────────────
   설정 안에 흩어져 있던 관리 기능을 한 화면으로 모았다.
   [잠금] 들어오면 먼저 암호를 묻는다. 암호는 서버의 NXT_ADMIN_TOKEN 이며,
   맞는지는 서버에 물어 확인한다(화면에서 비교하면 코드만 봐도 뚫린다).
   확인된 암호는 이 창을 닫을 때까지만 기억한다(sessionStorage).
   [알림 보내기] 코드를 발급한 뒤 상대에게 카톡·메일로 알리는 것과 별개로,
   앱을 열었을 때 안내창이 뜨도록 서버에 쪽지를 남긴다. 상대가 놓치지 않는다.
   ══════════════════════════════════════════════════════════════════════════════ */

/* ══════════════════════════════════════════════════════════════════════════════
   [v13.0] 이용권 안내 받기
   ─────────────────────────────────────────────────────────────────────────────
   관리자가 코드를 보내면 서버에 쪽지가 남는다. 로그인한 뒤 한 번 확인해,
   있으면 안내창을 띄운다. 창에서 바로 등록까지 끝낼 수 있게 코드를 채워 둔다.
   한 번 보여 준 쪽지는 서버에서 지운다(같은 안내가 계속 뜨면 성가시다).
   ══════════════════════════════════════════════════════════════════════════════ */
/* [v13.0] 저장은 붙여서, 표시는 4-5-5-5-1 로 — 서버와 같은 규칙 */
function cpnPretty(raw){
  const c=String(raw||'').toUpperCase().replace(/[^A-Z0-9]/g,'');
  return c.length===20?`${c.slice(0,4)}-${c.slice(4,9)}-${c.slice(9,14)}-${c.slice(14,19)}-${c.slice(19,20)}`:String(raw||'');
}
async function checkTierInbox(){
  try{
    if(!currentUser)return;
    const acc=accounts()[currentUser]; if(!acc||!acc.pass)return;
    const r=await fetch('/api/coupon',{method:'POST',headers:{'content-type':'application/json'},
      body:JSON.stringify({act:'inbox',id:currentUser,pass:acc.pass,read:1})});
    const j=await r.json();
    if(!j||!j.ok||!j.msg)return;
    showTierGift(j.msg);
  }catch(e){}
}
/* [v16.7] 등급이 바뀐 뒤 화면을 실제로 다시 그린다 — 멤버십 화면에서 코드를
   등록해도 카드가 그대로였던 원인(뷰 렌더러를 부르지 않았다). */
function tierRefreshUI(){
  try{ if(typeof renderTierCard==='function')renderTierCard(); }catch(e){}
  try{ if(currentView==='tier'&&typeof renderTierView==='function')renderTierView(); }catch(e){}
  try{ if(typeof renderMyDataView==='function'&&currentView==='mydata')renderMyDataView(); }catch(e){}
  try{ if(typeof paintTierBadge==='function')paintTierBadge(); }catch(e){}
  try{ if(typeof renderHeaderTier==='function')renderHeaderTier(); }catch(e){}
}
function showTierGift(m){
  const t=TIERS.find(x=>x.k===m.tier)||TIERS[0];
  const dur=m.days>0?`${m.days}일`:'기간 제한 없음';
  /* ══ [v17.0] 여기로 들어온 이용권도 MY 데이터에 남긴다 ═════════════════════
     이벤트 참여 경로에만 기록을 남기고 있어서, 문의·관리자 발급으로 받은
     이용권은 상세를 열어도 코드가 없었다(실기 사진). 코드 원문까지 보관한다. */
  try{
    if(m&&m.code&&typeof rewardLogAdd==='function'){
      const dup=(rewardLogGet()||[]).some(x=>x.code&&String(x.code)===String(m.code));
      if(!dup)rewardLogAdd({ kind:'tier', label:t.n+' 이용권 '+dur,
        src:m.from||m.memo||'관리자 발급', code:m.code||null });
    }
  }catch(e){}
  openLiteGate('이용권이 도착했어요',`
    <div class="gift" style="--tc:${t.c}">
      <div class="gift-badge">${t.n}</div>
      <p class="gift-lead"><b>${t.n} 이용권</b>이 발급되었습니다.<br>아래 버튼을 누르면 바로 적용돼요.</p>
      ${m.memo?`<div class="gift-memo">${htmlEsc(m.memo)}</div>`:''}
      <div class="gift-row"><span>이용 기간</span><b>${dur}</b></div>
      <div class="gift-code" id="giftCode">${htmlEsc(cpnPretty(m.code))}</div>
      <button type="button" class="mc-btn primary" id="giftGo" style="--nc:${t.c}">지금 등록하기</button>
      <button type="button" class="mc-btn" id="giftCopy">코드 복사</button>
      <p class="gift-note">나중에 하시려면 <b>멤버십 → 이용권 코드 입력</b>에서 이 코드를 넣으시면 됩니다.</p>
    </div>`);
  const cp=$('giftCopy');
  if(cp)cp.onclick=()=>{
    try{ navigator.clipboard&&navigator.clipboard.writeText(m.code); }catch(e){}
    toast('ok','코드를 복사했어요','');
  };
  const go=$('giftGo');
  if(go)go.onclick=async()=>{
    const acc=accounts()[currentUser]; if(!acc)return;
    go.disabled=true; go.textContent='등록 중…';
    try{
      const r=await fetch('/api/coupon',{method:'POST',headers:{'content-type':'application/json'},
        body:JSON.stringify({act:'redeem',id:currentUser,pass:acc.pass,
          code:String(m.code).replace(/[^A-Za-z0-9]/g,'')})});
      const j=await r.json();
      if(j&&j.ok){
        tierSet(j); closeLiteGate();
        toast('ok',j.msg||'등급이 바뀌었습니다',TIERS[tierLv()].d);
        tierRefreshUI();
        try{ rewardLogMarkUsed(String(m.code).replace(/[^A-Za-z0-9]/g,'')); }catch(e){}
      }else{
        toast('warn','등록하지 못했어요',(j&&j.msg)||'멤버십 화면에서 다시 시도해 주세요');
      }
    }catch(e){ toast('warn','연결에 실패했어요','네트워크 상태를 확인해 주세요'); }
    finally{ const g=$('giftGo'); if(g){ g.disabled=false; g.textContent='지금 등록하기'; } }
  };
}

function admTokGet(){ try{ return sessionStorage.getItem('admtok')||''; }catch(e){ return ''; } }
function admTokSet(v){ try{ v?sessionStorage.setItem('admtok',v):sessionStorage.removeItem('admtok'); }catch(e){} }
/* ══ [v15.7] 이벤트 — 참여만 해도 혜택이 바로 지급되는 페이지 ═══════════════════
   실서비스 이벤트 페이지 문법(토스·증권사 공통): 상태 필(진행중 D-n/마감),
   혜택 배지, 기간, 참여 진행률, 큼직한 참여 버튼, 참여 완료 상태. */
/* ══ [v15.9] 이벤트 상품 카탈로그 114종 ═══════════════════════════════════════
   [v16.1] 주식 프리셋(국내·미국·ETF)은 카탈로그에서 뺐다 — 주식 지급은 아래
   수동 선택기(국내·해외 전 종목 검색 + 수량 자유 입력)가 유일한 길이다.
   지급 방법(계열별):
   · tier   — 참여 순간 서버가 계정 등급을 직접 부여(쿠폰 등록과 동일 엔진)
   · cash   — 서버 확정 → 활성 계좌 원화 예수금에 즉시 입금·저장
   · usd    — 서버 확정 → 활성 계좌 달러 예수금에 즉시 입금·저장
   · stock  — 서버 확정 → 보유종목에 해당 수량을 평단 0원(증여)으로 추가
   · coupon — 서버가 1회용 쿠폰 코드를 실제 발급(유효 90일) → 표시·복사·선물 */
