let _evtItems=null,_evtBusy=false,_evtTab='on';
const EVT_BEN=(ev)=>{
  const nm={basic:'Basic',plus:'Plus',pro:'Pro',max:'Max'}[ev.tier]||ev.tier;
  if(ev.type==='tier')return {ic:'🎟',txt:nm+' 이용권 '+ev.days+'일',cls:'tier'};
  if(ev.type==='coupon')return {ic:'🎫',txt:nm+' '+ev.days+'일 쿠폰 코드',cls:'coupon'};
  if(ev.type==='stock')return {ic:'📈',txt:(ev.stockName||ev.code)+' '+ev.qty+'주',cls:'stock'};
  if(ev.type==='usstock')return {ic:'🇺🇸',txt:(ev.usName||ev.name||ev.ticker)+' '+(ev.usQty||ev.qty)+'주',cls:'usstock'};
  if(ev.type==='lucky')return {ic:'🎰',txt:(ev.cur==='usd'?('$'+Number(ev.min).toLocaleString()+'~$'+Number(ev.max).toLocaleString()):(Number(ev.min).toLocaleString()+'~'+Number(ev.max).toLocaleString()+'원'))+' 랜덤',cls:'lucky'};
  if(ev.type==='bundle')return {ic:'🎁',txt:'종합 패키지 '+((ev.items||[]).length)+'종',cls:'bundle'};
  if(ev.type==='watchpack')return {ic:'📋',txt:(ev.packName||'관심종목 팩')+' '+((ev.codes||[]).length)+'선',cls:'watchpack'};
  if(ev.type==='usd')return {ic:'💵',txt:'$'+Number(ev.amount).toLocaleString()+' 달러 예수금',cls:'usd'};
  return {ic:'💰',txt:Number(ev.amount).toLocaleString()+'원 예수금',cls:'cash'};
};
/* [v16.0] 혜택 집행기(클라이언트 몫) — bundle 이 항목별로 재사용한다 */
async function evtApplyBenefit(b2,ben){
  if(b2.type==='tier'){
    /* [v16.7] 자동 등급 부여 폐지 — 코드를 주고 등록은 사용자가 직접 */
    if(b2.code){
      try{showTierGift({tier:b2.tier,days:b2.days,code:b2.code,memo:'이벤트 참여 혜택'});}catch(e){}
      toast('ok','🎟 이용권 코드가 발급되었습니다','등록하면 등급이 적용돼요 · MY 데이터에 보관됩니다');
    }else{
      tierSet(b2);
      toast('ok','🎟 이용권이 적용되었습니다',(ben?ben.txt:''));
    }
  }else if(b2.type==='stock'){
    const ex=holdings.find(h=>h.code===b2.code&&!h.us);
    if(ex){ ex.avg=Math.round((ex.avg*ex.qty)/(ex.qty+b2.qty)); ex.qty+=b2.qty; }
    else holdings.push({code:b2.code,qty:b2.qty,avg:0});
    try{ensureStock(b2.code,b2.name||'','');}catch(e){}
    saveState();
    toast('ok','📈 주식이 지급되었습니다',(b2.name||b2.code)+' '+b2.qty+'주 — 내 계좌 보유종목에서 확인하세요');
  }else if(b2.type==='usstock'){
    const tk=String(b2.ticker||'').toUpperCase();
    const ex=holdings.find(h=>h.code===tk&&h.us);
    if(ex){ ex.avg=+( (ex.avg*ex.qty)/(ex.qty+b2.qty) ).toFixed(2); ex.qty+=b2.qty; }
    else holdings.push({code:tk,qty:b2.qty,avg:0,us:1,fxAvg:0});
    saveState();
    toast('ok','🇺🇸 미국 주식이 지급되었습니다',(b2.name||tk)+' '+b2.qty+'주 — 해외 보유종목에서 확인하세요');
  }else if(b2.type==='coupon'){
    try{navigator.clipboard&&navigator.clipboard.writeText(b2.code).catch(()=>{});}catch(e){}
    await askConfirm('🎫 쿠폰 코드가 발급되었습니다',
      b2.code+'\n\n'+({basic:'Basic',plus:'Plus',pro:'Pro',max:'Max'}[b2.tier]||b2.tier)+' '+b2.days+'일 이용권 쿠폰 · 유효 90일\n지금 등록하거나, 복사해 두었다가 선물할 수 있어요. (자동 복사됨)',
      {okLabel:'확인'});
    toast('ok','🎫 쿠폰 발급 완료','멤버십 화면의 쿠폰 등록에서 사용할 수 있습니다');
  }else if(b2.type==='usd'){
    usdCash=+(usdCash||0)+(+b2.amount||0); saveState();
    toast('ok',b2.lucky?'🎰 랜덤 박스 당첨!':'💵 달러 예수금 지급 완료','$'+Number(b2.amount).toLocaleString()+' 이 활성 계좌에 입금되었습니다');
  }else if(b2.type==='watchpack'){
    let added=0;
    (b2.codes||[]).forEach(c=>{ if(!watchlist.includes(c)){watchlist.push(c);added++;} try{ensureStock(c,'','');}catch(e){} });
    saveState();
    toast('ok','📋 관심종목 팩 담기 완료',(b2.name||'팩')+' — '+added+'종목이 관심종목에 추가되었습니다');
  }else if(b2.type==='cash'){
    cash=Math.floor(+cash||0)+Math.floor(+b2.amount||0); saveState();
    toast('ok',b2.lucky?'🎰 랜덤 박스 당첨!':'💰 예수금 지급 완료',Number(b2.amount).toLocaleString()+'원이 활성 계좌에 입금되었습니다');
  }
}
/* ══ [v16.2] MY 데이터 — 상품 획득·응모 자동 기록(계정별 로컬 보관) ═══════════════
   쿠폰 코드처럼 "안내창이 닫히면 끝"이던 정보를 영구 보관한다. */
function rewardLogKey(){ return pkey('rewardLog'); }
function rewardLogGet(){ try{ return JSON.parse(localStorage.getItem(rewardLogKey())||'[]')||[]; }catch(e){ return []; } }
function rewardLogAdd(rec){
  try{
    const l=rewardLogGet();
    l.unshift({ ...rec, at:Date.now() });
    localStorage.setItem(rewardLogKey(), JSON.stringify(l.slice(0,200)));
  }catch(e){}
}
/* [v16.7] 등록을 마친 코드는 기록에도 '사용함'으로 남긴다 */
function rewardLogMarkUsed(codeRaw){
  const norm=(v)=>String(v||'').replace(/[^A-Za-z0-9]/g,'').toUpperCase();
  const key=norm(codeRaw); if(!key)return;
  try{
    const l=rewardLogGet();
    let hit=false;
    l.forEach(r=>{ if(r.code&&norm(r.code)===key){ r.used=1; r.usedAt=Date.now(); hit=true; } });
    if(hit)localStorage.setItem(rewardLogKey(),JSON.stringify(l));
  }catch(e){}
  try{ if(currentView==='mydata')renderMyDataView(); }catch(e){}
}
/* 기록 하나를 눌렀을 때 — 코드·발급 시점·사용 여부·바로 등록까지 */
async function myDataDetail(i){
  const l=rewardLogGet(); const r=l[i]; if(!r)return;
  const NM={tier:'이용권',coupon:'쿠폰 코드',cash:'원화 예수금',usd:'달러 예수금',
    stock:'국내 주식',usstock:'해외 주식',watchpack:'관심종목 팩',entry:'응모 접수',bundle:'패키지'};
  const when=new Date(r.at).toLocaleString('ko-KR');
  const rows=[
    ['상품',r.label||'—'],
    ['종류',NM[r.kind]||r.kind||'—'],
    ['획득 경로',r.src||'—'],
    ['획득 시각',when]
  ];
  if(r.amount)rows.push(['금액',(r.kind==='usd'?'$':'')+Number(r.amount).toLocaleString()+(r.kind==='usd'?'':'원')]);
  /* ══ [v17.0] 상세창 재구성 ══════════════════════════════════════════════════
     · 코드가 있으면 큰 코드 박스 + 상태 배지 + 등록/복사
     · 코드가 없는 유형(예수금·주식·응모)은 "코드 없는 상품"임을 분명히 알린다
     · 옛 기록(코드를 안 남기던 시절)은 어디서 찾는지 안내한다 */
  const IC={tier:'🎟',coupon:'🎫',cash:'💰',usd:'💵',stock:'📈',usstock:'🇺🇸',watchpack:'📋',entry:'📮',bundle:'🎁'};
  const CODELESS=['cash','usd','stock','usstock','watchpack','entry','bundle'];
  const head=`<div class="mdd-head">
      <div class="mdd-ic">${IC[r.kind]||'🎁'}</div>
      <div class="mdd-t"><b>${htmlEsc(r.label||'—')}</b>
        <span>${htmlEsc(NM[r.kind]||r.kind||'')}</span></div>
      ${r.code?`<span class="mdd-st ${r.used?'used':'new'}">${r.used?'사용 완료':'미사용'}</span>`:''}
    </div>`;
  let codeBox='';
  if(r.code){
    codeBox=`<div class="mdd-codebox">
        <span class="mdd-ck">이용권 코드</span>
        <b class="num" id="mddCode">${htmlEsc(r.code)}</b>
        <i>${r.used?'이미 등록에 사용한 코드입니다':'멤버십 → 이용권 코드 입력에서 등록하세요'}</i>
      </div>
      <div class="mdd-acts">
        ${r.used?'':'<button type="button" class="tqx-btn primary" id="mddGo">지금 등록하기</button>'}
        <button type="button" class="tqx-btn" id="mddCopy">📋 코드 복사</button>
      </div>`;
  }else if(CODELESS.includes(r.kind)){
    codeBox=`<div class="mdd-note">이 상품은 <b>코드 없이 바로 지급</b>되는 유형입니다. 계좌·보유종목·관심종목에서 확인하실 수 있어요.</div>`;
  }else{
    codeBox=`<div class="mdd-note warn">이 기록에는 코드가 저장되어 있지 않습니다. 발급 안내창이나 메일·오픈채팅 대화에서 코드를 확인해 주세요.</div>`;
  }
  const html=head
    +`<div class="mdd-rows">${rows.map(([k,v])=>
      `<div class="mdd-r"><span>${htmlEsc(k)}</span><b>${htmlEsc(String(v))}</b></div>`).join('')}</div>`
    +codeBox;
  setTimeout(()=>{
    const c=$('mddCopy'); if(c)c.onclick=()=>{
      try{navigator.clipboard&&navigator.clipboard.writeText(r.code).catch(()=>{});}catch(e){}
      toast('ok','코드를 복사했습니다','멤버십 → 이용권 코드 입력에서 쓸 수 있어요');
    };
    const g=$('mddGo'); if(g)g.onclick=async()=>{
      const acc=accounts()[currentUser]; if(!acc){toast('warn','로그인이 필요합니다','');return;}
      g.disabled=true; g.textContent='등록 중…';
      try{
        const rr=await fetch('/api/coupon',{method:'POST',headers:{'content-type':'application/json'},
          body:JSON.stringify({act:'redeem',id:currentUser,pass:acc.pass,code:String(r.code).replace(/[^A-Za-z0-9]/g,'')})});
        const j=await rr.json();
        if(j&&j.ok){ tierSet(j); tierRefreshUI(); rewardLogMarkUsed(r.code);
          toast('ok',j.msg||'등급이 적용되었습니다',''); try{closeAsk&&closeAsk();}catch(e){}
          try{$('askOk')&&$('askOk').click();}catch(e){}
        } else toast('warn','등록하지 못했습니다',(j&&j.msg)||'');
      }catch(e){ toast('warn','서버 연결 실패',''); }
      finally{ const b=$('mddGo'); if(b){b.disabled=false;b.textContent='지금 등록하기';} }
    };
  },40);
  await askConfirm('획득 내역 상세',html,{html:true,okLabel:'닫기'});
}
function renderMyDataView(){
  const el=$('myDataBody'); if(!el)return;
  const l=rewardLogGet();
  if(!l.length){
    el.innerHTML='<div class="empty big"><i>🗂️</i><b>아직 기록이 없습니다</b><span>이벤트에 참여해 상품을 받으면 이곳에 자동으로 쌓여요.</span></div>';
    return;
  }
  const IC={tier:'🎟',cash:'💰',usd:'💵',stock:'📈',usstock:'🇺🇸',coupon:'🎫',watchpack:'📋',entry:'📮',bundle:'🎁'};
  el.innerHTML='<div class="md-list">'+l.map((r,i)=>{
    const d=new Date(r.at);
    const when=d.toLocaleDateString('ko-KR',{month:'long',day:'numeric'})+' '+d.toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit'});
    const code=r.code?`<div class="md-code"><span class="num">${htmlEsc(r.code)}</span>
      <button type="button" class="md-copy" data-code="${htmlEsc(r.code)}">복사</button></div>`:'';
    return `<div class="md-row" data-md="${i}" role="button" tabindex="0">
      <div class="md-ic">${IC[r.kind]||'🎁'}</div>
      <div class="md-b">
        <div class="md-t">${htmlEsc(r.label||'')}</div>
        <div class="md-s">${htmlEsc(r.src||'')} · ${when}${r.kind==='entry'?' · <b class="md-entry">응모 완료</b>':''}${r.code?(r.used?' · <b class="md-used">사용 완료</b>':' · <b class="md-new">미사용</b>'):''}</div>
        ${code}
      </div><div class="md-arrow">›</div></div>`;
  }).join('')+'</div>';
  el.querySelectorAll('.md-row[data-md]').forEach(row=>{
    row.onclick=(e)=>{ if(e.target.closest('.md-copy'))return; myDataDetail(+row.dataset.md); };
    row.onkeydown=(e)=>{ if(e.key==='Enter')myDataDetail(+row.dataset.md); };
  });
  el.querySelectorAll('.md-copy').forEach(b=>b.onclick=(e)=>{
    e.stopPropagation();
    try{navigator.clipboard&&navigator.clipboard.writeText(b.dataset.code).catch(()=>{});}catch(e){}
    toast('ok','복사되었습니다','멤버십 화면의 쿠폰 등록에서 사용할 수 있어요');
  });
}

async function renderEventView(){
  const el=$('eventList'); if(!el)return;
  if(!_evtItems&&!_evtBusy){
    _evtBusy=true;
    try{
      fnBump();
      const r=await fetch('/api/coupon',{method:'POST',headers:{'content-type':'application/json'},
        body:JSON.stringify({act:'evtpub',user:(typeof currentUser!=='undefined'&&currentUser)||''})});
      const j=await r.json();
      _evtItems=(j&&j.ok&&Array.isArray(j.items))?j.items:[];
    }catch(e){_evtItems=null;}
    finally{_evtBusy=false;}
    if(currentView==='event')renderEventView();
    return;
  }
  /* [v16.2] 진행 중 / 종료 탭 */
  const tabs=$('evtTabs');
  if(tabs&&!tabs._wired){tabs._wired=true;
    tabs.querySelectorAll('button').forEach(b=>b.onclick=()=>{_evtTab=b.dataset.et;
      tabs.querySelectorAll('button').forEach(x=>x.classList.toggle('on',x===b));
      renderEventView();});}
  const _all=_evtItems;
  /* [v16.5] 히어로 요약 — 진행 중 수·누적 참여·내 참여 */
  if(Array.isArray(_all)){
    const live=_all.filter(e=>!(e.endAt&&Date.now()>e.endAt));
    const set=(id,v)=>{const el=$(id); if(el)el.textContent=v;};
    set('ehOn',live.length.toLocaleString());
    set('ehJoin',_all.reduce((a,e)=>a+(+e.joined||0),0).toLocaleString());
    set('ehMine',_all.filter(e=>e.mine).length.toLocaleString());
  }
  const items=_all===null?null:_all.filter(ev=>{
    const ended=ev.endAt&&Date.now()>ev.endAt;
    return _evtTab==='end'?ended:!ended;
  });
  if(items===null){el.innerHTML='<div class="empty">이벤트를 불러오지 못했습니다.<br><button class="etf-more" id="evtRetry">다시 시도</button></div>';
    const b=$('evtRetry'); if(b)b.onclick=()=>{_evtItems=null;renderEventView();}; return;}
  if(!items.length){
    el.innerHTML=_evtTab==='end'
      ?'<div class="empty big"><i>🏁</i><b>종료된 이벤트가 없습니다</b><span>기간이 끝난 이벤트가 이곳에 보관돼요.</span></div>'
      :'<div class="empty big"><i>🎁</i><b>지금 진행 중인 이벤트가 없습니다</b><span>새 이벤트가 열리면 이곳에서 알려 드릴게요.</span></div>';
    return;}
  const now=Date.now();
  el.innerHTML=items.map(ev=>{
    const ben=EVT_BEN(ev);
    const ended=ev.endAt&&now>ev.endAt;
    const full=ev.maxJoin&&ev.joined>=ev.maxJoin;
    const dLeft=ev.endAt?Math.ceil((ev.endAt-now)/86400e3):null;
    const st=ended?['마감','end']:full?['정원 마감','end']:(dLeft!=null&&dLeft<=3)?['D-'+Math.max(0,dLeft),'hot']:['진행 중','on'];
    const prog=ev.maxJoin?Math.min(100,Math.round(ev.joined/ev.maxJoin*100)):null;
    const canJoin=!ended&&!full&&!ev.mine;
    return '<div class="evt-card '+ben.cls+(ev.mine?' joined':'')+'">'
      +'<div class="evt-top"><span class="evt-st '+st[1]+'">'+st[0]+'</span>'
      +(ev.mine?'<span class="evt-mine">✓ 참여 완료</span>':'')+'</div>'
      +'<div class="evt-tt">'+htmlEsc(ev.title)+'</div>'
      +(ev.desc?'<div class="evt-d">'+htmlEsc(ev.desc)+'</div>':'')
      +'<div class="evt-ben"><i>'+ben.ic+'</i><b>'+ben.txt+'</b><span>'+(ev.joinMode==='entry'?'응모 후 추첨':'즉시 지급')+'</span></div>'
      +(ev.mission?'<div class="evt-msn"><i>🎯</i><div><b>참여 조건</b><p>'+htmlEsc(ev.mission)+'</p></div></div>':'')
      +((ev.askFields&&ev.askFields.length)?'<div class="evt-req">'+ev.askFields.map(f=>'<span>'+((ASK_KIND[f.kind]||ASK_KIND.text).ic)+' '+htmlEsc(f.label)+(f.required?' *':'')+'</span>').join('')+'</div>':'')
      +'<div class="evt-meta">'
      +(ev.endAt?'<span>~ '+new Date(ev.endAt).toLocaleDateString('ko-KR',{month:'long',day:'numeric'})+'</span>':'<span>상시</span>')
      +'<span>·</span><span class="num">'+(ev.joined||0).toLocaleString()+'명 참여'
      +(ev.maxJoin?' / '+ev.maxJoin.toLocaleString()+'명 한정':'')+'</span></div>'
      +(prog!=null?'<div class="evt-prog"><i style="width:'+prog+'%"></i></div>':'')
      +'<button class="evt-go" data-evt="'+ev.id+'"'+(canJoin?'':' disabled')+'>'
      +(ev.mine?(ev.joinMode==='entry'?'응모 완료':'참여 완료'):ended?'마감된 이벤트':full?'정원 마감':(ev.joinMode==='entry'?'지금 응모하기':'지금 참여하고 받기'))+'</button></div>';
  }).join('');
  el.querySelectorAll('.evt-go[data-evt]:not([disabled])').forEach(b=>b.onclick=()=>evtJoin(b.dataset.evt));
}
async function evtJoin(id){
  if(typeof currentUser==='undefined'||!currentUser){toast('warn','로그인이 필요합니다','이벤트는 로그인 후 참여할 수 있어요');return;}
  const ev=(_evtItems||[]).find(x=>x.id===id); if(!ev)return;
  const ben=EVT_BEN(ev);
  const isEntry=ev.joinMode==='entry';
  if(!await askConfirm(isEntry?'이벤트 응모':'이벤트 참여',
    "'"+ev.title+"' — 혜택: "+ben.txt+(isEntry?' (응모 후 추첨)':' (즉시 지급)')+(ev.mission?'\n참여 조건: '+ev.mission:''),
    {okLabel:isEntry?'응모하기':'참여하기'}))return;
  let answer='',answers=null;
  const flds=Array.isArray(ev.askFields)?ev.askFields:[];
  if(flds.length){
    /* [v16.3] 여러 항목 제출 — 사진·파일·동영상 첨부까지 한 화면에서 */
    answers=await askForm(ev.askLabel||'참여 정보 제출',flds,
      {desc:ev.mission||'아래 항목을 채워 주세요',okLabel:isEntry?'응모하기':'제출하고 받기'});
    if(answers==null)return;
  }else if(ev.askLabel){
    answer=await askText(ev.askLabel,{desc:ev.mission||'참여 조건을 입력해 주세요'});
    if(answer==null)return;
    answer=String(answer).trim();
    if(!answer){toast('warn','입력이 필요합니다',ev.askLabel);return;}
  }
  try{
    fnBump();
    const r=await fetch('/api/coupon',{method:'POST',headers:{'content-type':'application/json'},
      body:JSON.stringify({act:'evtjoin',id,user:currentUser,answer,answers})});
    const j=await r.json();
    if(!j||!j.ok){toast('warn','참여하지 못했습니다',(j&&j.msg)||'잠시 후 다시 시도해 주세요');
      if(j&&(j.err==='dup'||j.err==='ended'||j.err==='full')){_evtItems=null;renderEventView();}
      return;}
    const b2=j.benefit||{};
    /* [v16.2] MY 데이터 자동 기록 — 코드가 있는 혜택은 코드 원문까지 보관 */
    const _log=(it)=>{ try{ const bn=EVT_BEN(it.type?it:ev);
      rewardLogAdd({ kind:it.type||ev.type, label:(it.type==='entry')?('응모: '+ev.title):bn.txt,
        src:'이벤트 · '+ev.title, code:it.code||null, amount:it.amount||null }); }catch(e){} };
    if(b2.type==='entry'){
      _log(b2);
      toast('ok','📮 응모가 접수되었습니다','발표·지급 소식은 이벤트 안내를 확인해 주세요');
      _evtItems=null; renderEventView(); return;
    }
    if(b2.type==='bundle'){
      (b2.items||[]).forEach(_log);
    }else{ _log(b2); }
    if(b2.type==='bundle'){
      for(const it of (b2.items||[]))await evtApplyBenefit(it,EVT_BEN(it));
      toast('ok','🎁 패키지 지급 완료',(b2.items||[]).length+'가지 혜택이 모두 지급되었습니다');
    }else{
      await evtApplyBenefit(b2,ben);
    }
    _evtItems=null; renderEventView();
  }catch(e){toast('warn','서버 연결 실패','잠시 후 다시 시도해 주세요');}
}

async function admCall(body){
  const r=await fetch('/api/coupon',{method:'POST',headers:{'content-type':'application/json'},
    body:JSON.stringify({...body,token:admTokGet()})});
  return r.json();
}
function renderAdminView(){
  const lock=$('admLock'), work=$('admWork');
  if(!lock||!work)return;
  if(!admTokGet()){ work.hidden=true; renderAdmLock(); return; }
  lock.innerHTML=''; work.hidden=false; renderAdmWork();
}
function renderAdmLock(){
  const el=$('admLock'); if(!el)return;
  el.innerHTML=`
  <div class="panel adm-lock">
    <div class="al-ico">🔒</div>
    <b>관리자 암호를 넣어 주세요</b>
    <span>서버에 설정한 <code>NXT_ADMIN_TOKEN</code> 값입니다.</span>
    <input type="password" id="alPass" placeholder="관리자 암호" autocomplete="off" aria-label="관리자 암호">
    <button type="button" class="mc-btn primary" id="alGo" style="--nc:var(--brand)">확인</button>
    <div class="al-msg" id="alMsg"></div>
  </div>`;
  const go=async()=>{
    const v=($('alPass')&&$('alPass').value||'').trim();
    if(!v){ $('alMsg').textContent='암호를 넣어 주세요'; return; }
    const b=$('alGo'); b.disabled=true; b.textContent='확인 중…';
    admTokSet(v);
    try{
      const j=await admCall({act:'list'});
      if(j&&j.ok){ renderAdminView(); return; }
      admTokSet('');
      $('alMsg').textContent=(j&&j.err==='forbidden')?'암호가 맞지 않습니다':'확인하지 못했습니다. 잠시 후 다시 시도해 주세요';
    }catch(e){ admTokSet(''); $('alMsg').textContent='서버에 연결하지 못했습니다'; }
    finally{ const b2=$('alGo'); if(b2){ b2.disabled=false; b2.textContent='확인'; } }
  };
  const btn=$('alGo'); if(btn)btn.onclick=go;
  const ip=$('alPass');
  if(ip){ ip.onkeydown=(e)=>{ if(e.key==='Enter')go(); }; setTimeout(()=>ip.focus(),100); }
}
